INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0c3dac7d-c51b-5cfc-a5fa-a0aab8bc079d', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 10, 10, 'ሦስተኛው ለዘኩር ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('4c847c76-0686-57c1-aa0a-55b14ff9896d', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 11, 11, 'አራተኛው ለይጽሪ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('cfad9d81-70d4-5f16-ade7-4150dc37dd18', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 12, 12, 'አምስተኛው ለናታንያስ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ።'),
  ('1ccd6d82-0ee5-5d79-ad49-fe2e60720f73', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 13, 13, 'ስድስተኛው ለቡቅያ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('7ec67344-8d8d-5542-a7f6-f5ca44aef8c6', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 14, 14, 'ሰባተኛው ለይስርኤል ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('b633d49c-8a62-5fd4-a685-dbfaa768b26f', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 15, 15, 'ስምንተኛው ለኢያስያ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('1165d56c-d5cd-5d4e-af2e-e27437c4fbbf', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 16, 16, 'ዘጠነኛው ለማታንያስ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('ab9a370c-b8d8-5f4b-ac92-a6f23fb39243', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 17, 17, 'ዐሥረኛው ለሰሜኢ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('19e0c4d5-9c19-52ec-a01f-d8a4ad5a0d95', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 18, 18, 'ዐሥራ አንደኛው ለዓዛርኤል ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('bf1ca388-994d-51d6-ac83-4ddae6fdf4c7', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 19, 19, 'ዐሥራ ሁለተኛው ለኢሰብያ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('0b0f87a6-625b-5419-a1cb-33ede32484d2', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 20, 20, 'ዐሥራ ሦስተኛው ለሱባኤል ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('426b7490-7a74-547d-a1b3-b616f9003d48', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 21, 21, 'ዐሥራ አራተኛው ለማታትያስ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('c41be9b5-3601-5d71-af01-91851f99a007', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 22, 22, 'ዐሥራ አምስተኛው ለኢየሪሙት ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('445fac7b-27f3-5e1c-ab61-d07d7af2468e', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 23, 23, 'ዐሥራ ስድስተኛው ለሐናንያ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('6c2417c0-1697-511d-a5b8-ac960be7ba64', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 24, 24, 'ዐሥራ ሰባተኛው ለዮስባቃጥ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('002cbb8a-b543-57dd-a5da-bbb93b9ebdbd', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 25, 25, 'ዐሥራ ስምንተኛው ለሐናኒ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('5ab9cb37-267a-5a88-a32b-9bc30f93b2d4', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 26, 26, 'ዐሥራ ዘጠነኛው ለማኤላቲ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('0d9cc35f-46cf-5c67-ab95-da1c6b14f682', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 27, 27, 'ሃያኛው ለኤልያታ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('233ea74c-ec52-5c3f-ada6-17b5ce9d939e', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 28, 28, 'ሃያ አንደኛው ለኦትሪ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('c6555cbf-2aa4-5143-a1f0-19844082f061', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 29, 29, 'ሃያ ሁለተኛው ለጌዶላቲ ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('de675110-dbaf-5c7e-abd9-6628a2928712', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 30, 30, 'ሃያ ሦስተኛው ለመሐዝዮት ለልጆቹም፥ ለወንድሞቹም፥ ለዐሥራ ሁለቱ፤'),
  ('f12b6f3f-214a-555d-a08d-a56eb0fb94fa', '1b30742f-b6be-5f5c-ae89-6b568dd9caa6', '9034c6f7-a3b2-5286-a968-23f1b32b8419', 31, 31, 'ሃያ አራተኛው ለሮማንቴዔዜር ለልጆቹም ለወንድሞቹም ለዐሥራ ሁለቱ ወጣ።'),
  ('ae3f2937-4def-5ef2-a00a-57cf7c26bbbe', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 1, 1, 'በረኞችም እንደዚህ ተመደቡ፤ ከቆሬያውያን ከአሳፍ ልጆች የቆሬ ልጅ ሜሱላም።'),
  ('77850c1b-5789-5d52-afd0-ba64c055059d', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 2, 2, 'ሜሱላምም ልጆች ነበሩት፤ በኵሩ ዘካርያስ፥ ሁለተኛው ይዲኤል፥ ሦስተኛው ዘባድያ፥ አራተኛው የትንኤል፤'),
  ('e14c516d-a17b-5a53-ace4-8f64c871757d', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 3, 3, 'አምስተኛው ኤላም፥ ስድስተኛው ይሆሐናን፥ ሰባተኛው ኤሊሆዔናይ።'),
  ('2292ec81-7d6c-52b4-a1a2-ce2b5948d020', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 4, 4, 'ዖቤድኤዶምም ልጆች ነበሩት፤ በኵሩ ሰማያ፥ ሁለተኛው ዮዛባት፥ ሦስተኛው ኢዮአስ፥ አራተኛው ሣካር፥ አምስተኛው ናትናኤል፤'),
  ('2ad002b8-9915-5ddd-a30f-edafdc2ee042', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 5, 5, 'ስድስተኛው ዓሚኤል፥ ሰባተኛው ይሳኮር፥ ስምንተኛው ፒላቲ ነበሩ፤ አምላኩ እግዚአብሔር ባርኮታልና።'),
  ('450f9b62-e2cd-5d16-ad20-5395db26bfe3', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 6, 6, 'ለልጁ ለሰማያም ከበኵር ልጁ ከሮሲ ልጆች ተወለዱለት፤ እነርሱም በአባታቸው ቤት የሠለጠኑ እጅግም ኀያላን ነበሩ።'),
  ('1c0ae7d8-6b56-54eb-aede-b338947c6ae1', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 7, 7, 'የሰማያ ልጆች ዖትኒ፥ ራፋኤል፥ ዖቤድ፥ ወንድሞቹም ኀያላን የነበሩ ኤልዛባድ፥ ኤሊሁ፥ ሰማክያ፥ ኢስባኮም።'),
  ('342450d9-c7fc-5dd3-ab42-2e00c77ac221', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 8, 8, 'እነዚህ ሁሉ የዖቤድኤዶም ልጆች ነበሩ፤ እነርሱም፥ ልጆቻቸውም፥ ወንድሞቻቸውም ለማገልገል ኀያላን የነበሩ የዖቤድኤዶም ልጆች ስድሳ ሁለት ነበሩ።'),
  ('2831af49-e34d-5658-acef-4620721c968c', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 9, 9, 'ለሜሱላምም ኀያላን የነበሩ ዐሥራ ስምንት ልጆችና ወንድሞች ነበሩት።'),
  ('d6fc06e9-ea7e-5107-a07f-7318057697f6', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 10, 10, 'ከሜራሪም ልጆች ለነበረው ለሖሳ ፊተኛውን በር የሚጠብቁ ልጆች ነበሩት፤ አለቃውም ሰምሪ ነበረ፤ በኵር አልነበረም፤ አባቱ ግን አለቃ አደረገው፤'),
  ('7f3263f7-9cf7-52ce-a511-892252e1696b', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 11, 11, 'ሁለተኛውም ኬልቅያስ፥ ሦስተኛውም ጥበልያ፥ አራተኛውም ዘካርያስ ነበረ፤ የሖሳ ልጆችና ወንድሞች ሁሉ ዐሥራ ሦስት ነበሩ።'),
  ('737f6bf1-433b-56ac-af44-eeea0521d9c3', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 12, 12, 'እንደ ወንድሞቻቸው ሆነው በእግዚአብሔር ቤት ያገለግሉ ዘንድ የበረኞች አለቆች በየሰሞናቸው የሚጠብቁ እነዚህ ነበሩ።'),
  ('7ca03632-d990-51f0-a284-3f23c9ecd398', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 13, 13, 'በበሩም ሁሉ ያገለግሉ ዘንድ በየአባቶቻቸው ቤቶች ታናሹና ታላቁ ተካክለው ዕጣ ተጣጣሉ።'),
  ('d020ec40-4e6b-5c38-adc5-81e6df194f1c', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 14, 14, 'የምሥራቁም በር ዕጣ ለሰሌምያና ለዘካርያ ወደቀ። የዮአስም ልጆች ለምልክያ ዕጣ ጣሉ፤ ዕጣውም በሰሜን በኩል ወጣ።'),
  ('a045e032-b6e4-5f14-a8ba-68111f669c9b', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 15, 15, 'ለአብዲዶም በደቡብ በኩል በዕቃ ቤት አንጻር ዕጣ ወጣ።'),
  ('c1761854-08f2-50f2-ac2c-8da1205f188b', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 16, 16, 'ለሶፊምና ለሖሳም በምዕራብ በኩል በዐቀበቱ መንገድ ባለው በሸለኬት በር በኩል ጥበቃ በጥበቃ ላይ ዕጣ ወጣ።'),
  ('a757da11-9fb2-5450-a4c1-af2134c060e5', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 17, 17, 'በምሥራቅ በኩል ለየዕለቱ ስድስት፥ በሰሜን በኩል ለየዕለቱ አራት፥ በደቡብ በኩል ለየዕለቱ አራት፥ ለዕቃ ቤትም ሁለት ሁለት ነበሩ።'),
  ('7cdfb17f-be9a-54c3-a535-4bec76068b03', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 18, 18, 'በኦሳም በምዕራብ በኩል በሸለኬት በር ሦስት፥ በምሥራቅ በኩል በዐቀበቱ በር ከጥበቃ በላይ ጥበቃ በቀን ስድስት፥ በሰሜን በኩል አራት፥ በደቡብ በኩል አራት፥ በዕቃ ቤቱ በኩል ተቀባባዮች ሁለት ሁለት፥ በምዕራብ በኩል አራት በመተላለፊያውም መንገድ ተቀባባዮች ሁለት ሁለት።'),
  ('0434113b-7688-5f0d-a761-6cbe2299d43e', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 19, 19, 'ከቆሬና ከሜራሪ ልጆች የነበሩ የበረኞች ሰሞን ይህች ናት።'),
  ('9e0cb051-1feb-5287-a021-5cca29b29ce7', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 20, 20, 'ወንድሞቻቸው ሌዋውያንም በእግዚአብሔር ቤት በሚሆኑ ቤተ መዛግብትና በንዋየ ቅድሳቱ ቤተ መዛግብት ላይ ተሹመው ነበር።'),
  ('f34b5c53-15af-51c8-a801-87aed1727442', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 21, 21, 'የለአዳን ልጆች፤ ለለአዳን የሆኑ የጌድሶናውያን ልጆች፥ ለጌድሶናዊው ለለአዳን የሆኑ፥ የአባቶች ቤቶች አለቆች ይሔኤሊ፤'),
  ('c5e4f4d8-2ce4-52bc-a0c0-bdc46c572c4c', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 22, 22, 'የይሔኤሊ ልጆች፤ በእግዚአብሔርም ቤት በሚሆኑ ቤተ መዛግብት ላይ የነበሩ ዜቶም፥ ወንድሙም ኢዮኤል ነበረ።'),
  ('fe6ff131-82bf-523e-a603-6ae0cc3aeb5e', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 23, 23, 'ከእንበረማውያን፥ ከይስዓራውያን፥ ከኬብሮናውያን፥ ከዑዝኤላውያን፤'),
  ('9cbac273-7bad-5a4f-a79a-ad3d1da66020', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 24, 24, 'የሙሴ ልጅ የጌርሳም ልጅ ሱባኤል በቤተ መዛግብት ላይ ተሾሞ ነበር።'),
  ('76c9d6f6-631c-54ee-a720-ca3a6e21911b', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 25, 25, 'ወንድሞቹም፤ ከአልዓዛር ልጁ ረዓብያ፥ ልጁም የሳያ፥ ልጁም ኢዮራም፥ ልጁም ዝክሪ፥ ልጁም ሰሎሚት ነበሩ።'),
  ('0a9d62fe-1bd2-5bd2-a104-597bb221591d', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 26, 26, 'ይህ ሰሎሚትና ወንድሞቹ፥ ንጉሡ ዳዊትና የአባቶች ቤቶች አለቆች፥ ሻለቆችና የመቶ አለቆች፥ የሠራዊቱም አለቆች፥ በቀደሱት በንዋየ ቅድሳቱ ቤተ መዛግብት ሁሉ ላይ ተሹመው ነበር።'),
  ('f55116a2-6eb4-5534-ad6e-6bfd151e5067', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 27, 27, 'የእግዚአብሔር ቤተ መቅደስ ሕንጻ ወደ ኋላ እንዳይል ዳዊት ከየሀገሩ በማረካቸውና በሰበሰባቸው በቀደሳቸውም ላይ የተሾሙ ናቸው።'),
  ('674c8291-3edd-5fdb-aacf-5732d5f8798f', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 28, 28, 'ነቢዩ ሳሙኤል፥ የቂስም ልጅ ሳኦል፥ የኔርም ልጅ አበኔር፥ የሶርህያም ልጅ ኢዮአብ የቀደሱት የእግዚአብሔር ንዋየ ቅድሳት ሁሉ ከሰሎሚትና ከወንድሞቹ እጅ በታች ነበረ።'),
  ('91553c74-c0ff-5dcb-af70-7533f260b13a', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 29, 29, 'ከይሰዓራውያን ከናንያና ልጆቹ ጻፎችና ፈራጆች ይሆኑ ዘንድ በውጭው ሥራ በእስራኤል ላይ ተሾመው ነበር።'),
  ('aead6910-5d52-52cd-a1a4-ac2898b4e133', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 30, 30, 'ከኬብሮናውያን ሐሳብያና ወንድሞቹ፥ ጽኑዓን የነበሩት ሺህ ሰባት መቶ ሰዎች፥ ለእግዚአብሔር ሥራ ሁሉ፥ ለንጉሡም አገልግሎት በዮርዳኖስ ማዶ በምዕራብ በኩል ባለው በእስራኤል ላይ ተሾመው ነበር።'),
  ('bb2fe090-03c1-572e-a27f-06fe2806201b', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 31, 31, 'ከኬብሮናውያንም እንደ አባቶች ቤቶች ትውልዶች የኬብሮናውያን አለቃ ኤርያስ ነበረ። ዳዊት በነገሠ በአርባኛው ዓመት ይፈልጉአቸው ነበረ፤ በእነርሱም መካከል በገለዓድ ኢያዜር ጽኑዓን ኀያላን ሰዎች ተገኙ፤'),
  ('5ec707db-9032-54cc-a4b5-5a6003f914c2', 'f8fe9554-de55-5fba-a987-dfe11fb3fa0e', 'd9f376be-5eff-5979-a556-4056a753590c', 32, 32, 'ወንድሞቹም ጽኑዓን የነበሩት የአባቶች ቤቶች አለቆች ሁለት ሺህ ሰባት መቶ ነበሩ። ንጉሡም ዳዊት በእግዚአብሔር ቃል ሁሉና በንጉሡ ትእዛዝ ሁሉ በሮቤላውያንና በጋዳውያን፥ በምናሴም ነገድ እኩሌታ ላይ ሹሞች አደረጋቸው።'),
  ('5b6bc2fd-1cf0-5a9e-a1bd-865d4def2193', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 1, 1, 'የእስራኤልም ልጆች የአባቶች ቤቶች አለቆችና የሺህ አለቆች፥ የመቶ አለቆችም ለንጉሡና ለንጉሡ ትእዛዝ ሁሉ የሚያገለግሉ ሹማምት እንደ ቍጥራቸው በየክፍላቸው እነዚህ ነበሩ። እነዚህም ክፍሎች እያንዳንዳቸው ሃያ አራት ሺህ ሆነው በዓመቱ ወራት ሁሉ በየወሩ ይገቡና ይወጡ ነበር።'),
  ('86aaa376-3b1a-5dfb-aa84-48e4cf7b1db3', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 2, 2, 'ለመጀመሪያው ወር በአንደኛው ክፍል ላይ የዘብድኤል ልጅ ያሶብአም ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('6577724e-9d05-592e-a6bf-876a2701a2c7', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 3, 3, 'እርሱም ከፋሬስ ልጆች ነበረ፤ ለመጀመሪያው ወር በጭፍራ አለቆች ሁሉ ላይ ተሾሞ ነበር።'),
  ('f3c76aa0-95f9-5f4c-a453-e0284442bbf2', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 4, 4, 'በሁለተኛውም ወር ክፍል ላይ የኤቲ ልጅ ዶድያ ነበረ፤ በእርሱም ክፍል ሚኮሎት አለቃ ነበር፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('6b6c0ee2-e837-54bd-a821-6e74002ef039', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 5, 5, 'በሦስተኛው ወር ሦስተኛው የጭፍራ አለቃ የካህኑ የዮዳሄ ልጅ በናያስ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሽህ ጭፍራ ነበረ።'),
  ('70c6d2b6-ecf3-5859-a9cc-f953f4245b8c', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 6, 6, 'ይህ በናያስ ከሠላሳው መካከል ኀያል ሆኖ በሠላሳው ላይ ነበረ፤ በእርሱም ክፍል ልጁ ዓሚዛባድ ነበረ።'),
  ('4ba7dcff-f5f2-5964-a208-8a928f6697c8', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 7, 7, 'በአራተኛው ወር አራተኛው አለቃ የኢዮአብ ወንድም አሳሄል ነበረ፤ ከእርሱም በኋላ ልጁ ዝባድያና ወንድሞቹ ነበሩ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('cd1001e5-39a8-5b65-ab7e-d144a8695689', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 8, 8, 'በአምስተኛው ወር አምስተኛው አለቃ ይዝራዊው ሰማኦት ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('c126711c-a9ff-5413-af60-8fd5c7fd3afe', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 9, 9, 'በስድስተኛውም ወር ስድስተኛው አለቃ የቴቁሓዊው የአቂስ ልጅ ኢይዝራኤል ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('f6605095-a760-5f9f-ac40-9c92431d324f', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 10, 10, 'በሰባተኛውም ወር ሰባተኛው አለቃ ከኤፍሬም ልጆች የሆነ ፍሎሳዊው ከሊስ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('5f05db82-b176-5318-ab68-3f06977fde5d', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 11, 11, 'በስምንተኛው ወር ስምንተኛው አለቃ ከዛራውያን የነበረው ኩሳታዊው ሲቦካይ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('2304440f-1f34-5ded-aedd-0eb5d994b139', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 12, 12, 'በዘጠነኛው ወር ዘጠነኛው አለቃ ከብንያማውያን የነበረው ዓናቶታዊው አቢዔዜር ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('0eb87179-5791-53db-a71c-920fd9aba8f9', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 13, 13, 'በዐሥረኛው ወር ዐሥረኛው አለቃ ከዛራውያን የነበረው ነጦፋዊው መዐርኢ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('4ce14f0a-e908-56ac-a765-945e91a30ff7', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 14, 14, 'በዐሥራ አንደኛው ወር ዐሥራ አንደኛው አለቃ ከኤፍሬም ልጆች የነበረው ፍርዓቶናዊው በናያስ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('a63a077e-e6f6-5cb7-a5e6-1aa114e75737', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 15, 15, 'በዐሥራ ሁለተኛው ወር ዐሥራ ሁለተኛው አለቃ ከጎቶንያል ወገን የነበረው ነጦፋታዊው ኬልዳይ ነበረ፤ በእርሱም ክፍል ሃያ አራት ሺህ ጭፍራ ነበረ።'),
  ('e1199c83-8239-5a9f-a21f-a7a3e289b63b', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 16, 16, 'በእስራኤልም ነገዶች ላይ እነዚህ ነበሩ፦ በሮቤላውያን ላይ የዝክሪ ልጅ ኤልያዛር አለቃ ነበረ፤ በስምዖናውያን ልጅ የመዓካ ልጅ ሰፋጥያስ ነበረ፤'),
  ('1086d97d-c5a1-538b-a39f-1a21e5ee00bb', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 17, 17, 'በሌዊ ወገን ላይ የቀሙኤል ልጅ አሰብያ፤ በአሮን ወገን ላይ ሳዶቅ፤'),
  ('f604b5c9-8c63-5cb7-a1df-1b396001fc11', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 18, 18, 'በይሁዳ ወገን ላይ ከዳዊት ወንድሞች ኤልያብ፤ በይሳኮር ወገን ላይ የሚካኤል ልጅ ዖምሪ፤'),
  ('268b6d2a-fa01-530b-a47a-e5c6dcceaa40', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 19, 19, 'በዛብሎን ወገን ላይ የአብድዩ ልጅ ሶማዒያስ፤ በንፍታሌም ወገን ላይ የዖዜሄል ልጅ ኢያሪሙት፤'),
  ('e354f0ee-6f0e-5f2c-a1c6-cc861dc0e2aa', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 20, 20, 'በኤፍሬም ልጆች ላይ የአዛዝያ ልጅ ሆሴዕ፤ በምናሴ ነገድ እኩሌታ ላይ የፈዳያ ልጅ ኢዩኤል፤'),
  ('a06957fe-c9e1-5fc9-a671-3ecdfc1ba64a', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 21, 21, 'በገለዓድ ምድር ባለው በምናሴ ነገድ እኩሌታ ላይ የዘብድያስ ልጅ ኢዮዳኢ፤ በብንያምም ልጆች ላይ የአበኔር ልጅ አሳሄል፤'),
  ('bbdaf981-2849-507c-a491-75e58c1ee083', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 22, 22, 'በዳን ወገንም ላይ የኢዮራም ልጅ ዓዛርኤል፤ እነዚህ የእስራኤል ነገዶች አለቆች ነበሩ።'),
  ('a9b641c1-d4d7-5ef0-ab7c-45c1aee73572', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 23, 23, 'ነገር ግን እግዚአብሔር ሕዝቡ እስራኤልን እንደ ሰማይ ከዋክብት ያበዛ ዘንድ ተናግሮ ነበርና ዳዊት ከሃያ ዓመት በታች የነበሩትን አልቈጠረም።'),
  ('41a4d168-fd90-5470-a272-78d761fad985', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 24, 24, 'የሶርህያ ልጅ ኢዮአብም መቍጠር ጀመረ፤ ነገር ግን አልፈጸመም፤ ስለዚህ ነገር በእስራኤል ላይ ቍጣ ሆነ፤ ቍጥራቸውም በንጉሡ በዳዊት የታሪክ መጽሐፍ አልተጻፈም።'),
  ('88b3b140-f4c5-514d-a71e-38f4eff5ff01', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 25, 25, 'በንጉሡም ቤተ መዛግብት ላይ የዓዳኤል ልጅ ዓዝሞት ሹም ነበረ፤ በሜዳውም፥ በከተሞቹም፥ በመንደሮቹም፥ በግንቦቹም ቤተ መዛግብት ላይ የዖዝያ ልጅ ዮናታን ሹም ነበረ፤'),
  ('568751d7-cb9a-59df-afd3-8c967df7502c', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 26, 26, 'መሬቱን በሚያበጃጁትና እርሻውን በሚያርሱት ላይ የክሉብ ልጅ ዔዝሪ ሹም ነበረ፤'),
  ('ed6e07f6-1a6a-5412-a10d-3907885e1cad', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 27, 27, 'በወይንም ቦታዎች ላይ ራማታዊው ሰሜኢ ሹም ነበረ፤ ለወይንም ጠጅ ዕቃ ቤት በሚሆነው በወይኑ ሰብል ላይ የሳፍኒው ዘብዲ ሹም ነበረ።'),
  ('c4701ab8-192c-5d8c-adae-701e7d0d8cad', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 28, 28, 'በቈላውም ውስጥ ባሉት በወይራውና በሾላው ዛፎች ላይ ጌድራዊው በአልሐናን ሹም ነበረ፤ በዘይቱም ቤቶች ላይ ኢዮአስ ሹም ነበረ፤'),
  ('cfc4baa3-7655-5b85-ae19-718e6ee9ea55', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 29, 29, 'በሳሮንም በሚሰማሩ ከብቶች ላይ ሳሮናዊው ሰጥራይ ሹም ነበረ፤ በሸለቆዎቹም ውስጥ በነበሩት ከብቶች ላይ የዓድላይ ልጅ ሳፋጥ ሹም ነበረ፤'),
  ('2f708ca7-e268-5bfd-a899-8a1cb094a849', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 30, 30, 'በግመሎቹም ላይ እስማኤላዊው ኤቢያስ ሹም ነበረ፤ በአህዮቹም ላይ ሜሮኖታዊው ኢያድስ ሹም ነበረ፤'),
  ('485cefd2-7282-5f98-a036-2c0237f58272', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 31, 31, 'በበጎችም ላይ አጋራዊው ያዚዝ ሹም ነበረ። እነዚህ ሁሉ በንጉሡ በዳዊት ሀብት ላይ ሹሞች ነበሩ።'),
  ('d2c8a37e-de44-5ae5-a063-5e47156f5465', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 32, 32, 'አስተዋይና ጸሓፊ የነበረው በአባቱ በኩል የዳዊት አጎት ዮናታን አማካሪ ነበረ፤ የአክማኔም ልጅ ኢያሔኤል ከንጉሡ ልጆች ጋር ነበረ፤'),
  ('df40220f-dba1-5b07-aaba-0e8b98e31feb', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 33, 33, 'አኪጦፌልም የንጉሡ አማካሪ ነበረ። አርካዊው ኩሲም የንጉሡ አንደኛ ወዳጅ ነበረ፤'),
  ('63a1ec44-0bcf-5841-ac50-95d2ce64c827', '3af79d81-8d21-5697-a7be-57bd5e5a834b', '4174627d-fa27-540b-af29-a3d593292d9e', 34, 34, 'ከአኪጦፌልም ቀጥሎ የበናያስ ልጅ ዮዳሔና አብያታር ነበሩ፤ ኢዮአብም የንጉሡ ሠራዊት አለቃ ነበረ።'),
  ('ce6c7c3f-e7d5-5aa1-a9fe-d262674896d5', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 1, 1, 'ዳዊትም የእስራኤልን አለቆች ሁሉና የፍርድ አለቆችን፥ ንጉሡንም በየተራ የሚጠብቁትን አለቆቹን፥ ሻለቆቹንም፥ የመቶ አለቆቹንም፥ በንጉሡና በልጆቹ ሀብትና ንብረት ላይ፥ መባ ባለበት ላይ የተሾሙትን ጃንደረቦችንም፥ ኀያላኑንና ሰልፈኞቹን ሁሉ ወደ ኢየሩሳሌም ሰበሰበ።'),
  ('f5bd32b5-b098-593b-ab1c-0abf599638e9', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 2, 2, 'ንጉሡም ዳዊት በጉባኤው መካከል ቆሞ እንዲህ አለ፥ “ወንድሞቼና ሕዝቤ ሆይ፥ ስሙኝ፤ ለእግዚአብሔር ለቃል ኪዳኑ ታቦትና ለአምላካችን እግር ማረፊያ የዕረፍት ቤት ለመሥራት አሳብ በልቤ መጣብኝ፤ ለዚህም ሥራ የሚያስፈልገውን አዘጋጅቻለሁ፤'),
  ('2209cf6d-de87-5ac9-a142-8193e592cf6e', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 3, 3, 'እግዚአብሔር ግን፦ የሰልፍ ሰው ነህና፥ ብዙ ደምም አፍስሰሃልና ስሜ የሚጠራበትን ቤት አትሠራም ብሎኛል።'),
  ('1bb1d7cd-c9d9-51da-a5b5-9f9aba5c0708', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 4, 4, 'ነገር ግን የእስራኤል አምላክ እግዚአብሔር በእስራኤል ላይ የዘለዓለም ንጉሥ እሆን ዘንድ ከአባቴ ቤት ሁሉ መርጦኛል፤ ይሁዳንም አለቃ ይሆን ዘንድ መርጦታል፤ ከይሁዳም ቤት የአባቴን ቤት መርጦአል፤ ከአባቴም ልጆች መካከል በእስራኤል ሁሉ ላይ ያነግሠኝ ዘንድ እኔን ሊመርጠኝ ወደደ።'),
  ('b88243e4-e89f-5571-a582-89015ca423ee', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 5, 5, 'እግዚአብሔርም ብዙ ልጆች ሰጥቶኛልና ከልጆቼ ሁሉ በእግዚአብሔር መንግሥት ዙፋን ላይ ተቀምጦ በእስራኤል ላይ ይነግሥ ዘንድ ልጄን ሰሎሞንን መርጦታል።'),
  ('57f8bfcb-dca9-5b69-a3ef-8199ed7a7f47', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 6, 6, 'እግዚአብሔርም እንዲህ አለኝ፦ ልጅ ይሆነኝ ዘንድ መርጬዋለሁና፥ እኔም አባት እሆነዋለሁና ልጅህ ሰሎሞን ቤቴንና አደባባዮቼን ይሠራል።'),
  ('310fb9bf-10c2-5d66-a33e-dfd76f93278d', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 7, 7, 'ትእዛዜንና ፍርዴንም መጠበቅ ቢችልና እንደ ዛሬው ቢጸና መንግሥቱን ለዘለዓለም አጸናዋለሁ።'),
  ('13491819-8fc3-582a-ab71-085353dd0be7', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 8, 8, 'አሁንም የእግዚአብሔር ጉባኤ እስራኤል ሁሉ እያዩ፥ አምላካችንም እየሰማ፥ ይህችን መልካሚቱን ምድር ትወርሱ ዘንድ፥ ለልጆቻችሁም ለዘለዓለም ታወርሱአት ዘንድ የአምላካችሁን የእግዚአብሔርን ትእዛዝ ሁሉ ጠብቁ፤ ፈልጉም።'),
  ('1af4bd97-18ee-5da3-a22a-63c2ef70ca4d', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 9, 9, '“አንተም ልጄ ሰሎሞን ሆይ፥ እግዚአብሔር ልብን ሁሉ ይመረምራልና፥ የነፍስንም አሳብ ሁሉ ያውቃልና የአባቶችህን አምላክ ዕወቅ፤ በፍጹም ልብና በነፍስህ ፈቃድም ተገዛለት፤ ብትፈልገው ታገኘዋለህ፤ ብትተወው ግን ለዘለዓለም ይተውሃል።'),
  ('88136127-7c66-5a39-a2f1-021bbe6f4fc5', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 10, 10, 'አሁንም፥ እነሆ፥ እግዚአብሔር ለመቅደስ የሚሆን ቤትን ትሠራ ዘንድ መርጦሃልና ጠንክረህ ፈጽመው።”'),
  ('7e2d3887-fe47-5b3a-a9b3-847ebc624177', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 11, 11, 'ዳዊትም ለመቅደሱ ወለል፥ ለቤቱም፥ ለቤተ መዛግብቱም፥ ለደርቡና ለውስጡም ጓዳዎች፥ ለስርየቱም መክደኛ መቀመጫ ምሳሌውን ለልጁ ለሰሎሞን ሰጠው።'),
  ('d05a196a-241e-56f6-a312-22ce0631e729', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 12, 12, 'ደግሞም ለእግዚአብሔር ቤት አደባባዮችና በዙሪያው ለሚሆኑ ጓዳዎች፥ ለእግዚአብሔርም ቤት ለሚሆኑ ቤተ መዛግብት፥ ለንዋየ ቅድሳቱም ለሚሆኑ ዕቃ ቤቶች፥ ለቀሩትም በመንፈሱ ላሰበው ሁሉ ምሳሌን ሰጠው።'),
  ('6e4ea247-ca62-58a0-a5a3-c3eb997ed3ec', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 13, 13, 'የካህናቱንና የሌዋውያኑንም ክፍላቸውን፥ በእግዚአብሔርም ቤት ለሚያገለግሉበት ሥራ ሁሉ፥ በእግዚአብሔርም ቤት ለሚያገለግሉበት ዕቃ ሁሉ፥ ለአገልግሎት ሁሉ ለሚሆነውም፥'),
  ('859dc712-e440-518b-aaef-098a67cf0f38', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 14, 14, 'ለወርቁ ዕቃ ወርቁን በሚዛን ሰጠው፤ ለአገልግሎት ሁሉ ለሚሆነውም ለብር ዕቃ ሁሉ ብሩን በሚዛን ሰጠው፤'),
  ('8541b585-dc8e-59c9-a5a8-ae06094ce648', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 15, 15, 'ለወርቁም መቅረዞችና ለቀንዲሎችም ወርቁን በየመቅረዙና በየቀንዲሉ በሚዛን ሰጠው፤ ለብሩም መቅረዞች እንደ መቅረዙ ሁሉ ሥራ ብሩን በየመቅረዙና በየቀንዲሉ በሚዛን ሰጠው፤'),
  ('12f61970-f396-587e-a781-d7d81fd989d7', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 16, 16, 'ዳግመኛም ለገጹ ኅብስት ገበታዎች ወርቁን በሚዛን ለገበታዎቹ ሁሉ፥ ብሩንም ለብሩ ገበታዎች እንደዚሁ ሰጠው፤'),
  ('0e476896-9e0e-56a5-ac31-8914028c0b75', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 17, 17, 'ለሥጋ ሜንጦዎቹና ለድስቶቹ፥ ለመጠጥ ቍርባን መቅጃዎቹም ጥሩውን ወርቅ፥ ለወርቁም ጽዋዎች ወርቁን በየጽዋው ሁሉ በሚዛን ሰጠው፤ ለብሩም ጽዋዎች ብሩን በየጽዋው በሚዛን ሰጠው።'),
  ('f6202c90-c70e-5fb8-aaa6-68b47cbfd2fe', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 18, 18, 'ለዕጣኑም መሠዊያ ጥሩውን ወርቅ በሚዛን፥ ክንፎቻቸውንም ዘርግተው የእግዚአብሔርን ቃል ኪዳን ታቦት የሸፈኑትን የኪሩቤልን የወርቅ ሰረገላ ምሳሌ አሳየው።'),
  ('7ff04873-3da5-5cd4-ae86-0c735e955f06', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 19, 19, 'ዕውቀት እንደ ተሰጠው የእግዚአብሔርን ቤት ይሠራ ዘንድ ዳዊት በእግዚአብሔር ሕግ የተጻፈውን ለልጁ ለሰሎሞን ሰጠው።'),
  ('7e1813bf-7f64-5e77-af42-bb0857ff7004', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 20, 20, 'ዳዊትም ልጁን ሰሎሞንን፥ “ጠንክር፤ ሰው ሁን፤ አይዞህ፥ አድርገውም፤ አምላኬ እግዚአብሔር ከአንተ ጋር ነውና አትፍራ፤ አትደንግጥም፤ ለእግዚአብሔርም ቤት አገልግሎት የሚሆነውን ሥራ ሁሉ እስክትፈጽም ድረስ እርሱ አይተውህም፤ አይጥልህምም። እነሆ፥ የእግዚአብሔር ቤት ሕንጻ ምሳሌ፥ የአደባባዩ፥ የቤተ መዛግብቱ፥ የሰገነቱ፥ የውስጡ ቤተ መዛግብት፥ የስርየት ቤቱና፥ የእግዚአብሔር ቤት ምሳሌ።'),
  ('d61ac2f5-8404-5594-a630-7a1519579aaf', 'eabd5100-0fe4-5f02-a692-a92d7e07178f', 'd88dd59c-4a87-5832-ad64-0cc1589d5c11', 21, 21, 'እነሆም፥ ለእግዚአብሔር ቤት አገልግሎት ሁሉ የሚሆኑ የካህናትና የሌዋውያን ክፍሎች በዚህ አሉ፤ ለሁሉም ዓይነት አገልግሎትና ሥራ በጥበብና በነፍሱ ፈቃድ የሚሠራ ሁሉ ከአንተ ጋር ይሆናል፤ አለቆችና ሕዝቡም ሁሉ ፈጽመው ይታዘዙሃል” አለው።'),
  ('77a577e3-eb0b-568d-aeb2-770772d70855', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 1, 1, 'ንጉሡ ዳዊትም ለጉባኤው ሁሉ እንዲህ አለ፥ “እግዚአብሔር ብቻውን የመረጠው ልጄ ሰሎሞን ገና ለጋ ብላቴና ነው፤ ሕንጻው ግን ለእግዚአብሔር ለአምላክ ነው እንጂ ለሰው አይደለምና ሥራው ታላቅ ነው።'),
  ('8fd6244e-8e71-5c14-a012-c8c96792fdb8', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 2, 2, 'እኔም እንደ ጉልበቴ ሁሉ ለአምላኬ ለእግዚአብሔር ቤት ወርቅን፥ ብርን፥ ናስን፥ ብረትን፥ እንጨትን፥ ደግሞም መረግድንና በፈርጥ የሚገባ ድንጋይን፥ የሚለጠፍ ድንጋይን፥ ልዩ ልዩ መልክ ያለውንም ድንጋይ፥ የከበረውንም ድንጋይ ከየዓይነቱ፥ ብዙም እብነ በረድ አዘጋጅቻለሁ።'),
  ('ca1e3a38-e37e-5bad-ac63-a5184cad57f6', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 3, 3, 'ከዚህም በላይ ደግሞ የአምላኬን የእግዚአብሔርን ቤት ስለ ወደድሁ፥ ለመቅደሱ ከሰበሰብሁት ሁሉ ሌላ የግል ገንዘቤ የሚሆን ወርቅና ብር አለኝና እነሆ፥ ለአምላኬ ቤት ሰጥቼዋለሁ።'),
  ('d3f2ac76-8219-5c8b-a719-df09c7206c0f', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 4, 4, 'የእግዚአብሔር ቤት ግንቦች ይለበጡበት ዘንድ ከኦፌር ወርቅ ሦስት ሺህ መክሊት ወርቅ፥ ሰባት ሺህ መክሊትም ጥሩ ብር፤'),
  ('853c1f5d-6d11-561b-a017-5c5ca3bdc5bc', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 5, 5, 'በሠራተኞች እጅ ለሚሠራው ሥራ ሁሉ ለወርቁ ዕቃ ወርቁን፥ ለብሩም ዕቃ ብሩን ሰጥቻለሁ። ዛሬ በዚች ቀን በፈቃዱ አገልግሎቱን ለእግዚአብሔር የሚፈጽም ማን ነው?”'),
  ('85b0e27b-38d9-56a3-a131-ff96e131231c', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 6, 6, 'የአባቶችም ቤቶች አለቆች፥ የእስራኤልም ልጆች አለቆች፥ ሻለቆችም፥ የመቶ አለቆችም፥ በእግዚአብሔር ቤት ሥራ የተሾሙና የንጉሡ ግንበኞች በፈቃዳቸው አቀረቡ።'),
  ('8f154d6a-adfd-5999-a9bb-115a5cbc9d53', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 7, 7, 'ለእግዚአብሔርም ቤት ሥራ አምስት ሺህ መክሊት ወርቅና ዐሥር ሺህ ዳሪክ፥ ዐሥር ሺህም መክሊት ብር፥ ዐሥራ ስምንት ሺህም መክሊት ናስ፥ መቶ ሺህም መክሊት ብረት ሰጡ።'),
  ('964b51cf-529b-50c8-a2f2-c600110d7ee4', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 8, 8, 'የከበረ ዕንቍም ያላቸው ሰዎች ሁሉ ለእግዚአብሔር ቤት ለሆነው ቤተ መዛግብት በጌድሶናዊው በኢዩኤል እጅ ሰጡ።'),
  ('164373db-9718-5ed7-a43a-7e7e8ffeb282', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 9, 9, 'ሕዝቡም ፈቅደው ሰጥተዋልና፥ በፍጹም ልባቸውም ለእግዚአብሔር በፈቃዳቸው አቅርበዋልና ደስ አላቸው፤ ንጉሡም ዳዊት ደግሞ ታላቅ ደስታ ደስ አለው።'),
  ('233f0a2e-db6e-5a25-a0df-df7c8f5136c3', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 10, 10, 'ንጉሡ ዳዊትም በጉባኤው ሁሉ ፊት እግዚአብሔርን አመሰገነ፤ እንዲህም አለ፥ “አቤቱ፥ የእስራኤል አምላክ አባታችን እግዚአብሔር ሆይ፥ ከዘለዓለም እስከ ዘለዓለም ቡሩክ ነህ።'),
  ('abc19490-a93e-5f27-afdd-f761b510f180', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 11, 11, 'አቤቱ፥ በሰማይና በምድር ያለው ሁሉ የአንተ ነውና ታላቅነትና ኀይል፥ ክብርም፥ ድልና ጽንዕ የአንተ ነው፤ ነገሥታቱና ሕዝቡ ሁሉ በፊትህ ይደነግጣሉ።'),
  ('5fcf4dac-5766-5fbc-ac46-4265fc747976', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 12, 12, 'ባለጠግነትና ክብር ከአንተ ዘንድ ነው፤ አቤቱ፥ አንተም ሁሉን ትገዛለህ፤ የሥልጣን ሁሉ ጌታ ነህ፤ ኀይልና ብርታት በእጅህ ነው፤ ኀያል ነህ፤ ታላቅ ለማድረግ፥ ለሁሉም ኀይልን ለመስጠት ዓለምን ሁሉ በእጅህ የያዝህ ነህ።'),
  ('bc5fd608-00e0-56f0-a73a-5deddae4058b', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 13, 13, 'አሁንም እንግዲህ፥ አምላካችን ሆይ፥ እንገዛልሃለን፤ ለክቡር ስምህም ምስጋና እናቀርባለን።'),
  ('fe524d1e-e6c7-5c7b-ad4e-4fb8940d1b72', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 14, 14, 'ሁሉ ከአንተ ዘንድ ነውና፥ ከእጅህም የተቀበልነውን ሰጥተንሃልና ይህን ያህል ችለን ልናቀርብልህ እኔ ማን ነኝ? ሕዝቤስ ማን ነው?'),
  ('66c135b2-0be7-5955-aeed-bee3dd537c40', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 15, 15, 'አባቶቻችን ስደተኞች እንደ ነበሩ እኛ በፊትህ ስደተኞችና መጻተኞች ነን፤ ዘመናችንም በምድር ላይ እንደ ጥላ ናት፤ አትጸናምም።'),
  ('e37321bf-ced2-5068-aaa0-addc84ad1e82', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 16, 16, 'አቤቱ አምላካችን ሆይ፥ ለቅዱስ ስምህ ቤት እሠራ ዘንድ ይህ ያዘጋጀሁት ባለጠግነት ሁሉ ከእጅህ የመጣ ነው፤ ሁሉም የአንተ ነው።'),
  ('cd61a4eb-3d30-5214-af71-ffdedf02aeac', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 17, 17, 'አምላኬ ሆይ፥ ልብን እንደምትመረምር፥ ጽድቅንም እንደምትወድድ አውቃለሁ፤ እኔም በልቤ ቅንነትና በፈቃዴ ይህን ሁሉ አቅርቤአለሁ፤ አሁንም በዚህ ያለው ሕዝብህ በፈቃዱ እንዳቀረበልህ በደስታ አይቻለሁ።'),
  ('b014b633-01a2-586e-a9b2-905ef2e2b0d5', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 18, 18, 'አቤቱ፥ የአባቶቻችን የአብርሃምና የይስሐቅ የእስራኤልም አምላክ ሆይ፥ ይህን አሳብ በሕዝብህ ልብ ላይ ለዘለዓለም ጠብቅ፤ ልባቸውንም ወደ አንተ አቅና።'),
  ('64ceec6d-ff04-56f7-a9a9-0659373a1ccf', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 19, 19, 'ትእዛዝህንም ያደርግ ዘንድ፥ ምስክርህንም፥ ሥርዐትህንም ይጠብቅ ዘንድ፥ ያዘጋጀሁለትንም ቤት ይሠራ ዘንድ ለልጄ ለሰሎሞን ቅን ልብን ስጠው።”'),
  ('93fccd5b-674e-54d1-aed2-f1f4b5c5b529', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 20, 20, 'ዳዊትም ጉባኤውን ሁሉ፥ “አምላካችን እግዚአብሔርን አመስግኑ” አላቸው። ጉባኤውም ሁሉ የአባቶቻቸውን አምላክ እግዚአብሔርን አመሰገኑ፥ በጕልበታቸውም ተንበርክከው ለእግዚአብሔር ሰገዱ፤ ደግሞም ለንጉሡ።'),
  ('ab3b9b2e-32e2-59b8-a26a-471f563ca0e9', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 21, 21, 'በነጋውም ዳዊት ለእግዚአብሔር መሥዋዕት ሠዋ፤ የሚቃጠለውንም መሥዋዕት ለእግዚአብሔር አቀረበ፤ አንድ ሺህ ወይፈን፥ አንድ ሺህም አውራ በጎች፥ አንድ ሺህም የበግ ጠቦቶች፥ የመጠጥ ቍርባናቸውንም፥ ስለ እስራኤልም ሁሉ ብዙ መሥዋዕት አቀረበ።'),
  ('692e55e0-71d4-51e9-a54b-5ba2f32c07cf', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 22, 22, 'በዚያም ቀን በታላቅ ደስታ በእግዚአብሔር ፊት በሉ፥ ጠጡም። የዳዊትንም ልጅ ሰሎሞንን ሁለተኛ ጊዜ አነገሡት፤ እርሱንም ንጉሥ ይሆን ዘንድ ለእግዚአብሔር ቀቡት፤ ሳዶቅም በካህናት ላይ ተሾመ።'),
  ('c672bc63-09aa-5cb0-a2c7-e0b35176958c', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 23, 23, 'ሰሎሞንም በአባቱ በዳዊት ዙፋን ላይ ተቀመጠ፤ በሁሉም ዘንድ ተወዳጅ ሆነ፤ እስራኤልም ሁሉ ታዘዙለት።'),
  ('155afdc6-4422-51fc-a709-36fef9fdb9f3', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 24, 24, 'አለቆቹም ሁሉ፥ ኀያላኑም፥ ደግሞም የንጉሡ የአባቱ የዳዊት ልጆች ሁሉ ለንጉሡ ለሰሎሞን ተገዙለት።'),
  ('1798dad9-85e9-517f-adbd-88cc836ba2ec', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 25, 25, 'እግዚአብሔርም ሰሎሞንን በእስራኤል ሁሉ ፊት እጅግ አገነነው፤ ከእርሱ በፊትም ለነበሩት ነገሥታት ያልሆነውን የመንግሥት ክብር ሰጠው።'),
  ('c9874e04-1c04-5c7c-a88a-e771b5922eff', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 26, 26, 'የእሴይም ልጅ ዳዊት በእስራኤል ሁሉ ላይ አርባ ዓመት ነገሠ።'),
  ('52840b0d-5db2-58cf-a8a0-bf369affff38', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 27, 27, 'ሰባት ዓመት በኬብሮን፥ ሠላሳ ሦስትም ዓመት በኢየሩሳሌም ነገሠ።'),
  ('ac49de89-2345-5914-a252-2fbb52a2ff00', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 28, 28, 'ዕድሜም፥ ባለጠግነትም፥ ክብርም ጠግቦ በመልካም ሽምግልና ሞተ፤ ልጁም ሰሎሞን በእርሱ ፋንታ ነገሠ።'),
  ('9cf44620-8b2a-592d-a7d7-73d58b56ba5c', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 29, 29, 'የንጉሡም የዳዊት የፊተኛውና የኋለኛው ነገር፥ እነሆ፥ በባለራእዩ በሳሙኤል ታሪክ፥ በነቢዩም በናታን ታሪክ፥ በባለ ራእዩም በጋድ ታሪክ ተጽፎአል።'),
  ('1e97e55a-9dfd-54d8-a9af-a0cd9d79cbaf', '3fe92cfc-e074-5c23-a084-b4475035a180', '04a76ddd-b808-573a-a8b5-f9b5f4152e89', 30, 30, 'እንደዚሁም የመንግሥቱ ነገርና ኀይሉ ሁሉ በእርሱም፥ በእስራኤልም፥ በምድርም መንግሥታት ሁሉ ላይ ያለፉት ዘመናት ተጽፈዋል።'),
  ('fa9efc30-a7b8-5ae3-a4f8-e29612474f63', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 1, 1, 'የዳዊት ልጅ ሰሎሞንም በመንግሥቱ በረታ፤ አምላኩም እግዚአብሔር ከእርሱ ጋር ነበረ፤ እጅግም አከበረው፤ አገነነውም።'),
  ('5990c89e-f2c9-5997-a42d-5f5440b97193', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 2, 2, 'ሰሎሞንም ለእስራኤል ሁሉ፥ ለሻለቆች ለመቶ አለቆችም፥ ለፈራጆችም፥ በእስራኤልም ሁሉ ዘንድ ለነበሩ መሳፍንት ሁሉ፥ ለአባቶች ቤቶች አለቆች ሁሉ ተናገረ።'),
  ('3c92c8e8-bd79-557a-a4d9-bff0f897021e', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 3, 3, 'ሰሎሞንም ከእርሱም ጋር የእስራኤል ጉባኤ ሁሉ የእግዚአብሔር ባሪያ ሙሴ በምድረ በዳ የሠራው የእግዚአብሔር የምስክር ድንኳን በዚያ ነበረና በገባዖን ወዳለው የኮረብታው መስገጃ ሄዱ።'),
  ('1fc16a2e-3570-579b-acfc-ce916a15df2b', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 4, 4, 'ዳዊት ግን የእግዚአብሔርን ታቦት ከቂርያትይዓሪም አወጣት። ለእርሷ በኢየሩሳሌም ድንኳን አዘጋጅቶላት ነበርና።'),
  ('4e7b1f6c-8801-5e3e-abf7-75da25a2294d', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 5, 5, 'የሆርም ልጅ የኡሪ ልጅ ባስልኤል የሠራው የናስ መሠዊያ በዚያ በእግዚአብሔር ማደሪያ ፊት ነበረ፤ ሰሎሞንና የእስራኤልም ጉባኤ የእግዚአብሔርን ታቦት ይፈልጓት ነበር።'),
  ('cc9d0246-b53e-5e19-a673-65fa014669db', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 6, 6, 'ሰሎሞንም በእግዚአብሔር ፊት በድንኳኑ አጠገብ ወዳለው ወደ ናሱ መሠዊያ ወጣ፤ በዚያም አንድ ሺህ የሚቃጠል መሥዋዕት አቀረበ።'),
  ('e31068c1-c2dc-5149-aaf2-876534ebc750', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 7, 7, 'በዚያችም ሌሊት እግዚአብሔር ለሰሎሞን ታየው፥ “የምሰጥህን ከእኔ ለምን” አለው።'),
  ('735e47b9-4c71-54bf-a469-31af0b77e3e2', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 8, 8, 'ሰሎሞንም እግዚአብሔርን አለው፥ “ከአባቴ ከዳዊት ጋር ታላቅ ምሕረትን አድርገሃል፤ በእርሱም ፋንታ አንግሠኸኛል።'),
  ('40586c25-ee16-508b-a55f-96547af9cae7', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 9, 9, 'አሁንም አቤቱ አምላኬ፥ ቍጥሩ እንደ ምድር አሸዋ በሆነው በብዙ ሕዝብ ላይ አንግሠኸኛልና ስምህ የታመነ ይሁን።'),
  ('ff1f9131-cbf5-58ce-a1e2-e8c831c642f5', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 10, 10, 'አሁንም በዚህ ሕዝብ ፊት እወጣና እገባ ዘንድ ጥበብንና ማስተዋልን ስጠኝ፤ በዚህ በታላቅ ሕዝብ ላይ መፍረድ የሚቻለው የለምና።”'),
  ('b529df22-8ed2-5a98-aa1e-660f89192f88', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 11, 11, 'እግዚአብሔርም ሰሎሞንን አለው፥ “ይህ በልብህ ነበረና፥ ባለጠግነትን፥ ሀብትን፥ ክብርን፥ የጠላቶችህንም ነፍስ፥ ረጅምም ዕድሜን አልለመንህም፤ ነገር ግን ባነገሥሁህ በሕዝቤ ላይ ትፈርድ ዘንድ ጥብብንና ማስተዋልን ለራስህ ለምነሃል።'),
  ('c819210f-40c6-50e7-a0f3-bf000b1ff65a', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 12, 12, 'ጥበብንና ማስተዋልን እሰጥሃለሁ። ካንተ በፊት ለነበሩ ነገሥታት ያልተሰጠውን፥ ከአንተም በኋላ ለሚነሡ የማይሰጠውን ብልፅግናን፥ ገንዘብንና ክብርን እሰጥሃለሁ።”'),
  ('633d9c43-8283-563e-a0aa-90eb702b1afe', '138cdf44-549c-52fc-aaea-4fa1998cad18', '2a105301-f043-586e-a292-59703018ba36', 13, 13, 'ሰሎሞንም በገባዖን ካለው ኮረብታ ከምስክሩ ድንኳን ፊት ወደ ኢየሩሳሌም መጣ፤ በእስራኤልም ላይ ነገሠ።'),
  ('1f26c9e6-60e7-5309-abee-5e755150b4cb', '138cdf44-549c-52fc-aaea-4fa1998cad18', 'f9426dd3-ddd2-516a-a743-9b9b8e6c5814', 1, 14, 'ሰሎሞንም ሰረገሎችንና ፈረሰኞችን ሰበሰበ፤ አንድ ሺህ አራት መቶ ሰረገሎች፥ ዐሥራ ሁለት ሺህም ፈረሰኞች ነበሩት፤ በሰረገሎች ከተሞችም አስቀመጣቸው። ሕዝቡም ከንጉሡ ጋር በኢየሩሳሌም ነበሩ።'),
  ('2df2ec6b-ddad-583a-ae4c-60b4c1e43f27', '138cdf44-549c-52fc-aaea-4fa1998cad18', 'f9426dd3-ddd2-516a-a743-9b9b8e6c5814', 2, 15, 'ንጉሡም ብሩንና ወርቁን፥ በኢየሩሳሌም እንደ ድንጋይ፥ የዝግባንም እንጨት በብዛት በቆላ እንደሚገኝ ሾላ በይሁዳ አኖረ።'),
  ('1c4bc914-8fc1-5d1b-afa9-f7d46afacd71', '138cdf44-549c-52fc-aaea-4fa1998cad18', 'f9426dd3-ddd2-516a-a743-9b9b8e6c5814', 3, 16, 'የሰሎሞን ፈረሶች መምጫ ከግብፅና ከቴቁሄ ምድር ነበር። በዋጋ ገዝተው ከቴቁሄ የሚያመጡአቸውም ከሀገር ሽማግሌዎች የሆኑ የሰሎሞን ነጋዴዎች ነበሩ።'),
  ('928367c0-5f81-5376-ad45-6bd3e2b8b71a', '138cdf44-549c-52fc-aaea-4fa1998cad18', 'f9426dd3-ddd2-516a-a743-9b9b8e6c5814', 4, 17, 'ሄደውም ከግብፅ አንድ ሰረገላ በስድስት መቶ ብር፥ አንድንም ፈረስ በመቶ አምሳ ሰቅል ብር አመጡ፤ እንዲሁም ለኬጢያውያንና ለሦርያ ነገሥታት ሁሉ በየተራቸው ያመጡላቸው ነበር።'),
  ('b28b459a-ec66-5449-a8fb-00c66b8c5d77', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 1, 1, 'ሰሎሞንም ለእግዚአብሔር ስም ቤት፥ ለራሱም ቤተ መንግሥት ልሥራ አለ።'),
  ('3880f928-80b5-5785-aec2-b7f748f34222', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 2, 2, 'ሰሎሞንም የሚሸከሙትን ሰባ ሺህ፥ ከተራሮችም ድንጋዮችን የሚጠርቡትን ሰማንያ ሺህ፥ በእነርሱም ላይ የተሾሙትን ሦስት ሺህ ስድስት መቶ ሰዎች ሰበሰበ።'),
  ('1c7e0518-ce6c-53f9-a7b6-678f897bbcc6', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 3, 3, 'ሰሎሞንም እንዲህ ሲል ወደ ጢሮስ ንጉሥ ወደ ኪራም ላከ፥ “ከአባቴ ከዳዊት ጋር እንዳደረግህ፥ የሚቀመጥበትንም ቤት ይሠራ ዘንድ የዝግባ እንጨት እንደ ላክህለት፥ እንዲሁ ለእኔ አድርግ።'),
  ('1a1f9e9c-5bc3-5012-adb8-d847e7de846c', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 4, 4, 'እነሆ፥ ለእስራኤል ለዘለዓለም እንደ ታዘዘው በእግዚአብሔር ፊት የጣፋጩን ሽቱ ዕጣን ለማጠን፥ የገጹንም ኅብስት ለማኖር፥ የሚቃጠለውንም መሥዋዕት በጥዋትና በማታ፥ በሰንበታቱም፥ በመባቻዎቹም፥ በአምላካችንም በእግዚአብሔር በዓላት ለማቅረብ እኔ ልጁ ለአምላኬ ለእግዚአብሔር ስም ቤት እሠራለሁ፤ እርሱንም እቀድሳለሁ።'),
  ('d04827d2-f9f7-5ee7-a58f-d45c6c9d3fc4', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 5, 5, 'አምላካችን እግዚአብሔርም ከአማልክት ሁሉ ይልቅ ታላቅ ነውና የምሠራው ቤት ታላቅ ነው።'),
  ('c8dafa09-620d-5b69-a4fd-f783ccbb705b', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 6, 6, 'ነገር ግን ሰማይና ከሰማያት በላይ ያለ ሰማይ ክብሩን ይሸከም ዘንድ አይችልምና ለእርሱ ቤት ይሠራ ዘንድ ማን ይችላል? በፊቱ ዕጣን ከማጠን በቀር ቤት እሠራለት ዘንድ እኔ ማን ነኝ?'),
  ('344745f2-5bf3-581a-ac7e-a16fd6f48da0', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 7, 7, 'አሁንም በወርቅና በብር፥ በናስና በብረት፥ በሐምራዊና በቀይ፥ በሰማያዊም ግምጃ መለበጥ የሚችልና፥ አባቴ ዳዊት ካዘጋጃቸው በእኔ ዘንድ በይሁዳና በኢየሩሳሌም ካሉት ብልሃተኞች ጋር ቅርጽ ማውጣት የሚያውቅ ብልሃተኛ ሰውን ላክልኝ።'),
  ('1bcd28d9-ca0c-5415-ace3-c6f1d9dbaffb', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 8, 8, 'ደግሞም አገልጋዮችህ ከሊባኖስ እንጨት መቍረጥ እንዲያውቁ እኔ አውቃለሁና ከሊባኖስ የዝግባና የጥድ፥ የሰንደልም እንጨት ላክልኝ።'),
  ('5517a1dd-1db4-5152-a0d5-53dae05af434', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 9, 9, 'የምሠራውም ቤት እጅግ ታላቅና ክቡር ይሆናልና ብዙ እንጨት ያዘጋጁልኝ ዘንድ፥ እነሆ፥ አገልጋዮች ከአገልጋዮችህ ጋር ይወጣሉ።'),
  ('2e6051fd-f628-51e9-a40c-149d7645ea3e', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 10, 10, 'እነሆም፥ እንጨቱን ለሚቈርጡ ለአገልጋዮችህ ሃያ ሺህ የቆሮስ መስፈሪያ የተበጠረ ስንዴ፥ ሃያ ሺህም የቆሮስ መስፈሪያ ገብስ፥ ሃያ ሺህም የባዶስ መስፈሪያ የወይን ጠጅ፥ ሃያ ሺህም የባዶስ መስፈሪያ ዘይት በነጻ እሰጣለሁ።”'),
  ('26da91a0-0f4f-5d4c-a3eb-72fdb1795ce7', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 11, 11, 'የጢሮስ ንጉሥ ኪራምም፥ “እግዚአብሔር ሕዝቡን ወድዶአልና በላያቸው አነገሠህ” ሲል ለሰሎሞን ጻፈለት።'),
  ('af562d83-d5c0-5516-af96-8c754f368cd5', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 12, 12, 'የጢሮስ ንጉሥ ኪራምም ደግሞ አለ፥ “ለእግዚአብሔር ቤት ለመንግሥቱም ቤት ይሠራ ዘንድ ጥበበኛና ብልሃተኛ፥ አስተዋይም ልጅ ለንጉሡ ለዳዊት የሰጠ፥ ሰማይንና ምድርን የፈጠረ የእስራኤል አምላክ እግዚአብሔር ቡሩክ ይሁን።'),
  ('4f3220f8-8731-5c54-a193-baf1a45f82dd', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 13, 13, 'አሁንም ብልሃተኛና አስተዋይ ሰው አቢኪራምን ልኬልሃለሁ።'),
  ('d2df15f6-a607-58a5-adb5-4214d6a28d5f', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 14, 14, 'እናቱ ከዳን ልጆች ናት፤ አባቱም የጢሮስ ሰው ነው፤ በወርቅና በብር፥ በናስና በብረት፥ ድንጋዩንና እንጨቱን መለበጥ፥ ሐምራዊውንና ሰማያዊውን፥ ቀዩንም ግምጃ፥ ጥሩውንም በፍታ መሥራት፥ ቅርጽም፥ ሌላም ነገር ሁሉ ማድረግ ያውቃል። ከብልሃተኞችህ ጋር ከጌታዬም ከአባትህ ከዳዊት ብልሃተኞች ጋር ሥራ ብለህ የምትሰጠውን ሁሉ አስቦ መሥራት ይችላል።'),
  ('9ebea0c4-baa7-52df-a7a0-d680a1e82f37', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 15, 15, 'አሁንም ጌታዬ የተናገረውን ስንዴውንና ገብሱን ዘይቱንና የወይን ጠጁን ወደ አገልጋዮቹ ይላክ፤'),
  ('dad46f74-54c4-50ca-ae92-13282d10445d', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 16, 16, 'እኛም ከሊባኖስ የምትሻውን ያህል እንጨት እንቈርጣለን፤ በታንኳም አድርገን በባሕር ላይ ወደ አንተ ወደ ኢዮጴ እንልካለን፤ አንተም ወደ ኢየሩሳሌም ታስወስደዋለህ።”'),
  ('450704f7-ff53-54be-af76-0c8107a38038', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 17, 17, 'ሰሎሞንም አባቱ ዳዊት ከቈጠራቸው ጋር ያልተቈጠሩ በእስራኤል ምድር የነበሩትን መጻተኞች ሁሉ ሰበሰበ፤ ቍጠራቸውም መቶ ኀምሳ ሦስት ሺህ ስድስት መቶ ሆኖ ተገኘ።'),
  ('7a7e07a7-301d-553c-a567-e06b1ce91bbd', '89f11d1b-7acc-53a1-a401-f4b63ef89213', '34b50027-2787-5b85-a7a5-93c39d29a6fa', 18, 18, 'ከእነርሱም የሚሸከሙትን ሰባ ሺህ፥ በተራሮቹም ላይ የሚጠርቡትን ሰማንያ ሺህ፥ በሕዝቡም ሥራ ላይ የተሾሙትን ሦስት ሺህ ስድስት መቶ አደረገ።'),
  ('375e1e2f-5c26-5ab5-ac31-4ed5b0a20bcc', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 1, 1, 'ሰሎሞንም እግዚአብሔር ለአባቱ ለዳዊት በተገለጠበት በአሞሪያ ተራራ ዳዊት ባዘጋጀው ስፍራ በኢያቡሳዊው በኦርና አውድማ በኢየሩሳሌም የእግዚአብሔርን ቤት መሥራት ጀመረ።'),
  ('f0b11bbe-14b2-5801-a38e-d410dfb7c2a0', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 2, 2, 'በነገሠም በአራተኛው ዓመት በሁለተኛው ወር መሥራት ጀመረ።'),
  ('fdcdb533-8b1a-50e2-ac21-edf485fc37ee', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 3, 3, 'ሰሎሞንም የእግዚአብሔርን ቤት ይሠራ ዘንድ የጣለው መሠረት ይህ ነው፤ ርዝመቱም በዱሮው ስፍር ስድሳ ክንድ፥ ወርዱም ሃያ ክንድ ነበረ።'),
  ('df57a372-74c6-5ae8-a8ef-43244acab0d2', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 4, 4, 'በቤቱም ፊት የነበረው ወለል ርዝመቱ እንደ ቤቱ ወርድ ሃያ ክንድ፥ ቁመቱም መቶ ሃያ ክንድ ነበረ፤ ውስጡንም በጥሩ ወርቅ ለበጠው።'),
  ('fc6268af-7b8b-5bc7-ac3c-958e3e9afbb9', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 5, 5, 'ታላቁንም ቤት በዝግባ እንጨት ከደነው፤ በጥሩም ወርቅ ለበጠው፤ የዘንባባና የሰንሰለት አምሳልም ቀረጸበት።'),
  ('26c672c8-a609-54be-ad5e-0bf62e3bc3f4', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 6, 6, 'ቤቱንም በከበረና በተመረጠ ዕንቍ፥ በወርቅም አስጌጠው፤ ወርቁም የፋሩሔም ወርቅ ነበረ።'),
  ('3eb5a5ac-0a97-5f8e-a823-570cb3743d26', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 7, 7, 'ቤቱንም፥ ሰረገሎቹንም፥ መድረኮቹንም፥ ግንቦቹንም፥ ደጆቹንም በወርቅ ለበጠ፤ በግንቦቹም ላይ ኪሩቤልን ቀረጸ።'),
  ('a94ffe43-6b96-55d3-a64b-0dd278481591', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 8, 8, 'ቅድስተ ቅዱሳኑንም ሠራ፤ ርዝመቱም እንደ ቤቱ ወርድ ሃያ ክንድ፥ ወርዱም ሃያ ክንድ ነበረ፤ ስድስት መቶ መክሊት በሚያህል በጥሩ ወርቅም ኪሩቤልን ለበጣቸው።'),
  ('cdef0725-baf9-5004-afc8-c91eaa71940e', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 9, 9, 'የምስማሮቹም ሚዛን ለእያንዳንዱ አምሳ ሰቅል ወርቅ ነበረ። የደርቡንም ጓዳዎች በወርቅ ለበጠ።'),
  ('b1b2ffd1-883d-5048-a56c-e616515f75fb', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 10, 10, 'በቅድስተ ቅዱሳንም ውስጥ ከእንጨት ሥራ ሁለቱን ኪሩቤል ሠራ፤ በወርቅም ለበጣቸው።'),
  ('f40e8685-1121-5617-a091-163a77c1fac9', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 11, 11, 'የኪሩቤልም ክንፎች ሃያ ክንድ ሙሉ ተዘርግተው ነበር፤ የአንዱ የኪሩብ ክንፍ ርዝመት አምስት ክንድ ነበረ፤ የቤቱንም ግንብ ይነካ ነበር፤ የሁለተኛውም ክንፍ ርዝመት አምስት ክንድ ነበረ፤ የሁለተኛውንም ኪሩብ ክንፍ ይነካ ነበር።'),
  ('6dc4f0fe-419a-523b-a430-8918fbdd3e65', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 12, 12, 'የሁለተኛውም ኪሩብ አንዱ ክንፍ አምስት ክንድ ነበረ፤ የቤቱንም ግንብ ይነካ ነበር፤ ሁለተኛውም ክንፍ አምስት ክንድ ነበረ፤ የሌላውንም ኪሩብ ክንፍ ይነካ ነበር።'),
  ('48d4797c-c8ca-5c80-a9e3-4d0848afa45c', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 13, 13, 'የእነዚህም ኪሩቤል ክንፎች ሃያ ክንድ ሙሉ ተዘርግተው ነበር፤ በእግራቸውም ቆመው ነበር፤ ፊቶቻቸውም ወደ እግዚአብሔር ቤት ይመለከቱ ነበር።'),
  ('1b7ee779-2890-5494-a427-f686974ad723', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 14, 14, 'ከሰማያዊውም፥ ከሐምራዊውም፥ ከቀዩም ሐር፥ ከጥሩም በፍታ መጋረጃውን ሠራ፤ ኪሩቤልንም ጠለፈበት።'),
  ('ad111de2-cfe4-5097-ae86-7f341a5943a7', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 15, 15, 'በቤቱም ፊት ቁመታቸው ሠላሳ አምስት ክንድ የነበረውን ሁለቱን ዐምዶች ሠራ፤ በእያንዳንዳቸውም ላይ የነበረው ጕልላት አምስት ክንድ ነበረ።'),
  ('03f8bc43-dd72-54ab-aca6-d5e8fc0f4139', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 16, 16, 'እንደ ድሪ ያሉ ሰንሰለቶችንም ሠርቶ በአዕማዱ ራስ ላይ አደረጋቸው፤ መቶም ሮማኖች ሠርቶ በሰንሰለቱ ላይ አደረጋቸው።'),
  ('8e1ac740-8a98-5f28-a1df-a1672b2ef97c', 'fff7f699-49f3-5d4a-adc0-5538f388f234', 'f897b8ad-fb6a-529f-ae17-86fc25ddfaed', 17, 17, 'አዕማዶቹንም አንደኛውን በቀኝ፥ ሁለተኛውንም በግራ በመቅደሱ ፊት አቆማቸው፤ በቀኝም የነበረውን ስም ርትዕ በግራም የነበረውን ስም ጽንዕ ብሎ ጠራቸው።'),
  ('3b578a2c-2f44-5c58-a48b-1c2f7be7bf61', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 1, 1, 'ርዝመቱም ሃያ ክንድ፥ ወርዱም ሃያ ክንድ፥ ቁመቱም ዐሥር ክንድ የነበረውን የናሱን መሠዊያ ሠራ።'),
  ('4cf7b968-3528-5e06-a777-43e7957315ce', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 2, 2, 'ዳግመኛም ከቀለጠ ናስ ከዳር እስከ ዳር ዐሥር ክንድ፥ ቁመትዋም አምስት ክንድ፥ ዙሪያዋም ሠላሳ ክንድ የሆነ ኵሬ ሠራ።'),
  ('4d12909a-1746-5762-a2ea-35fd0b709365', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 3, 3, 'በበታችዋም፥ በዙሪያዋ በዐሥሩ ክንድ የበሬዎች ምስሎች ነበሩ። ኵሬዋንም ይከብቡአት ነበር። በሬዎቹም በሁለት ተራ ሁነው ከኵሬው ጋር በአንድነት ቀልጠው የተሠሩ ነበሩ።'),
  ('1544990f-42a3-551c-a2d4-697133a76e3b', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 4, 4, 'ዐሥራ ሁለት በሬዎችን ሠሩላቸው። ከእነርሱም ሦስቱ ወደ ሰሜን፥ ሦስቱ ወደ ምዕራብ፥ ሦስቱም ወደ ደቡብ፥ ሦስቱም ወደ ምሥራቅ ይመለከቱ ነበር፤ ቀልጣ የተሠራች ኵሬም በላያቸው ነበረች፤ የሁሉም ጀርባቸው በስተውስጥ ነበረ።'),
  ('d8d1b1e4-37b7-5b5c-adde-f20996b02a71', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 5, 5, 'ውፍረትዋም አንድ ጋት ያህል ነበረ፤ ከንፈሯም እንደ ጽዋ ከንፈር፥ እንደ ሱፍ አበባ ሆኖ ተሠርቶ ነበር፤ ሦስት ሺህም ማድጋ ትይዝ ነበር ሠርቶም ፈጸማት፤'),
  ('5d6bf99a-8eb3-5415-a071-7032bcb58cd7', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 6, 6, 'ደግሞም ዐሥር የመታጠቢያ ሰኖችን ሠራ፤ ለሚቃጠለውም መሥዋዕት የሚቀርበው ነገር ሁሉ ይታጠብባቸው ዘንድ አምስቱን በቀኝ፥ አምስቱንም በግራ አኖራቸው፤ ባሕሩ ግን ካህናት ይታጠቡበት ነበር።'),
  ('d1e7bd15-bafb-5692-a7d3-3be33d0b6965', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 7, 7, 'ዐሥሩንም የወርቅ መቅረዞች እንደ ሥርዐታቸው ሠራ፤ አምስቱን በቀኝ፥ አምስቱንም በግራ በመቅደሱ ውስጥ አኖራቸው።'),
  ('355566ed-eda6-56e4-a798-15e4af57aefe', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 8, 8, 'ዐሥሩንም የወርቅ ገበታዎች ሠርቶ አምስቱን በቀኝ፥ አምስቱንም በግራ በመቅደሱ ውስጥ አኖራቸው። አንድ መቶም የወርቅ ጽዋዎችን ሠራ።'),
  ('491456ce-4fe6-5794-aa83-754de92ce9ca', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 9, 9, 'ደግሞም የካህናቱን አደባባይ ፥ ታላቁንም አደባባይ፥ የአደባባዩንም ደጆች ሠራ፤ ደጆቻቸውንም በናስ ለበጠ።'),
  ('4923a98f-2be4-5d00-a32e-1e9a09f0adee', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 10, 10, 'ኵሬውንም በቤተ መቅደሱ መዓዝን በስተቀኝ በኩል በምሥራቅ አቅጣጫ አኖረው።'),
  ('d838ccea-aa22-5530-a0ff-814c85c41a4c', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 11, 11, 'ኪራምም ምንቸቶቹንና መጫሪያዎቹን፥ በመሠዊያው ቤት ያሉ ማንኪያዎችንና የመገልገያውን ዕቃ ሁሉ ሠራ። ኪራምም ለንጉሡ ለሰሎሞን በእግዚአብሔር ቤት የሠራውን ሥራ ሁሉ ጨረሰ።'),
  ('de1f077b-f1ba-59c9-aa5a-6c8244eb0708', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 12, 12, 'ሁለት ዐምዶችንና በሁለቱ ዐምዶች ላይ ጕልላቶችን፥ በዐምዶቹም ራሶች ላይ ያሉትን ጕልላቶች የሚሸፍኑ ሁለት መርበቦችን ሠራ።'),
  ('a8501a55-7386-531f-a777-7ee72d5a0859', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 13, 13, 'በሁለቱም መርበቦች አራት መቶ የወርቅ ሻኵራዎችንና በዐምዶቹ ላይ ያሉትን ሁለት ጕልላቶች በሁለት ጎኖች የሚሸፍኑትን ሮማኖች ሠራ።'),
  ('42c57d80-5ca7-51f5-ae9f-a0bfdab56960', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 14, 14, 'ዐሥር መቀመጫዎችንና በመቀመጫዎቹም ላይ መታጠቢያዎችን ሠራ፤'),
  ('33c4dd31-520c-5d75-ae14-6c07617372d0', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 15, 15, 'አንድዋንም ኵሬ፥ በበታችዋም ያሉትን ዐሥራ ሁለት በሬዎች ሠራ።'),
  ('14648c18-f623-5962-a5e9-fbf8dc7ec690', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 16, 16, 'የእግር መታጠቢያዎችን፥ የእጅ መታጠቢያዎችን፥ ጋኖችን፥ የሥጋ ማውጫ ሜንጦዎችንና ኪራም የሠራውን ሥራ ሁሉ ከንጹሕ ናስ ሠርቶ ለንጉሡ ለሰሎሞን ለእግዚአብሔር ቤት አቀረበለት።'),
  ('ccd1deff-a23c-5888-a745-b9aa001b2e29', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 17, 17, 'ንጉሡም በዮርዳኖስ ሜዳ በሱኮትና በሴድራ መካከል ባለው በወፍራሙ መሬት ውስጥ አቀለጣቸው።'),
  ('c0a44ff6-0a51-5974-a108-64cf9599ef81', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 18, 18, 'ሰሎሞንም እነዚህን ዕቃዎች ሁሉ እጅግ አብዝቶ ሠራ፤ የናሱም ብዛት አይቈጠርም ነበር።'),
  ('43dd067d-3706-55f4-adc0-ab506ead02bb', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 19, 19, 'ሰሎሞንም በእግዚአብሔር ቤት የነበረውን ዕቃ ሁሉ፥ የወርቁንም መሠዊያ፥ ኅብስተ ገጽ የነበረባቸውን ገበታዎች ሠራ።'),
  ('0726a664-8623-54b0-a61f-5db630770850', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 20, 20, 'በመቅደሱ ፊት እንደ ሥርዐታቸው የሚያበሩ መቅረዞችንና ቀንዲሎችንም ከጥሩ ወርቅ ሠራ።'),
  ('06f4dbbd-7d5c-511c-a867-68a0e9267c5c', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 21, 21, 'የመብራቶች መቅረዞችንና በላያቸው ያሉ መብራቶችን፥ ጽዋዎቹን፥ ማንኪያዎቹን፥ ሥራ የሚሠሩባቸው ጻሕሎችንም ከጥሩ ወርቅ ሠራ።'),
  ('fdaafb67-c229-5f72-a4fb-bd882ade5920', '355c9f50-4d14-53ea-a5ec-8d6cace02538', 'ba338a10-67e6-5089-a5db-031d6cb9e0ce', 22, 22, 'ውስጠኛው የእግዚአብሔር ቤት ደጅና ወደ ቅድስተ ቅዱሳኑ መግቢያ የሚወስደው የውስጠኛውም የቤተ መቅደሱ ደጆች የወርቅ ነበሩ። እንዲሁም ሰሎሞን ስለ እግዚአብሔር ቤት የሠራው ሥራ ሁሉ ተፈጸመ።'),
  ('a277dc60-9cd7-5458-a95c-1b727873c37e', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 1, 1, 'ሰሎሞንም አባቱ ዳዊት የቀደሰውን ብሩንና ወርቁን፥ የመገልገያ ዕቃውንም ሁሉ አምጥቶ በእግዚአብሔር ቤት ውስጥ በነበረው ግምጃ ቤት አገባ።'),
  ('b8a91776-3e92-5569-a719-3f4f9f15a819', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 2, 2, 'በዚያ ጊዜም ሰሎሞን የእግዚአብሔርን ቃል ኪዳን ታቦት ከዳዊት ከተማ ከጽዮን ያወጡ ዘንድ የእስራኤልን ሽማግሌዎችና የነገድ አለቆችን ሁሉ፥ የእስራኤልንም ልጆች አባቶች ቤቶች መሳፍንት ወደ ኢየሩሳሌም ሰበሰበ።'),
  ('d3057b77-ab27-5485-ad00-a024255ec5e6', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 3, 3, 'የእስራኤልም ሰዎች ሁሉ በሰባተኛው ወር በበዓሉ ጊዜ ወደ ንጉሡ ወደ ሰሎሞን ተሰበሰቡ።'),
  ('3b9c6e78-1f54-58ad-ac1b-36baa9fea67c', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 4, 4, 'የእስራኤልም ሽማግሌዎች ሁሉ መጡ፤ ሌዋውያንም ሁሉ ታቦቷን አነሡ።'),
  ('a3356ff5-88b5-54bb-a70e-cdb89bfbe56f', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 5, 5, 'የምስክሩንም ድንኳን፥ በድንኳኑም ውስጥ የነበረውን የተቀደሰውን ዕቃ ሁሉ አወጡ፤ ታቦቷንም ካህናቱና ሌዋውያኑ አወጡ።'),
  ('ea714102-826f-5b91-a4ce-418719a86d1d', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 6, 6, 'ንጉሡም ሰሎሞንና የእስራኤል ማኅበር ሁሉ፥ እግዚአብሔርን የሚፈሩ ሁሉ በአንድነት በታቦቷ ፊት ሆነው ከብዛት የተነሣ የማይቈጠሩትንና የማይመጠኑትን በጎችና በሬዎች ይሠዉ ነበር።'),
  ('304ea2f7-3e61-5038-af8c-506efbd39e84', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 7, 7, 'ካህናቱም የእግዚአብሔርን የቃል ኪዳን ታቦት ወደ ቤትዋ አምጥተው በቅድስተ ቅዱሳን ውስጥ ከኪሩቤል ክንፍ በታች በነበረው መቅደስ አኖሯት።'),
  ('9d66dbb7-800c-5f1d-a483-b11ac9777092', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 8, 8, 'ኪሩቤልም በታቦቷ ስፍራ ላይ ክንፎቻቸውን ዘርግተው ነበር፤ ኪሩቤልም ታቦቷንና መሎጊያዎቹን በስተላዩ በኩል ይሸፍኑ ነበር።'),
  ('a4d5f70c-dd91-55e2-a1a0-26edeaafa433', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 9, 9, 'መሎጊያዎቹም ረጃጅሞች ነበሩና በቅድስተ ቅዱሳኑ ፊት ከመቅደሱ ውስጥ ጫፎቻቸው ይታዩ ነበር፤ ነገር ግን ከውጭ አይታዩም ነበር፤ እስከ ዛሬም ድረስ እዚያ አሉ።'),
  ('ca7ede90-a8d9-5fea-a9b3-712b2071bf23', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 10, 10, 'በታቦቷም ውስጥ የእስራኤል ልጆች ከግብፅ ምድር በወጡ ጊዜ፥ እግዚአብሔርም ከእነርሱ ጋር ቃል ኪዳን ባደረገ ጊዜ ሙሴ በኮሬብ ካስቀመጣቸው ከሁለቱ ጽላት በቀር ምንም አልነበረባትም።'),
  ('d7a467a0-710f-5885-a5ea-6dd16bd5f605', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 11, 11, 'ከመቅደስም ከወጡ በኋላ በዚያ የነበሩት ካህናት ሁሉ ተቀድሰው ነበር፤ በሰሞናቸውም አልተከፈሉም ነበር።'),
  ('48814cd3-e53f-5e0b-a44d-9e48832306ab', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 12, 12, 'መዘምራንም የነበሩት ሌዋውያን ሁሉ፥ ከአሳፍና ከኤማን፥ ከኤዶትምም ልጆች ጋር ወንድሞቻቸውም፥ ጥሩ በፍታ ለብሰው ጸናጽልና ከበሮ፥ መሰንቆም እየመቱ በመሠዊያው አጠገብ በምሥራቅ በኩል ቆመው ነበር፤ ከእነርሱም ጋር መቶ ሃያ ካህናት መለከት ይነፉ ነበር።'),
  ('8be28673-9a8e-5ef7-ab3f-ed0b83235c6f', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 13, 13, 'መለከቱንም የሚነፉ መዘምራኑ በአንድነት ሆነው እግዚአብሔርን እያመሰገኑና እያከበሩ፥ “እግዚአብሔር ቸር ነውና፥ ምሕረቱም ለዘለዓለም ነውና እግዚአብሔርን አመስግኑ” እያሉ በአንድ ቃል ድምፃቸውን ወደ ላይ ከፍ አድርገው በመለከትና በጸናጽል፥ በዜማም ዕቃ ሁሉ እግዚአብሔርን ባመሰገኑ ጊዜ፥ የእግዚአብሔር የክብሩ ደመና የእግዚአብሔርን ቤት ሞላው።'),
  ('c3619f2f-9d27-5fa8-a2a8-bc55c7588689', '88751140-c36a-56fd-ab30-f473a866895a', '48e627ba-74b4-5997-ad4d-8450628ad3c9', 14, 14, 'የእግዚአብሔርም ክብር የእግዚአብሔርን ቤት ሞልቶት ነበርና ካህናቱ ከደመናው የተነሣ መቆምና ማገልገል አልተቻላቸውም።'),
  ('617dd29e-82a8-5d6f-a290-190d1f4df26a', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 1, 1, 'ያንጊዜም ሰሎሞን፥ “እግዚአብሔር፦ በጨለማ ውስጥ እኖራለሁ ብሎአል።'),
  ('2fe91691-37ab-5fd7-adf6-cf64ea9aa83a', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 2, 2, 'እኔም ለዘለዓለም የሚኖርበት ዝግጁና ቅዱስ ቤት ለስሙ ሠራሁ” አለ።'),
  ('ec8bcb8d-1ed6-5b30-ab9a-4f8faf20ac94', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 3, 3, 'ንጉሡ ሰሎሞንም ፊቱን መልሶ የእስራኤልን ጉባኤ ሁሉ መረቀ፤ የእስራኤልም ጉባኤ ሁሉ ቆመው ነበር።'),
  ('a99d0217-31f9-5a42-a776-f5a8af6e1ad6', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 4, 4, 'እርሱም አለ፥ “ለአባቴ ለዳዊት በአፉ የተናገረ፥ በእጁም የፈጸመ የእስራኤል አምላክ እግዚአብሔር ይመስገን።'),
  ('d612600b-1881-52ee-a382-33ebc95797c1', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 5, 5, 'እርሱ፦ ሕዝቤን ከግብፅ ምድር ካወጣሁበት ጊዜ ጀምሮ ከእስራኤል ነገድ በዚያ ለስሜ ቤት ይሠራበት ዘንድ ከተማን አልመረጥሁም። በሕዝቤ እስራኤል ላይም ይነግሥ ዘንድ ሰውን አልመረጥሁም።'),
  ('a8f4e54d-83a8-53e1-a576-202829b74042', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 6, 6, 'ነገር ግን ስሜ በዚያ እንዲጠራባት ኢየሩሳሌምን መርጫለሁ። በሕዝቤም በእስራኤል ላይ ንጉሥ እንዲሆን ዳዊትን መርጫለሁ ብሎአል።'),
  ('b70ace30-6f58-5f64-a69e-1a11f1be4273', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 7, 7, 'አባቴም ዳዊት ለእስራኤል አምላክ ለእግዚአብሔር ቤት ይሠራ ዘንድ በልቡ አስቦ ነበር።'),
  ('7f4a9260-10a5-515d-afb3-0e23901d2157', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 8, 8, 'እግዚአብሔርም አባቴን ዳዊትን፦ ለስሜ ቤት ትሠራ ዘንድ በልብህ አስበሃልና ይህን በልብህ ማሰብህ መልካም አደረግህ።'),
  ('29d3e88b-6492-5289-a7a3-487fd0818b9b', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 9, 9, 'ነገር ግን ከወገብህ የሚወጣው ልጅህ እርሱ ለስሜ ቤትን ይሠራል እንጂ አንተ አትሠራልኝም አለው።'),
  ('730243b1-0479-5da6-a5f6-1446837689a1', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 10, 10, 'እግዚአብሔርም የተናገረውን ቃል ፈጸመ፤ እግዚአብሔርም እንደ ተናገረ በአባቴ በዳዊት ፋንታ ተተካሁ፤ በእስራኤልም ዙፋን ላይ ተቀመጥሁ፤ ለእስራኤልም አምላክ ለእግዚአብሔር ስም ቤት ሠራሁ።'),
  ('36c67bfb-fcb6-5c94-a792-2e7e4a6276e4', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '83a04368-379e-5b81-aaf3-ff2b7f72884a', 11, 11, 'ከሕዝቡም ከእስራኤል ጋር ያደረገው የእግዚአብሔር ቃል ኪዳን ያለባትን ታቦት በዚያው ውስጥ አኖርሁ።”'),
  ('199055e7-8218-55af-a4d3-caeda0c1bb5f', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 1, 12, 'ሰሎሞንም በእስራኤል ጉባኤ ሁሉ ፊት በእግዚአብሔር መሠዊያ አንጻር ቆሞ እጆቹን ዘረጋ።'),
  ('4077ac82-3e46-5493-a122-52afec3839c2', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 2, 13, 'ሰሎሞንም ርዝመቱ አምስት ክንድ፥ ወርዱም አምስት ክንድ፥ ቁመቱም ሦስት ክንድ የሆነ የናስ መድረክ ሠርቶ በእግዚአብሔር ቤት አደባባይ መካከል ተክሎት ነበር፤ በላዩም ቆመ፤ በእስራኤልም ጉባኤ ሁሉ ፊት በጕልበቱ ተንበርክኮ እጁን ወደ ሰማይ ዘረጋ፤'),
  ('9676669d-f9da-5e37-ac87-9516924fd9a4', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 3, 14, 'እንዲህም አለ፥ “አቤቱ የእስራኤል አምላክ ሆይ፥ በሰማይም በምድርም አንተን የሚመስል አምላክ የለም፤ በፍጹም ልባቸው በፊትህ ለሚሄዱ ባሪያዎችህ ቃል ኪዳንንና ምሕረትን የምታጸናና የምትጠብቅ አንተ ነህ።'),
  ('0c3bc82b-68aa-558f-a3aa-767bfe441b54', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 4, 15, 'ለባሪያህ ለአባቴ ለዳዊት እንዲህ ብለህ የተናገርኸውን የጠበቅህ፥ በአፍህ ተናገርህ፤ ዛሬም እንደ ሆነው በእጆችህ ፈጸምኸው።'),
  ('26884b15-5456-5d8c-a8d7-16242a0aa860', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 5, 16, 'አሁንም አቤቱ የእስራኤል አምላክ ሆይ፥ አንተ በፊቴ እንደ ሄድህ ልጆችህ በሕጌ ይሄዱ ዘንድ መንገዳቸውን ቢጠብቁ በእስራኤል ዙፋን የሚቀመጥ ሰው በፊቴ አይታጣም ብለህ የተናገርኸውን ለባሪያህ ለአባቴ ለዳዊት ጠብቅ፤ አጽናም።'),
  ('11458fe5-e8c3-5309-a05e-4a234401060f', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 6, 17, 'አሁንም፥ አቤቱ፥ የእስራኤል አምላክ ሆይ፥ ለባሪያህ ለዳዊት የተናገርኸው ቃል ይጽና።'),
  ('0dd0c9d2-8cc3-5728-a83b-af47bd46d90f', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 7, 18, '“በውኑ እግዚአብሔር ከሰው ጋር በምድር ላይ ይኖራልን? እነሆ፥ ሰማይ ሰማየ ሰማያትም ይወስንህ ዘንድ አይችልም፤ እንግዲያስ እኔ የሠራሁት ይህ ቤት ምንድን ነው?'),
  ('d66b2bf5-a90d-542c-a7d7-269c2b90bc42', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 8, 19, 'ነገር ግን አቤቱ አምላኬ ሆይ፥ ወደ ባሪያህ ጸሎትና ልመና ተመልከት፤ ባሪያህ በዚች ዕለት በፊትህ የሚጸልየውን ጸሎትና ልመናውን ስማ።'),
  ('6208697a-d547-5c8c-ae41-6d2569ba2ef0', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 9, 20, 'ባሪያህ በዚህ ቤት የሚጸልየውን ጸሎት ትሰማ ዘንድ፦ በዚያ ስሜ ይሆናል ወዳልኸው ስፍራ፥ ወደዚህ ቤት ዐይኖችህ ቀንና ሌሊት የተገለጡ ይሁኑ።'),
  ('9189dbe0-51b5-5946-af5b-b7fd02f76de5', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 10, 21, 'ባሪያህና ሕዝብህ እስራኤል በዚህ ስፍራ የሚጸልዩትን ልመና ስማ፤ በተዘጋጀው በማደሪያህ በሰማይ ስማ፤ ሰምተህም ይቅር በል።'),
  ('42fa7fa3-be43-5a9b-acf9-9d6ff800b025', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 11, 22, '“ሰው ባልንጀራውን ቢበድል፥ ይምልም ዘንድ በላዩ መሐላ ቢጭንበት፥ እርሱም መጥቶ በዚህ ቤት በመሠዊያህ ፊት ቢናዘዝ፥'),
  ('c72a85be-e1e0-5184-a907-6cc49b19f9ac', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 12, 23, 'በሰማይ ስማ፤ አድርግም፤ በባሪያዎችህም ላይ ዳኛ ሁን፤ በበደለኛውም ላይ ፍረድ፤ መንገዱንም በራሱ ላይ መልስበት፤ ንጹሑንም አጽድቀው፤ እንደ ጽድቁም ክፈለው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('45e70879-9ff2-521f-afff-cf995a1bfd95', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 13, 24, '“ሕዝብህ እስራኤል አንተን ስለ በደሉ በጠላት ፊት ድል ተመትተው ወደ አንተ ቢመለሱ፥ ስምህንም ቢያከብሩ፥ በዚህም ቤት በፊትህ ቢጸልዩና ቢለምኑህ፥'),
  ('4572490a-0c7b-57c4-a2e3-7337c653f25d', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 14, 25, 'አንተ በሰማይ ስማ፤ የሕዝብህንም የእስራኤልን ኀጢአት ይቅር በል፤ ለእነርሱም፥ ለአባቶቻቸውም ወደ ሰጠሃት ምድር መልሳቸው።'),
  ('e2b64fb2-eb04-556b-ae75-713d0ce0548e', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 15, 26, '“አንተን ስለ በደሉ ሰማያት በተዘጉ ጊዜ፥ ዝናብም ባልዘነበ ጊዜ፥ በዚህ ስፍራ ቢጸልዩ፥ ስምህንም ቢያከብሩ፥ ባዋረድሃቸውም ጊዜ ከኀጢአታቸው ቢመለሱ፥'),
  ('3dfb6910-51a7-543a-acf2-236757dc63c6', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 16, 27, 'አንተ በሰማይ ስማ፤ የባሪያዎችህንና የሕዝብህን የእስራኤልን ኀጢአት ይቅር በል፥ የሚሄዱበትንም መልካም መንገድ አሳያቸው፤ ለሕዝብህም ርስት አድርገህ ለሰጠሃት ምድር ዝናብን ስጥ።'),
  ('cc77cca9-cba7-5244-aafc-c7f66533e149', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 17, 28, '“በምድር ላይ ራብ፥ ወይም ቸነፈር፥ ወይም ዋግ፥ ወይም አረማሞ፥ ወይም አንበጣ፥ ወይም ኩብኩባ ቢሆን፥ ጠላቶቻቸውም የሀገሩን ከተሞች ከብበው ቢያስጨንቁአቸው፥ ማናቸውም መቅሠፍትና ደዌ ቢሆን፥'),
  ('4411e317-3267-5fd0-a169-bffb40dfbe11', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 18, 29, 'ማንም ሰው ወይም ሕዝብህ እስራኤል ሁሉ፥ ማናቸውም ሰው ሕማሙንና ኀዘኑን ዐውቆ ጸሎትና ልመና ቢያደርግ፥ እጆቹንም ወደዚህ ቤት ቢዘረጋ፥'),
  ('2b61121e-4369-5eee-aa40-5e7b0a68eb41', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 19, 30, 'አንተ በተዘጋጀው በማደሪያህ በሰማይ ስማው፤ ይቅርም በለው፤ ልቡን ለምታውቀው ሰው ሁሉ እንደ መንገዱ ሁሉ መጠን ክፈለው፤ አንተ ብቻ የሰውን ልጆች ልብ ታውቃለህና።'),
  ('1e8e1c1e-19c7-5973-aad1-3b184b6ac54d', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 20, 31, 'ለአባቶቻችን በሰጠኸው ምድር ላይ በሚኖሩበት ዘመን ሁሉ ይፈሩህ ዘንድ በመንገዶችህም ይሄዱ ዘንድ።'),
  ('66c03355-d23e-5c51-aa7d-458a713a8ae8', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 21, 32, '“ከሕዝብህ ከእስራኤል ያልሆነ እንግዳ ስለ ታላቁ ስምህ፥ ስለ ብርቱውም እጅህ፥ ስለ ተዘረጋውም ክንድህ፥ ከሩቅ ሀገር መጥቶ በዚህ ቤት በጸለየ ጊዜ፥'),
  ('466cd5ec-cff0-52a0-a6b2-4fe8a8e13e73', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 22, 33, 'አንተ በማደሪያህ በሰማይ ስማ፤ የምድርም አሕዛብ ሁሉ ስምህን ያውቁ ዘንድ፥ እንደ ሕዝብህም እንደ እስራኤል ይፈሩህ ዘንድ፥ በዚህም በሠራሁት ቤት ስምህ እንደ ተጠራ ያውቁ ዘንድ፥ እንግዳው የሚለምንህን ሁሉ አድርግ።'),
  ('f1d9ab55-8f93-5e4a-abe9-20eab40ac2eb', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 23, 34, '“ሕዝብህም ጠላቶቻቸውን ለመውጋት አንተ በምትልካቸው መንገድ ቢወጡ፥ አንተም ወደ መረጥሃት ወደዚህች ከተማ፥ እኔም ለስምህ ወደ ሠራሁት ቤት ለአንተ ቢጸልዩ፥'),
  ('cc69ef7b-d43b-546b-ae7b-9c5e2e471dd2', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 24, 35, 'ጸሎታቸውንና ልመናቸውን በሰማይ ስማ፤ ፍርድንም ፍረድላቸው።'),
  ('0cbdfca8-f16a-595d-a30f-27d49cecbc24', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 25, 36, '“የማይበድል ሰው የለምና አንተን ቢበድሉ፥ ብትቈጣቸውም፥ ለጠላቶቻቸውም አሳልፈህ ብትሰጣቸው፥ ሩቅም ወይም ቅርብ ወደ ሆነ ሀገር ጠላቶቻቸው ቢማርኩአቸው፥'),
  ('8fdb4204-15ea-576d-afba-fc3d7ef9d078', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 26, 37, 'በተማረኩባትም ሀገር ሆነው በልባቸው ንስሓ ቢገቡ፥ በምርኮአቸውም ሀገር ሳሉ ተመልሰው፦ ኀጢአት ሠርተናል፥ በድለንማል፥ ክፉም አድርገናል ብለው ቢለምኑህ፤'),
  ('d534a7d0-c76a-5abb-a83c-46901b609b5b', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 27, 38, 'በተማረኩበትም ሀገር ሳሉ በፍጹም ልባቸውና በፍጹም ነፍሳቸው ወደ አንተ ቢመለሱ፥ ለአባቶቻቸውም ወደ ሰጠሃት ወደ ምድራቸው፥ ወደ መረጥሃትም ከተማ፥ ለስምህም ወደ ሠራሁት ቤት ቢጸልዩ፥'),
  ('29b6cf98-79ef-519e-a897-02877aca76c6', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 28, 39, 'ጸሎታቸውንና ልመናቸውን በተዘጋጀ በማደሪያህ በሰማይ ስማ፤ ፍርድንም አድርግላቸው፤ አንተንም የበደሉህን ሕዝብህን ይቅር በል።'),
  ('ed372e61-c8f1-52b7-ac03-243d006ac065', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 29, 40, '“አሁንም አምላኬ ሆይ፥ በዚህ ስፍራ ወደሚሆነው ጸሎት ዐይኖችህ የተገለጡ፥ ጆሮዎችህም የሚያደምጡ ይሁኑ።'),
  ('6f3bfb80-2558-57e4-a3be-701e1c459817', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 30, 41, 'አሁንም አቤቱ አምላክ ሆይ፥ ከኀይልህ ታቦት ጋር ወደ ዕረፍትህ ተነሣ፤ አቤቱ አምላክ ሆይ፥ ካህናትህ ደኅንነትን ይልበሱ፤ ቅዱሳንህም በደስታ ደስ ይበላቸው።'),
  ('9e09131a-174d-550d-add3-8a6ae9cbbdeb', 'fed15ebe-5ed0-5457-a5eb-8a3ccf1e4a4a', '7ef9eb58-bb4b-565d-ad21-b51aaa6d7d1a', 31, 42, 'አቤቱ አምላክ ሆይ፥ ከቀባኸው ሰው ፊትህን አትመልስ፤ ለባሪያህም ለዳዊት ምሕረትን አስብ።”'),
  ('d69210af-a457-57ff-a396-79cf671b7dc7', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 1, 1, 'ሰሎሞንም ይህን ጸሎት በፈጸመ ጊዜ እሳት ከሰማይ ወርዶ የሚቃጠለውን ቍርባንና መሥዋዕቱን ሁሉ በላ፤ የእግዚአብሔርም ክብር ቤቱን ሞላ።'),
  ('89ea38d1-2558-59ef-ad84-3e62bf02ef2a', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 2, 2, 'የእግዚአብሔርም ክብር የእግዚአብሔርን ቤት ሞልቶት ነበርና ካህናቱ በዚያች ዕለት ወደ እግዚአብሔር ቤት መግባት አልቻሉም።'),
  ('7bd3d9bb-e326-552c-adf3-87d4cbb3c186', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 3, 3, 'የእስራኤልም ልጆች ሁሉ እሳቱ ሲወርድ የእግዚአብሔርም ክብር በቤቱ ላይ ሲሆን ያዩ ነበር፤ ድንጋይ በተነጠፈበትም ምድር በግንባራቸው ተደፍተው ሰገዱ፥ “እርሱ ቸር ነውና፥ ምሕረቱም ለዘለዓለም ነውና” እያሉ እግዚአብሔርን አመሰገኑ።'),
  ('1c823b8a-8f78-502d-a1f2-2515d154afa1', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 4, 4, 'ንጉሡም ሰሎሞን፥ የእስራኤልም ሕዝብ ሁሉ በእግዚአብሔር ፊት መሥዋዕት ያቀርቡ ነበር።'),
  ('a838ea1a-f1fa-56f8-ab36-d3e01e42a830', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 5, 5, 'በዚያችም ዕለት ንጉሡ ሰሎሞን ሃያ ሁለት ሺህ በሬዎችንና መቶ ሃያ ሺህ በጎችን ሠዋ። እንዲሁ ንጉሡና ሕዝቡ ሁሉ የእግዚአብሔርን ቤት ቅዳሴ አከበሩ።'),
  ('0e1fb1a5-53b8-58d2-a392-5db3d04344bf', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 6, 6, 'ካህናቱም በየሥርዐታቸው ሌዋውያኑም ደግሞ፥ “ምሕረቱ ለዘለዓለም ነውና እግዚአብሔርን አመስግኑ” የሚለውን የዳዊትን መዝሙር እየዘመሩ፥ ንጉሡ ዳዊት እግዚአብሔርን ለማመስገን የሠራውን የእግዚአብሔርን የዜማ ዕቃ ይዘው ቆመው ነበር፤ ካህናቱም በፊታቸው መለከት ይነፉ ነበር፤ እስራኤልም ሁሉ ቆመው ነበር።'),
  ('03ebb759-cd2d-50e4-acdc-d7fecaacfa24', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 7, 7, 'ሰሎሞንም በእግዚአብሔር ቤት ፊት የነበረውን የአደባባዩን ውስጥ ቀደሰ፤ ሰሎሞንም የሠራው የናስ መሠዊያ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን፥ ስቡንም መያዝ አልቻለምና የሚቃጠለውን መሥዋዕትና የደኅንነቱንም መሥዋዕት፥ ስብ በዚያ አቀረበ።'),
  ('0fec927a-ae50-5c7c-a6c1-8a18e1544028', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 8, 8, 'ሰሎሞንም፥ ከእርሱም ጋር እጅግ ታላቅ ጉባኤ የሆኑ ከኤማት መግቢያ ጀምሮ እስከ ግብፅ ወንዝ ድረስ ያሉ እስራኤል ሁሉ፥ በዚያ ጊዜ ሰባት ቀን በዓል አደረጉ።'),
  ('61e297f9-4528-58ab-a95c-312653e10e64', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 9, 9, 'መሠዊያውንም ቀድሶ፥ ሰባት ቀን በዓል አድርጎ ነበርና በስምንተኛው ቀን የፍጻሜ በዓል አደረገ።'),
  ('220c79f6-36b9-5b17-a4e1-c10ce18075f6', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 10, 10, 'በሰባተኛውም ወር በሃያ ሦስተኛው ቀን ሕዝቡን ወደ ድንኳናቸው አሰናበተ፤ እግዚአብሔር ለዳዊትና ለሰሎሞን፥ ለሕዝቡም ለእስራኤል ስላደረገው ቸርነት በልባቸው ደስ ብሎአቸው ሄዱ።'),
  ('d9a92f2d-1694-5c09-afe8-fc1efe17d6cf', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 11, 11, 'ሰሎሞንም የእግዚአብሔርን ቤትና የንጉሡን ቤት፥ በእግዚአብሔር ቤትና በራሱ ቤት ይሠራው ዘንድ በልቡ ያሰበውን ሁሉ ጨረሰ፤ አከናወነም።'),
  ('057615e7-7321-5044-a1c5-f230bd4ff4dd', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 12, 12, 'እግዚአብሔርም ለሰሎሞን በሌሊት ተገልጦ እንዲህ አለው፥ “ ጸሎትህን ሰምቻለሁ፤ ይህንም ስፍራ ለራሴ ለመሥዋዕት ቤት መርጫለሁ።'),
  ('31b6d8fb-dc05-50bb-a9ca-3884b426f6e2', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 13, 13, 'ዝናብ እንዳይወርድ ሰማያቱን ብዘጋ፥ ወይም የሚያፈራውን እንጨት ሁሉ ይበላ ዘንድ አንበጣን ባዝዘው፥ ወይም በሕዝቤ ላይ ቸነፈር ብሰድድ፥'),
  ('0af2489b-172b-50fa-ace4-c2ab6e77a96d', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 14, 14, 'በስሜ የተጠሩት ሕዝቤ ሰውነታቸውን አዋርደው ቢጸልዩ፥ ፊቴንም ቢፈልጉ፥ ከክፉ መንገዳቸውም ቢመለሱ፥ በሰማይ ሆኜ እሰማለሁ፥ ኀጢአታቸውንም ይቅር እላለሁ፤ ምድራቸውንም እፈውሳለሁ።'),
  ('b3d47ad9-b1a3-5540-a9e3-dcda18ef1dbf', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 15, 15, 'አሁንም በዚህ ስፍራ ለሚጸለይ ጸሎት ዐይኖች ይገለጣሉ፤ ጆሮዎችም ያዳምጣሉ።'),
  ('fefedddc-2e80-5bf0-aa2f-eacf8ed4fb22', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 16, 16, 'አሁንም ስሜ ለዘለዓለም በዚያ ይኖር ዘንድ ይህን ቤት መርጫለሁ፤ ቀድሻለሁም፤ ዐይኖችና ልቤም ዘወትር በዚያ ይሆናሉ።'),
  ('2ffca34c-5358-52a6-a6e2-1faed4b7760a', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 17, 17, 'አንተም ደግሞ አባትህ ዳዊት እንደ ሄደ በፊቴ ብትሄድ፥ እንዳዘዝሁም ሁሉ ብታደርግ፥ ሥርዐቴንና ፍርዴንም ብትጠብቅ፥'),
  ('2dfb45d0-78f4-547e-aea0-d5560d2528d3', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 18, 18, 'ከአባትህ ከዳዊት ጋር፦ ‘በእስራኤል ላይ አለቃ የሚሆን ከዘርህ አይታጣም’ ብዬ ቃል ኪዳን እንዳደረግሁ የመንግሥትህን ዙፋን አጸናለሁ።'),
  ('9e93eaa2-3dbc-5d4c-aec7-6ed0199cd8f2', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 19, 19, '“እናንተ ግን ብትመለሱ፥ የሰጠኋችሁን ሥርዐቴንና ትእዛዜን ብትተዉ፥ ሄዳችሁም ሌሎችን አማልክት ብታመልኩ፥ ብትሰግዱላቸውም፥'),
  ('045cbfdc-e478-5814-a459-bf198beadbe3', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 20, 20, 'እኔም ለአባቶቻችሁ ከሰጠኋቸው ምድር እነቅላችኋለሁ፤ ለስሜም የቀደስሁትን ይህን ቤት ከፊቴ እጥለዋለሁ፤ በአሕዛብም ሁሉ መካከል ምሳሌና ተረት አደርገዋለሁ።'),
  ('5f6d2588-72e3-5ef6-a337-797c0a371afa', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 21, 21, 'ከፍ ከፍ ብሎ የነበረውንም ይህን ቤት እያየ በዚያ የሚያልፍ መንገደኛ ሁሉ፦ ‘እግዚአብሔር በዚህ ሀገርና በዚህ ቤት ስለ ምን እንዲህ አደረገ?’ ብሎ ይደነቃል።'),
  ('2f744114-ed06-5339-ab04-b3055c415df7', 'a8afe303-d047-5683-af79-8863a15077ef', 'e9374bb3-eda3-5821-a525-e22ba45cb24d', 22, 22, 'መልሰውም፦ ከግብፅ ምድር ያወጣቸውን ያባቶቻቸውን አምላክ እግዚአብሔርን ትተው ሌሎችን አማልክት ስለ ተከተሉ፥ ስለ ሰገዱላቸውም፥ ስለ አመለኩአቸውም፥ ስለ አገለገሏቸውም፥ ስለዚህ ይህን ክፉ ነገር ሁሉ አመጣባቸው” ይላሉ።'),
  ('30f9bb9d-8c85-59c5-ad5c-2b97ddfb9959', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 1, 1, 'እንዲህም ሆነ፤ ሰሎሞን የእግዚአብሔርን ቤትና የራሱን ቤት የሠራበት ሃያ ዓመት በተፈጸመ ጊዜ፥'),
  ('05c14617-1220-5bef-a408-acd730470079', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 2, 2, 'ኪራም ለሰሎሞን የሰጠውን ከተሞች ሰሎሞን ሠራቸው፤ የእስራኤልንም ልጆች አኖረባቸው።'),
  ('5dd29660-a52f-5cb2-aaf4-036a963d137d', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 3, 3, 'ሰሎሞንም ወደ ኤማትሱባ ሄደ፤ በረታባትም።'),
  ('d51c3d45-da50-5c1b-a8b7-ee67cca1a4d7', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 4, 4, 'በምድረ በዳም ያለውን ተድሞርን፥ በኤማትም የጸኑ ከተሞችን ሁሉ ሠራ።'),
  ('b352cb8c-969d-5010-a4d5-281ec6c6292e', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 5, 5, 'ደግሞም ቅጥርና መዝጊያ፥ መወርወሪያም የነበራቸውን የተመሸጉትን ከተሞች ላይኛውን ቤትሖርን፥ ታችኛውንም ቤትሖርን ሠራ።'),
  ('2e253752-48ad-5144-a057-855532cb4474', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 6, 6, 'ባዕላትንም፥ ለሰሎሞንም የነበሩትን የዕቃ ቤት ከተሞች ሁሉ፥ የሰረገላውንም ከተሞች ሁሉ፥ የፈረሰኞችንም ከተሞች፥ በኢየሩሳሌምም፥ በሊባኖስም፥ በመንግሥቱም ምድር ሁሉ ሰሎሞን ይሠራ ዘንድ የወደደውን ሁሉ ሠራ።'),
  ('23c7452c-13d6-5646-a8e4-cfb6d7161aff', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 7, 7, 'ከኬጤዎናውያን፥ ከአሞሬዎናውያን፥ ከፌርዜዎናውያንም፥ ከኤዎናውያንም፥ ከኢያቡሴዎናውያንም የቀሩትን፥ ከእስራኤል ወገን ያልሆኑትን ሕዝብ ሁሉ፥'),
  ('592977d8-9641-52a7-aca4-4c738950b2fa', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 8, 8, 'የእስራኤልም ልጆች ያላጠፉአቸውን፥ በኋላቸውም በምድር ላይ የቀሩትን ልጆቻቸውን ሰሎሞን እስከ ዛሬ ድረስ ገባሮች አደረጋቸው።'),
  ('54f15818-cf81-5efe-ab0f-6509e67e164b', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 9, 9, 'ሰሎሞንም በመንግሥቱ ከእስራኤል ልጆች ማንንም አገልጋይ አላደረገም፤ እነርሱ ሰልፈኞች፥ የሹሞችም አለቆች፥ የሰረገሎችና የፈረሰኞች ባልደራሶች ነበሩና።'),
  ('a3228625-e538-5b62-af1f-bcb89d7245e3', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 10, 10, 'እነዚህም በሕዝቡ ላይ ያለውን ሥራ የሚቈጣጠሩ የንጉሡ የሰሎሞን ዓይነተኞች አለቆች ሁለት መቶ አምሳ ነበሩ።'),
  ('257ae071-6a14-5c4c-a3ae-4c92a50f2606', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 11, 11, 'ሰሎሞንም፥ “የእግዚአብሔር ታቦት የገባችበት ስፍራ ቅዱስ ነውና ሚስቴ በእስራኤል ንጉሥ በዳዊት ቤት አትቀመጥም” ሲል የፈርዖንን ልጅ ከዳዊት ከተማ ወደ ሠራላት ቤት አወጣት።'),
  ('aee61151-1df8-5664-aea8-9e1dc4d0893e', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 12, 12, 'በዚያ ጊዜም ሰሎሞን በእግዚአብሔር ቤት ፊት በሠራው በእግዚአብሔር መሠዊያ ላይ ለእግዚአብሔር የሚቃጠለውን መሥዋዕት አቀረበ።'),
  ('0b949eb3-7442-5a21-aeec-f00e4f2abcbd', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 13, 13, 'ሙሴም እንዳዘዘ እንደ ሥርዐታቸው በየቀኑ ሁሉ፥ በየሰንበታቱም፥ በየመባቻዎቹም፥ በየበዓላቱም፥ በየዓመቱ ሦስት ጊዜ በየቂጣው በዓልና በየሰባቱ ሱባዔ በዓል፥ በየዳሱም በዓል ቍርባን ያቀርቡ ነበር።'),
  ('61381c1d-73c1-5ddb-a07e-856c0a3d2fd7', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 14, 14, 'የእግዚአብሔርም ሰው ዳዊት እንዲህ አዝዞ ነበርና ካህናቱን እንደ አባቱ እንደ ዳዊት ሥርዐት በየአገልግሎታቸው ሰሞን ከፈላቸው፤ ሌዋውያንም እንደ ሥርዐታቸው ያመሰግኑ ዘንድ፥ በካህናቱም ፊት ያገለግሉ ዘንድ በየሰሞናቸው ከፈላቸው፤ በረኞቹንም ደግሞ በየበሩ ሁሉ በየሰሞናቸው ከፈላቸው።'),
  ('4a194c43-b02c-5499-af74-d4492ceee3f1', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 15, 15, 'እነርሱም ንጉሡ ስለ ነገሩ ሁሉና ስለ መዝገቡ ካህናቱንና ሌዋውያኑን ያዘዘውን ነገር ሁሉ አልተላለፉም።'),
  ('e53f183f-2c57-50b2-ae0a-6d879535b6b3', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 16, 16, 'እነሆ፥ መሠረቱ ከተጣለ ጀምሮ ሰሎሞን የእግዚአብሔርን ቤት እስከ ፈጸመ ድረስ ሥራው ሁሉ የተዘጋጀ ነበረ። የእግዚአብሔርም ቤት ተፈጸመ።'),
  ('020793e9-0fd7-56d0-a48b-fd20ee04bfce', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 17, 17, 'ሰሎሞንም የዚያን ጊዜ በኤዶምያስ ምድር በባሕር ዳር ወዳሉ ወደ ጋሴዎንጋብርና ወደ ኤላት ሄደ።'),
  ('405335e6-6f6f-5ff4-a3c0-d08284805fed', '2ef8bd07-b75f-5aa7-a531-2688a15e341a', 'd710998c-9374-50c4-ae21-a5b3d9f3bf5a', 18, 18, 'ኪራምም መርከቦችንና የባሕርን ነገር የሚያውቁትን መርከበኞች በአገልጋዮቹ እጅ ላከለት፤ እነርሱም ከሰሎሞን አገልጋዮች ጋር ወደ ሴፌር መጡ፤ ከዚያም አራት መቶ አምሳ መክሊት ወርቅ ወስደው ወደ ንጉሡ ወደ ሰሎሞን አመጡ።'),
  ('fc07136b-6368-59d7-af52-c05e72aa575b', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 1, 1, 'የሳባም ንግሥት የሰሎሞንን ዝና በሰማች ጊዜ በግመሎች ላይ ሽቱና ብዙ ወርቅ፥ የከበረም ዕንቍ አስጭና ከታላቅ ጓዝ ጋር ሰሎሞንን በኢየሩሳሌም በእንቆቅልሽ ትፈትነው ዘንድ መጣች፤ ወደ ሰሎሞንም በገባች ጊዜ በልብዋ ያለውን ሁሉ አጫወተችው።'),
  ('11946862-a3f3-5f04-a73d-152d45e70c9b', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 2, 2, 'ሰሎሞንም የጠየቀችውን ሁሉ ፈታላት፤ ሰሎሞንም ያልፈታው ነገር አልነበረም።'),
  ('3eed8d20-73ff-58b9-a6ee-62da449503dd', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 3, 3, 'የሳባም ንግሥት የሰሎሞንን ጥበብ፥ ሠርቶትም የነበረውን ቤት፤'),
  ('b54af586-4ede-518d-afda-fca12dfe4d9a', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 4, 4, 'የማዕዱንም መብል፥ የብላቴኖቹንም አቀማመጥ፥ የሎሌዎቹንም ሥርዐት፥ አለባበሳቸውንም፥ ጠጅ አሳላፊዎቹንም፥ አለባበሳቸውንም፥ በእግዚአብሔርም ቤት የሚያሳርገውን መሥዋዕት ባየች ጊዜ ተደነቀች።'),
  ('d2b4626e-9ce0-5f6b-a680-8c85f6fee388', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 5, 5, 'ንጉሡንም አለችው፥ “ስለ ነገርህና ስለ ጥበብህ በሀገሬ ሳለሁ የሰማሁት ዝና እውነት ነው።'),
  ('fac5a610-d862-5287-a58a-3f96cb11a6c4', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 6, 6, 'እኔ ግን መጥቼ በዐይኔ እስካየሁ ድረስ የነገሩኝን አላመንሁም፤ እነሆ፥ የጥበብህን ታላቅነት እኩሌታ አልነገሩኝም፤ በሀገሬ ከሰማሁትም ዝና ይልቅ ጨመርህልኝ።'),
  ('4cc867f8-5a76-58ef-a780-54a13a6ea864', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 7, 7, 'እነዚህ ሰዎችህ ምስጉኖች ናቸው፤ በፊትህ ሁልጊዜ የሚቆሙና ጥበብህን የሚሰሙ እነዚህ አገልጋዮችህም ምስጉኖች ናቸው።'),
  ('06d93a9b-7e32-5333-aa2a-3fb18070c672', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 8, 8, 'በአምላክህ በእግዚአብሔር ፊት ንጉሥ እንድትሆን በዙፋኑ ላይ ያስቀምጥህ ዘንድ የወደደህ አምላክህ እግዚአብሔር ቡሩክ ይሁን፤ አምላክህ እግዚአብሔር እስራኤልን ለዘለዓለም ያጸናቸው ዘንድ ወድዶአቸዋልና ስለዚህ ፍርድንና ጽድቅን ታደርግ ዘንድ በላያቸው አነገሠህ።”'),
  ('677dad04-ca35-5ad1-aff4-6e7b61bc152a', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 9, 9, 'ለንጉሡም መቶ ሃያ መክሊት ወርቅ፥ እጅግም ብዙ ሽቱ፥ የከበረም ዕንቍ ሰጠችው፤ የሳባም ንግሥት ለንጉሡ ለሰሎሞን እንደ ሰጠችው ያለ ሽቱ ከቶ አልነበረም።'),
  ('ebe509e9-a8a9-52c1-a93d-d660e992e733', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 10, 10, 'የኪራም አገልጋዮችና የሰሎሞን አገልጋዮችም ከሴፌር ለሰሎሞን ወርቅ አመጡ፤ የሰንደል እንጨትና የከበረ ዕንቍም ደግሞ አመጡ።'),
  ('c18de826-1621-51dd-ae75-9a214b0aaebe', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 11, 11, 'ንጉሡም ከሰንደሉ እንጨት ለእግዚአብሔር ቤትና ለንጉሡ ቤት ደርብ፥ ለመዘምራኑም መሰንቆና በገና አደረገ፤ እንደዚህም ያለ በይሁዳ ምድር ከቶ አልታየም ነበር።'),
  ('90f8a20e-581c-5226-a0d3-cdc0151e5ae6', '7a503c9e-b175-532b-a032-157b37428a68', '9ee0f766-8ff3-5174-a83f-7d029344c825', 12, 12, 'እርስዋም ለንጉሡ ለሰሎሞን ካመጣችው የበለጠ፥ ንጉሡ ሰሎሞን የወደደችውን ሁሉ፥ ከእርሱም የለመነችውን ሁሉ ለሳባ ንግሥት ሰጣት፤ እርስዋም ተመልሳ ከአገልጋዮችዋ ጋር ወደ ሀገርዋ ሄደች።'),
  ('6de03389-a766-57f6-a97c-a207c4eec634', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 1, 13, 'በየዓመቱም ወደ ሰሎሞን የሚመጣ የወርቅ ሚዛን ስድስት መቶ ስድሳ ስድስት መክሊት ወርቅ ነበረ።'),
  ('53595689-6c06-5010-a3d9-0ee72ce27594', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 2, 14, 'ነጋድራሶችና ነጋዴዎች ከሚያመጡት ሌላ የዓረብ ነገሥታት ሁሉ፥ የምድሩም ሹሞች ወደ ንጉሡ ሰሎሞን ወርቅና ብር ያመጡ ነበር'),
  ('c1eb8425-aafd-522b-a4cd-f4c25b92efe4', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 3, 15, 'ንጉሡም ሰሎሞን በጥፍጥፍ ወርቅ ሁለት መቶ አላባሽ አግሬ ጋሻ አሠራ፤ በየአንዳንዱም አላባሽ አግሬ ጋሻ ውስጥ የገባው የጠራ ወርቅ ስድስት መቶ ሰቅል ነበረ።'),
  ('cc0528a4-0cdf-51e7-a6d2-905e5ce34c90', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 4, 16, 'ከጥፍጥፍም ወርቅ ሦስት መቶ ጋሻ አሠራ፤ በየአንዳንዱም ጋሻ የገባው ወርቅ ሦስት መቶ ሰቅል ነበረ፤ ንጉሡም የሊባኖስ ዱር በተባለው ቤት ውስጥ አኖራቸው።'),
  ('298be4a4-4350-5216-ae72-5a9ea7eeea01', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 5, 17, 'ንጉሡም ደግሞ ከዝሆን ጥርስ ታላቅ ዙፋን አሠራ፤ በጥሩ ወርቅም ለበጠው።'),
  ('9c2ac7d4-af90-537b-ac12-ee7d146ffdca', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 6, 18, 'ወደ ዙፋኑም የሚያስሄዱ፥ በወርቅ የተለበጡ ስድስት እርከኖች ነበሩ፤ በዚህና በዚያ በመቀመጫው አጠገብ ሁለት የክንድ መደገፊያዎች ነበሩበት፤ በመደገፊያዎቹም አጠገብ ሁለት አንበሶች ቆመው ነበር።'),
  ('7c1f4e3e-1eb4-542c-a947-a71c4808a2b2', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 7, 19, 'በስድስቱም እርከኖች ላይ በዚህና በዚያ ዐሥራ ሁለት አንበሶች ቆመው ነበር፤ በመንግሥታት ሁሉ እንዲህ ያለ ሥራ አልተሠራም።'),
  ('8edf5a5b-5d5e-525a-a356-3edb0705c333', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 8, 20, 'ንጉሡም ሰሎሞን የሚጠጣበት ዕቃ ሁሉ የወርቅ ነበረ፤ የሊባኖስ ዱር በተባለውም ቤቱ የሚገለገልበት ዕቃ ሁሉ ጥሩ ወርቅ ነበረ፤ በሰሎሞንም ዘመን ብር ከቶ አይቈጠርም ነበር።'),
  ('10e7d6b2-2ff8-561c-a29a-02d74fd64899', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 9, 21, 'ለንጉሡም ከኪራም አገልጋዮች ጋር ወደ ተርሴስ የሚሄዱ መርከቦች ነበሩት፤ በሦስት በሦስት ዓመትም አንድ ጊዜ የተርሴስ መርከቦች ወርቅና ብር፥ የዝሆንም ጥርስና ዝንጀሮ ይዘው ይመጡ ነበር።'),
  ('6cd2d452-9a17-5275-a5a2-f2827048739f', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 10, 22, 'ንጉሡም ሰሎሞን ከምድር ነገሥታት ሁሉ በባለጠግነትና በጥበብ በለጠ።'),
  ('fcd733c8-d491-5678-a8ae-5883096a7479', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 11, 23, 'የምድርም ነገሥታት ሁሉ እግዚአብሔር በልቡ ያኖረውን ጥበቡን ይሰሙ ዘንድ የሰሎሞንን ፊት ሊያዩ ይመኙ ነበር።'),
  ('804b72dd-7194-5da1-aef5-9cbed17bc46a', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 12, 24, 'ከእነርሱም እያንዳንዱ ገጸ በረከቱን፥ የወርቅንና የብርን ዕቃ፥ ልብስንና የጦር መሣሪያን፥ ሽቱውንም፥ ፈረሶችንና በቅሎዎችን እየያዘ በየዓመቱ ያመጣ ነበር።'),
  ('44610849-8db7-5a60-a5f2-943fe693f538', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 13, 25, 'ሰሎሞንም ለሰረገሎች አራት ሺህ እንስት ፈረሶችና ዐሥራ ሁለት ሺህ ፈረሰኞች ነበሩት፤ በሰረገሎችም ከተሞች፥ ከንጉሡ ጋር በኢየሩሳሌም አኖራቸው።'),
  ('40b14bd2-fd34-5cf8-a074-a67e58cdb977', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 14, 26, 'ከኤፍራጥስም ወንዝ ጀምሮ እስከ ፍልስጥኤም ምድርና እስከ ግብፅ ዳርቻ ድረስ ባሉ ነገሥታት ሁሉ ላይ ነገሠ።'),
  ('9188882f-a429-57b2-a5ba-94b03486e636', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 15, 27, 'ንጉሡም ወርቁንና ብሩን በኢየሩሳሌም እንደ ድንጋይ፥ የዝግባውንም እንጨት በቆላ እንደሚበቅል ሾላ ብዛት አደረገው።'),
  ('c867a5de-5292-5c95-a2a9-12f036dbeb82', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 16, 28, 'ለሰሎሞንም ፈረሶች ከግብፅና ከየሀገሩ ሁሉ ይመጡለት ነበር።'),
  ('7c63ef36-b323-5e8f-a693-9c2046e91d0f', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 17, 29, 'የቀረውም ፊተኛውና ኋለኛው የሰሎሞን ነገር በነቢዩ በናታን ታሪክ፥ በሴሎናዊውም በአኪያ ትንቢት፥ ስለ ናባጥም ልጅ ስለ ኢዮርብዓም ባየው በባለ ራእዩ በኢዩሔል ራእይ የተጻፈ አይደለምን?'),
  ('14063af0-2bc3-587f-a0bc-4dee9b01375d', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 18, 30, 'ሰሎሞንም በኢየሩሳሌም በእስራኤል ሁሉ ላይ አርባ ዓመት ነገሠ።'),
  ('35f6da5f-7026-5c0b-a526-dc12240bcadd', '7a503c9e-b175-532b-a032-157b37428a68', 'a0100ce4-a61a-5ddf-a2e3-d2dd1f14df65', 19, 31, 'ሰሎሞንም ከአባቶቹ ጋር አንቀላፋ፤ በአባቱም በዳዊት ከተማ ቀበሩት፤ ልጁም ሮብዓም በእርሱ ፋንታ ነገሠ።'),
  ('3900f85e-62b7-58f2-ae31-b839ec5c4743', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 1, 1, 'እስራኤልም ሁሉ ያነግሡት ዘንድ ወደ ሴኬም መጥተው ነበርና ሮብዓም ወደ ሴኬም ሄደ።'),
  ('e4ad29f8-5935-5f3c-a504-2df18bcd94a9', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 2, 2, 'የናባጥ ልጅ ኢዮርብዓምም ከንጉሡ ከሰሎሞን ፊት ሸሽቶ በግብፅ ይኖር ነበርና ይህን በሰማ ጊዜ ኢዮርብዓም ከግብፅ ተመለሰ።'),
  ('d57adede-cf8e-58ce-a54c-ad84ec3af4dd', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 3, 3, 'ልከውም ጠሩት፤ ኢዮርብዓምና እስራኤልም ሁሉ ወደ ሮብዓም መጥተው እንዲህ አሉት፦'),
  ('7dcf1e4b-69d8-5672-a298-a3d6dddc8eb1', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 4, 4, '“አባትህ ቀንበር አክብዶብን ነበር፤ አሁንም አንተ ጽኑውን የአባትህን አገዛዝ፥ በላያችንም የጫነውን የከበደውን ቀንበር አቅልልልን፥ እኛም እንገዛልሃለን።”'),
  ('9ebb0221-e1eb-5a76-a115-3f34ce8f4aba', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 5, 5, 'እርሱም፥ “ሂዱ ከሦስት ቀን በኋላ ወደ እኔ ተመለሱ” አላቸው። ሕዝቡም ሄዱ።'),
  ('05bce85f-0fc9-523f-a7b5-6ccc8e62f0df', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 6, 6, 'ንጉሡም ሮብዓም፥ “ለዚህ ሕዝብ እመልስለት ዘንድ የምትመክሩኝ ምንድን ነው?” ብሎ አባቱ ሰሎሞን በሕይወት ሳለ በፊቱ ይቆሙ የነበሩትን ሽማግሌዎች ሰበሰበ።'),
  ('e2eba737-7025-5dc7-a5e8-c093666dff62', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 7, 7, 'እነርሱም፥ “በዚች ዕለት ለዚህ ሕዝብ ቸርነት ብታደርግላቸው፥ ደስም ብታሰኛቸው፥ መልካም ነገርንም ብትናገራቸው፥ ሁልጊዜ አገልጋዮች ይሆኑልሃል” ብለው ተናገሩት።'),
  ('4829faa5-a960-5a74-ab6e-8f807cadf65e', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 8, 8, 'እርሱ ግን ሽማግሌዎች የመከሩትን ነገር ትቶ ከእርሱ ጋር ካደጉትና በፊቱ ይቆሙ ከነበሩት ብላቴኖች ጋር ተማከረ።'),
  ('dab12b8d-98a7-5e86-a294-b94cb8e1c43f', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 9, 9, 'እርሱም፥ “አባትህ የጫነብንን ቀንበር አቅልልልን ለሚሉኝ ሕዝብ እመልስላቸው ዘንድ የምትመክሩኝ ምንድን ነው?” አላቸው።'),
  ('9e8d9036-8425-59e9-a841-baa770b55b79', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 10, 10, 'ከእርሱም ጋር ያደጉት ብላቴኖች፥ “አባትህ ቀንበር አክብዶብን ነበር፤ አንተ ግን አቅልልልን ለሚሉህ ሕዝብ፦ ታናሺቱ ጣቴ ከአባቴ ወገብ ትወፍራለች፤'),
  ('dbdde19c-004e-57f1-ab06-02c794eb8b32', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 11, 11, 'አሁንም አባቴ ከባድ ቀንበር ጭኖባችሁ ነበር፤ እኔ ግን በቀንበራችሁ ላይ እጨምራለሁ፤ አባቴ በአለንጋ ገርፎአችሁ ነበር፤ እኔ ግን በጊንጥ እገርፋችኋለሁ በላቸው” ብለው ነገሩት።'),
  ('5067da39-26f5-5b21-aaa9-c3db2a1de650', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 12, 12, 'ንጉሡም፥ “በሦስተኛው ቀን ወደ እኔ ተመለሱ” ብሎ እንደ ተናገረ ኢዮርብዓምና ሕዝቡ ሁሉ በሦስተኛው ቀን ወደ ሮብዓም መጡ።'),
  ('e4b6d617-6306-5bb5-a20e-566e4b22f0e2', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 13, 13, 'ንጉሡም ጽኑ ምላሽ መለሰላቸው፤ ንጉሡም ሮብዓም የሽማግሌዎቹን ምክር ትቶ፦'),
  ('fd74b091-c41c-57fc-a0e8-4260933f5674', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 14, 14, '“አባቴ ቀንበር አክብዶባችሁ ነበር፤ እኔ ግን እጨምርበታለሁ፤ አባቴ በአለንጋ ገርፎአችሁ ነበር፤ እኔ ግን በጊንጥ እገርፋችኋለሁ” ብሎ እንደ ብላቴኖቹ ምክር ተናገራቸው።'),
  ('9e493ee3-b91f-5158-a2a6-0fef5b774179', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 15, 15, 'እግዚአብሔርም በሴሎናዊው በአኪያ ቃል ስለ ናባጥ ልጅ ስለ ኢዮርብዓም የተናገረውን ቃሉን እንዲያጸና ለውጡ ከእግዚአብሔር ዘንድ ነበርና ንጉሡ ሕዝቡን አልሰማም።'),
  ('5bcfef83-ee32-533b-ad97-c43c2c6ca178', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 16, 16, 'ንጉሡ ስላልሰማቸው ሕዝቡ፥ “በዳዊት ዘንድ ምን ክፍል አለን? በእሴይም ልጅ ዘንድ ምን ርስት አለን? እስራኤል ሆይ፥ ወደ እየድንኳኖቻችሁ ተመለሱ፤ ዳዊት ሆይ፥ አሁን ቤትህን ተመልከት” ብለው ለንጉሡ መለሱለት። እስራኤልም ሁሉ ወደ እየድንኳኖቻቸው ሄዱ።'),
  ('742bcd74-241c-5f0d-a229-0933eacc4907', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 17, 17, 'በይሁዳ ከተሞች የተቀመጡት የእስራኤል ሰዎች ግን ሮብዓምን በላያቸው አነገሡ።'),
  ('6242f308-f439-51de-a758-cfd1dda8a5d3', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 18, 18, 'ንጉሡም ሮብዓም አስገባሪውን አዶራምን ወደ እነርሱ ላከው፤ የእስራኤልም ልጆች በድንጋይ ወገሩት፤ ሞተም፤ ንጉሡም ሮብዓም ፈጥኖ ወደ ሰረገላው ወጣ፤ ወደ ኢየሩሳሌምም ሸሸ።'),
  ('25d77c6f-6c26-5601-ab64-7da2d0c705ee', 'eb8433d3-d7f7-5cae-a2c4-c8d43c9a57c2', 'e00b5595-30fe-5969-a0d3-d9f4606e12d0', 19, 19, 'እስራኤልም እስከ ዛሬ ድረስ ከዳዊት ቤት ሸፈተ።'),
  ('52d07380-b4c3-5a3d-a01e-79183b1680c1', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 1, 1, 'ሮብዓምም ወደ ኢየሩሳሌም በመጣ ጊዜ እስራኤልን ወግተው መንግሥቱን ወደ ሮብዓም ይመልሱ ዘንድ ከይሁዳና ከብንያም ቤት የተመረጡትን አንድ መቶ ሰማንያ ሺህ ሰልፈኞች ጐልማሶችን ሰበሰበ።'),
  ('8ac379d1-1a05-5821-a6d5-83759808e501', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 2, 2, 'የእግዚአብሔርም ቃል ወደ እግዚአብሔር ሰው ወደ ሰማያ እንዲህ ሲል መጣ፦'),
  ('e81d5a4a-ae9b-5086-aaec-be44feac6e0d', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 3, 3, '“ለይሁዳ ንጉሥ ለሰሎሞን ልጅ ለሮብዓም፥ በይሁዳና በብንያምም ላሉት ለእስራኤል ሁሉ፦'),
  ('6718b45f-ad7e-5f36-a9bb-d2eb2df60153', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 4, 4, '‘እግዚአብሔር እንዲህ ይላል፦ ይህ ነገር ከእኔ ዘንድ ነውና አትውጡ፤ ወንድሞቻችሁንም አትውጉ፤ እያንዳንዱም ወደ ቤቱ ይመለስ’ ብለህ ንገራቸው።” የእግዚአብሔርንም ቃል ሰሙ፤ በኢዮርብዓምም ላይ ከመሄድ ተመለሱ።'),
  ('70fe16f4-0cee-58d4-ad31-f5a045b4a6fb', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 5, 5, 'ሮብዓምም በኢየሩሳሌም ተቀመጠ፤ በይሁዳም የተመሸጉትን ከተሞች ሠራ።'),
  ('bb20636d-d91b-5506-ac31-f398a5f80185', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 6, 6, 'በይሁዳና በብንያም ያሉትንም የተመሸጉትን ከተሞች፥ ቤተ ልሔምን፥ ኤጣምን፥ ቴቁሔን፤'),
  ('6926c794-fc5c-56dd-a1b7-ed2c9f0e6e16', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 7, 7, 'ቤተሱራን፥ ሱላኮን፥ ዓዶላምን፥'),
  ('36679051-2e01-5940-a7a4-57b504354693', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 8, 8, 'ጌትን፥ መሪሳን፥ ዚፍን፥'),
  ('cf81fd8b-5577-599b-a858-a02ec28a35ff', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 9, 9, 'አዶራይምን፥ ለኪስን፥ ዓዚቃን፤'),
  ('bb250388-f6c3-5647-ab0e-44585e04e2ad', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 10, 10, 'ሶርዓን፥ ኤሎንን፥ ኬብሮንን ሠራ።'),
  ('e8eed82e-159e-58c6-ad09-cdf75458607c', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 11, 11, 'ምሽጎቹንም አጠነከረ፤ አለቆችንም አኖረባቸው፤ ምግቡንም፥ ዘይቱንም፥ የወይን ጠጁንም አከማቸባቸው።'),
  ('f4bcb13e-3390-51c9-adf7-80dd45259398', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 12, 12, 'በከተሞቹ ሁሉ አላባሽ አግሬ ጋሻና ጦርን አኖረ፤ ከተሞቹንም እጅግ አጠነከራቸው፤ ይሁዳና ብንያምም የእርሱ ወገን ነበሩ።'),
  ('638f59e8-dbd8-5bc8-a04a-b23e58e7e2eb', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 13, 13, 'በእስራኤልም ሁሉ ዘንድ የነበሩ ካህናትና ሌዋውያን ከየሀገራቸው ሁሉ ወደ እርሱ መጡ።'),
  ('03ba5aaa-595a-5184-a956-ba7d28d7fdd7', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 14, 14, 'የእግዚአብሔርም ካህናት እንዳይሆኑ ኢዮርብዓምና ልጆቹ አስለቅቀዋቸው ነበርና ሌዋውያን መሰምሪያቸውን ትተው ወደ ይሁዳና ወደ ኢየሩሳሌም መጡ።'),
  ('f739e3a1-b193-52bb-a4c8-0492f7dbf84d', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 15, 15, 'እርሱ ግን ለኮረብታው መስገጃዎች፥ ከንቱ ለሆኑ ጣዖታቱም፥ ኢዮርብዓም ለሠራቸው እንቦሶችም ካህናትን አቆመ።'),
  ('f632735e-cb7a-5708-a2f7-ab7a87af3834', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 16, 16, 'ደግሞም ለአባቶቻቸው አምላክ ለእግዚአብሔር ይሠዉ ዘንድ ከእስራኤል ነገድ ሁሉ የእስራኤልን አምላክ እግዚአብሔርን ለመፈለግ ልባቸውን የሰጡ ሁሉ እነርሱን ተከትለው ወደ ኢየሩሳሌም መጡ።'),
  ('20163c03-8af4-549f-a2c8-ae5914ca0d62', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 17, 17, 'ሦስት ዓመትም በዳዊትና በሰሎሞን መንገድ ይሄድ ነበርና ሦስት ዓመት የይሁዳን መንግሥት አበረቱ፤ የሰሎሞንንም ልጅ ሮብዓምን አጸኑ።'),
  ('c68aff12-89de-554f-a110-16ec414c075f', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 18, 18, 'ሮብዓምም የዳዊትን ልጅ የኢያሪሙትን ሴት ልጅ ሞላትን አገባ፤ እናቷም የእሴይ ልጅ የኤልያብ ልጅ አቢካኤል ነበረች።'),
  ('6cbe3e3b-c92e-54cc-ae55-05f0c402f996', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 19, 19, 'እርስዋም የዑስን፥ ሰማርያንና፥ ዘሃምን ወንዶች ልጆች ወለደችለት።'),
  ('e3de8256-e1a0-52af-a9c8-bf9c4e995aeb', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 20, 20, 'ከእርስዋም በኋላ የአቤሴሎምን ልጅ መዓካን አገባ፤ እርስዋም አብያን፥ ኢያቲን፥ ዚዛን፥ ሰሎሚትን ወለደችለት።'),
  ('dfa8c040-9ec3-56ab-a6f6-7701bdfea6ed', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 21, 21, 'ሮብዓምም ከሚስቶቹና ከቁባቶቹ ሁሉ ይልቅ የአቤሴሎምን ልጅ መዓካን ወደደ፤ ዐሥራ ስምንትም ሚስቶችና ስድሳ ቁባቶች ነበሩት፤ ሃያ ስምንት ወንዶችና ስድሳ ሴቶች ልጆችንም ወለደ።'),
  ('247ed949-d9b3-57c1-a114-75ce71a125da', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 22, 22, 'ሮብዓምም ያነግሠው ዘንድ አስቦአልና የመዓካን ልጅ አብያን በወንድሞቹ ላይ አለቃ አድርጎ ሾመው።'),
  ('c6f66062-e78c-5226-ae1b-430e3899c3bd', '30df5980-9a31-5b31-a1b5-f11685ef11de', '61d5a372-51e7-5b86-aa5c-0410dbb4d95f', 23, 23, 'ብልሃተኛም ሆነ፤ ልጆቹንም ሁሉ በይሁዳና በብንያም ሀገር ሁሉ በምሽጉ ከተሞች ሁሉ ከፋፈላቸው፤ ብዙም ምግብ ሰጣቸው፤ ብዙም ሚስቶች ፈለገላቸው።'),
  ('108973af-18bd-5dd0-aed7-d3572839c11c', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 1, 1, 'እንዲህም ሆነ፤ የሮብዓም መንግሥት በጸናች ጊዜ፥ እርሱም በበረታ ጊዜ፥ የእግዚአብሔርን ሕግ ረሳ፤ እስራኤልም ሁሉ ከእርሱ ጋር ረሱ።'),
  ('6c0046f6-47cc-5c7c-abcf-332445ec31b6', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 2, 2, 'ሮብዓም በነገሠ በአምስተኛው ዓመት የግብፅ ንጉሥ ሱስቀም ወደ ኢየሩሳሌም መጣ። እግዚአብሔርን በድለዋልና፤'),
  ('0fc2bc3f-5086-5fdd-a3f6-5aa6e58d7117', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 3, 3, 'ሺህ ሁለት መቶ ሰረገሎችንና ስድሳ ሺህ ፈረሰኞችን ይዞ መጣ፤ ከእርሱም ጋር ከግብፅ ለመጣው ሕዝብ ቍጥር አልነበረውም፤ እነርሱም የልብያ ሰዎች፥ ሞጠግሊያናውያን፥ የኢትዮጵያም ሰዎች ነበሩ።'),
  ('cca31e2c-5f03-5235-a11f-ee1eac00dfb3', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 4, 4, 'በይሁዳም የነበሩትን ምሽጎች ከተሞች ያዙ። እስከ ኢየሩሳሌምም ደረሱ።'),
  ('71813beb-9ad2-5f70-a173-8a5fd25e8ca8', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 5, 5, 'ነቢዩም ሰማያ ወደ ሮብዓምና ከሱስቀም ሸሽተው በኢየሩሳሌም ወደ ተሰበሰቡት ወደ ይሁዳ መሳፍንት መጥቶ እንዲህ አላቸው፥ “እግዚአብሔር እንዲህ ይላል፦ እናንተ ተዋችሁኝ፤ ስለዚህ እኔ ደግሞ በግብፅ ንጉሥ በሱስቀም እጅ ተውኋችሁ።”'),
  ('5c0aa2bc-90f0-54c2-a03d-6ac91e7addfb', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 6, 6, 'የእስራኤልም መሳፍንትና ንጉሡ አፈሩ፥ “እግዚአብሔር ጻድቅ ነው” አሉ።'),
  ('9a7077f9-949e-52a8-aa62-da62740b67f3', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 7, 7, 'እግዚአብሔርም እንደ ተመለሱና እንደ ተፀፀቱ ባየ ጊዜ የእግዚአብሔር ቃል፥ “ከተመለሱ አላጠፋቸውም፤ ከጥቂት ቀንም በኋላ አድናቸዋለሁ፤ ቍጣዬም በኢየሩሳሌም ላይ አይፈስስም” ሲል ወደ ሰማያ መጣ።'),
  ('fa9988ee-9ae8-5774-a5ef-d43068372bff', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 8, 8, 'ለእኔ መገዛትንና ለምድር ነገሥታት መገዛትን ያውቃሉና አገልጋዮች ይሆናሉ።'),
  ('5070dfe7-b523-5a0c-a5f6-1b1282757eb0', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 9, 9, 'የግብፅ ንጉሥ ሱስቀምም ወደ ኢየሩሳሌም መጣ፤ የእግዚአብሔርንም ቤተ መዛግብትና የንጉሡን ቤተ መዛግብት ወሰደ፤ ሁሉንም ወሰደ፤ ደግሞም ሰሎሞን የሠራቸውን የወርቁን አላባሽ አግሬ ጋሻዎችን ወሰደ።'),
  ('4dfeed6d-aff4-5d64-a94d-b7340053ec5d', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 10, 10, 'ንጉሡም ሮብዓም በእነርሱ ፋንታ የናስ አላባሽ አግሬ ጋሻዎችን ሠራ፤ ሮብዓምም የንጉሡን ቤት ደጅ በሚጠብቁ በዘበኞች አለቃ እጅ አኖራቸው።'),
  ('76d40e3a-e6f1-5553-af9b-355cd8b4b669', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 11, 11, 'ንጉሡም ወደ እግዚአብሔር ቤት በገባ ቍጥር ዘበኞች መጥተው ይሸከሙአቸው ነበር፤ መልሰውም በዘበኞች ቤት ውስጥ ያኖሩአቸው ነበር።'),
  ('375bf22a-fad3-5d68-ad71-1e574786cc44', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 12, 12, 'በተፀፀተም ጊዜ የእግዚአብሔር ቍጣ ከእርሱ ዘንድ ራቀ፤ ፈጽሞም አላጠፋውም፤ በይሁዳ መልካም ነገር ተገኝቶአልና።'),
  ('e47a03df-7a8c-5e23-a007-93ae4fac849a', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 13, 13, 'ንጉሡም ሮብዓም በኢየሩሳሌም ጸና፤ ንጉሥም ሆነ፤ ሮብዓምም በነገሠ ጊዜ የአርባ አንድ ዓመት ጐልማሳ ነበረ፤ እግዚአብሔርም ስሙን ያኖርባት ዘንድ ከእስራኤል ሀገር ሁሉ በመረጣት ከተማ በኢየሩሳሌም ዐሥራ ሰባት ዓመት ነገሠ፤ እናቱም የአሞን ሴት ንዑማ ነበረች።'),
  ('0f741da4-996e-5c8f-ac39-26d096fd6d47', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 14, 14, 'እግዚአብሔርንም ይሻ ዘንድ ልቡን አላቀናም ነበርና ክፉ ነገርን አደረገ።'),
  ('17c069b5-f4d7-5643-ab8d-3f4b2cf703bb', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 15, 15, 'የሮብዓምም የፊተኛውና የኋለኛው ነገር እነሆ፥ በነቢዩ ሰማያና በባለ ራእዩ በአዶ መጽሐፍ የተጻፈ አይደለምን? ሮብዓምም ከኢዮርብዓም ጋር በዘመኑ ሁሉ ይዋጋ ነበር።'),
  ('cb73e4c1-8461-56ed-a9e3-3c950d2afad9', '100fc456-993c-53d9-a3bd-fb10486c94fd', '02ca76ad-e95f-5abb-a348-d9988c869371', 16, 16, 'ሮብዓምም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ተቀበረ፤ ልጁም አብያ በእርሱ ፋንታ ነገሠ።'),
  ('a63350d1-c2b5-5189-a4d9-b8ca0d5513cf', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 1, 1, 'ንጉሡም ኢዮርብዓም በነገሠ በዐሥራ ስምንተኛው ዓመት አብያ በይሁዳ ላይ ንጉሥ ሆነ።'),
  ('862fd929-b3ec-5c94-a616-c265620d0501', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 2, 2, 'ሦስት ዓመትም በኢየሩሳሌም ነገሠ፤ የእናቱም ስም መዓካ ነበረ፤ የገባዖን ሰው የኡርኤል ልጅ ነበረች። በአብያና በኢዮርብዓም መካከልም ሰልፍ ነበረ።'),
  ('7c5fd80e-62b4-5201-a6b2-b720ec4b5aef', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 3, 3, 'አብያም የተመረጡትን አራት መቶ ሺህ ኀያላን ሰልፈኞች ይዞ ወደ ሰልፍ ወጣ፤ ኢዮርብዓምም የተመረጡትን ስምንት መቶ ሺህ ጽኑዓን ኀያላን ሰዎች ይዞ በእርሱ ላይ ተሰለፈ።'),
  ('13ecc176-8398-52af-ab6d-5495aae7a2d4', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 4, 4, 'አብያም በኤፍሬም ተራራ ባለው በሳምሮን ተራራ ላይ ቆሞ እንዲህ አለ፥ “ኢዮርብዓምና እስራኤል ሁሉ ሆይ፥ ስሙኝ፤'),
  ('bcc5ffde-79e7-5998-a15e-7435e6d86d0a', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 5, 5, 'የእስራኤል አምላክ እግዚአብሔር በእስራኤል ላይ መንግሥትን ለዳዊትና ለልጆቹ በጨው ቃል ኪዳን ለዘለዓለም እንደ ሰጠ በውኑ አታውቁምን?'),
  ('bd3bfc40-0855-5ed2-ad63-69487e302a66', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 6, 6, 'የዳዊት ልጅ የሰሎሞን አገልጋይ የናባጥ ልጅ ኢዮርብዓም ግን ተነሥቶ በጌታው ላይ ዐመፀ።'),
  ('a3422a2f-ba4e-5756-a898-8ce8aff52931', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 7, 7, 'ክፉዎች ሰዎችና የሕግ ተላላፊዎች ልጆችም ወደ እርሱ ተሰበሰቡ፤ ሮብዓም ሕፃን በነበረና በልቡ ድፍረት ባልነበረው ጊዜ፥ ሊቋቋመውም ባልቻለበት ጊዜ፥ በሰሎሞን ልጅ በሮብዓም ላይ በረታበት።'),
  ('6b0dacfb-29f2-5a58-a97e-b8c09d2300b7', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 8, 8, 'አሁንም በዳዊት ልጆች እጅ የሚሆነውን የእግዚአብሔርን መንግሥት ልትቋቋሙ እንዲህ ትላላችሁ። እናንተም እጅግ ታላቅ ሕዝብ ናችሁ፥ ኢዮርብዓምም አማልክት አድርጎ የሠራላችሁ የወርቅ እንቦሶች ከእናንተ ጋር ናቸው።'),
  ('59a0791b-9590-51f4-ae60-feaea2f722c2', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 9, 9, 'የአሮንን ልጆች የእግዚአብሔርን ካህናትና ሌዋውያን አላሳደዳችሁምን? ከምድርም አሕዛብ ሁሉ ለራሳችሁ ካህናትን አላደረጋችሁምን? አንድ ወይፈንና ሰባት አውራ በጎችን ይዞ ራሱን ይቀድስ ዘንድ የሚመጣ ሁሉ አማልክት ላልሆኑት ለእነዚያ ካህን ይሆናል።'),
  ('0d5ad302-d8af-5201-a338-2d3fdc6ecf51', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 10, 10, 'እኛ ግን አምላካችን እግዚአብሔርን አልተውነውም፤ የእግዚአብሔርም አገልጋዮች የአሮን ልጆች ካህናቱና ሌዋውያኑ በየሰሞናቸው ያገለግሉታል።'),
  ('e40249a5-1cd1-5d07-abc7-1962d0e771ce', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 11, 11, 'በየጥዋቱና በየማታውም ለእግዚአብሔር የሚቃጠለውን መሥዋዕትና ጣፋጩን ዕጣን ያሳርጋሉ፤ የገጹንም ኅብስት በንጹሕ ገበታ ላይ፥ የወርቁን መቅረዝና ቀንዲሎቹንም ማታ ማታ እንዲያበሩ ያዘጋጃሉ፤ እኛም የአምላካችንን የእግዚአብሔርን ትእዛዝ እንጠብቃለን፤ እናንተ ግን ትታችሁታል።'),
  ('fc64422c-0bb6-565b-ad08-eb9acd840a88', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 12, 12, 'እነሆም፥ እግዚአብሔር በእኛ ላይ አለቃ ነው፤ መለከቱንም የሚነፉ ካህናቱ ከእኛ ጋር ናቸው፤ በእናንተም ላይ ይጮኻሉ። የእስራኤል ልጆች ሆይ፥ አይበጃችሁምና ከአባቶቻችሁ አምላክ ከእግዚአብሔር ጋር አቷጉ።”'),
  ('9ae44781-fef1-5442-ae47-8b0e7f9a8905', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 13, 13, 'ኢዮርብዓም ግን በስተኋላቸው ይመጣባቸው ዘንድ ድብቅ ጦር አዞረባቸው፤ እነርሱ በይሁዳ ሰፈር ፊት ሳሉ ድብቅ ጦሩ በስተኋላቸው ከበባቸው።'),
  ('3b421710-a8b3-52f3-a547-9f9aea37276d', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 14, 14, 'የይሁዳም ሰዎች ወደ ኋላቸው በተመለከቱ ጊዜ፥ እነሆ፥ ሰልፉ በፊታቸውና በኋላቸው ነበረ፤ ወደ እግዚአብሔርም ጮኹ፤ ካህናቱም መለከቱን ነፉ።'),
  ('6aafe948-10e8-5678-a00c-d2f3b0a09b74', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 15, 15, 'የይሁዳም ሰዎች ጮኹ፤ የይሁዳም ሰዎች በጮኹ ጊዜ እግዚአብሔር ኢዮርብዓምንና እስራኤልን ሁሉ በይሁዳ ንጉሥ በአብያና በሕዝቡ ፊት መታቸው።'),
  ('84f109a1-759e-5172-a548-5cbe818109b5', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 16, 16, 'የእስራኤልም ልጆች ከይሁዳ ሰዎች ፊት ሸሹ፤ እግዚአብሔርም በእጃቸው አሳልፎ ሰጣቸው።'),
  ('c8864c8a-c76e-56d0-a244-5d894f1ada31', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 17, 17, 'አብያና ሕዝቡም ታላቅ አመታት መቱአቸው፤ ከእስራኤልም አምስት መቶ ሺህ የተመረጡ ሰዎች ተገድለው ወደቁ።'),
  ('33c70307-24f9-5dd7-a046-ae136fa3b5c7', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 18, 18, 'በዚያም ጊዜ የእስራኤል ልጆች ተዋረዱ፤ የይሁዳም ልጆች በአባቶቻቸው አምላክ በእግዚአብሔር ታምነው ነበርና አሸነፉ።'),
  ('f84db6a3-6bcd-5834-a651-bf56c1acc352', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 19, 19, 'አብያም ኢዮርብዓምን ተከትሎ አሳደደው፤ ከእርሱም ከተሞቹን ቤቴልንና መንደሮችዋን፥ ይሳናንና መንደሮችዋን፥ ዔፍሮንንና መንደሮችዋን ወሰደ።'),
  ('a7d9b12f-f9b4-508f-a3db-4fff303e0837', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 20, 20, 'ኢዮርብዓምም ከዚያ በኋላ በአብያ ዘመን አልበረታም፤ እግዚአብሔርም ቀሠፈው፤ ሞተም።'),
  ('5f56f847-26ac-58e1-a5d6-96d665153243', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 21, 21, 'አብያም ጸና፤ ዐሥራ አራት ሚስቶችንም አገባ፤ ሃያ ሁለትም ወንዶች ልጆችንና ዐሥራ ስድስት ሴቶች ልጆችን ወለደ።'),
  ('582f9092-035e-5fdf-af67-faea5a8aad85', 'c6e40171-6dfb-530e-a84d-bb3c68911746', '9dadd4cc-5974-55a0-a302-4fcc3657bf27', 22, 22, 'የአብያም የቀረው ነገርና አካሄዱ የተናገራቸውም ቃሎች በነቢዩ በአዶ መጽሐፍ ተጽፈዋል።'),
  ('08dac06f-c4c2-5354-ad60-7450f911f491', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 1, 1, 'አብያም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ቀበሩት፤ ልጁም አሳ በእርሱ ፋንታ ነገሠ። በእርሱም ዘመን ምድሪቱ ዐሥር ዓመት ያህል ዐረፈች።'),
  ('450a4f2d-6d5a-5d3f-a80c-da68860d8fff', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 2, 2, 'አሳም በአምላኩ በእግዚአብሔር ፊት መልካምና ቅን ነገር አደረገ፤'),
  ('1741f195-1d40-5a98-a42b-21114f780ce6', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 3, 3, 'የእንግዶቹንም አማልክት መሠዊያ፥ የኮረብታውንም መስገጃዎች አፈረሰ፤ ሐውልቶቹንም ሰበረ፤ የማምለኪያ አፀዶቹንም ቈረጠ፤'),
  ('3a66644c-51d2-523a-a097-53525128c1c2', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 4, 4, 'የአባቶቻቸውንም አምላክ እግዚአብሔርን ይሹ ዘንድ፥ ሕጉንና ትእዛዙንም ያደርጉ ዘንድ የይሁዳን ሕዝብ አዘዘ።'),
  ('e956b3be-8559-547f-a3ce-1af9a15e9627', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 5, 5, 'ከይሁዳም ከተሞች ሁሉ የጣዖት መሠዊያዎችንና ምስሎችን አስወገደ፤ መንግሥቱም በእርሱ ሥር በሰላም ተቀመጠች።'),
  ('78aae0da-ccc3-5451-aa35-2863b633ac9e', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 6, 6, 'በይሁዳም ምሽጎች ከተሞችን ሠራ፤ እግዚአብሔርም ዕረፍት ስለ ሰጠው ምድሪቱ ጸጥ ብላ ነበር፤ በዚያም ዘመን ጦርነት አልነበረም።'),
  ('7723631f-6347-5604-aae6-b42d10c797cc', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 7, 7, 'እርሱም የይሁዳን ሰዎች፥ “እነዚህን ከተሞች እንሥራ፤ ቅጥርም፥ ግንብም፥ መዝጊያም፥ መወርወሪያም እናድርግባቸው፤ ምድሪቱንም እንገዛታለን፤ አምላካችንን እግዚአብሔርን እንደ ፈለግነው እርሱም ይፈልገናልና፤ እርሱም በዙሪያችን ዕረፍት ሰጥቶናል፤ ሁሉንም አከናወነልን” አለ።'),
  ('9cb9af40-b9f6-55d2-accb-7491c613bba4', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 8, 8, 'ለአሳም አላባሽ አግሬ ጋሻና ጦር የሚሸከሙ ሦስት መቶ ሺህ የይሁዳ ሠራዊት፥ ወንጭፍ የሚወነጭፉ፥ ቀስትም የሚገትሩ ሁለት መቶ ሰማንያ ሺህ የብንያም ሰዎች ነበሩት፤ እነዚህም ሁሉ ጽኑዓን ኀያላን ሰዎች ነበሩ።'),
  ('35db523d-1000-5b68-a222-df0b703f85be', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 9, 9, 'የኢትዮጵያም ንጉሥ ዝሪ አንድ ሚሊዮን ሰዎችና ሦስት መቶ ሰረገሎች ይዞ ወጣባቸው፤ ወደ መሪሳም መጣ።'),
  ('9bf7d874-ac64-5500-ae9d-a110715bb9aa', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 10, 10, 'የይሁዳ ንጉሥ አሳም ሊጋጠመው ወጣ፤ በመሪሳም ደቡብ አጠገብ ባለው ሸለቆ ውስጥ ተሰለፉ።'),
  ('4e9ccab9-ebfc-549a-af1c-e9807b136ae7', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 11, 11, 'አሳም፥ “አቤቱ፥ በብዙም ሆነ በጥቂቱ ማዳን አይሳንህም፤ አቤቱ፥ አምላካችን ሆይ፥ በአንተ ታምነናልና፥ በስምህም በዚህ ታላቅ ወገን ላይ መጥተናልና ርዳን፤ አቤቱ፥ አምላካችን አንተ ነህ፤ ሰውም አያሸንፍህም” ብሎ ወደ አምላኩ ወደ እግዚአብሔር ጮኸ።'),
  ('a7e674c1-571f-57e2-a301-fba42fce93ef', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 12, 12, 'እግዚአብሔርም በአሳና በይሁዳ ሕዝብ ፊት ኢትዮጵያውያንን መታ፤ ኢትዮጵያውያንም ሸሹ።'),
  ('3dedbfe3-c285-5e58-a2af-e935de98da97', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 13, 13, 'አሳም፥ ከእርሱም ጋር ያለው ሕዝብ እስከ ጌዶር ሀገር ድረስ አሳደዱአቸው፤ ኢትዮጵያውያንም ፈጽመው እስኪጠፉ ድረስ ወደቁ፤ በእግዚአብሔርና በሠራዊቱ ፊት ተሰባብረዋልና፤ እጅግም ብዙ ምርኮ ወሰዱ።'),
  ('88c7f55d-baef-5f36-a380-d2a828457e13', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 14, 14, 'ከእግዚአብሔርም ዘንድ ታላቅ ድንጋጤ ስለ ወደቀባቸው በጌዶር ዙሪያ የነበሩትን ከተሞች ሁሉ መቱ፤ በከተሞቹም ውስጥ እጅግ ብዙ ምርኮና ብዝበዛ ነበርና ከተሞቹን ሁሉ ማረኩ።'),
  ('9f0a31e2-ef06-5d8b-ae98-284de39b701d', '2b7891bf-0d24-5d7c-a310-3ff0e4a2d893', '873cec63-7295-55e2-adea-2a88a80a0a62', 15, 15, 'የከብቶቹንም በረት አፈረሱ፤ እጅግ ብዙ በጎችንና ግመሎችንም ወሰዱ፤ ወደ ኢየሩሳሌምም ተመለሱ።'),
  ('2305142a-a287-5744-ad78-4ac7a3f925ca', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 1, 1, 'የእግዚአብሔርም መንፈስ በአዳድ ልጅ በአዛርያስ ላይ መላ፤'),
  ('1315f9ac-f046-50e4-ae41-74ef898d8de7', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 2, 2, 'እርሱም ንጉሡን አሳን፥ የይሁዳንና የብንያምን ሕዝብ ሁሉ ሊገናኝ ወጣ፤ እንዲህም አለ፥ “አሳ ይሁዳና ብንያም ሁሉ ሆይ፥ ስሙኝ፤ እናንተ ከእግዚአብሔር ጋር ብትሆኑ እርሱ ከእናንተ ጋር ይሆናል፤ ብትፈልጉትም ይገኝላችኋል፤ ብትተዉት ግን ይተዋችኋል።'),
  ('8ab0e9cd-417b-52f7-a53f-0e7448cc15e2', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 3, 3, 'እስራኤልም ብዙ ዘመን እውነተኛውን አምላክ ሳያመልኩ፥ ያለ አስተማሪም ካህን፥ ያለ ሕግም ይኖራሉ።'),
  ('48edbb0a-f382-5dbd-a9ef-decc660ff642', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 4, 4, 'በመከራቸውም ጊዜ ወደ እስራኤል አምላክ ወደ እግዚአብሔር ተመልሰው ይፈልጉታል፤ እርሱም ይገኝላቸዋል።'),
  ('283275bf-448b-5311-aa59-3f4bf238489f', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 5, 5, 'በዚያም ዘመን ለሚወጣውና ለሚገባው ሰላም አይሆንለትም፤ በሀገሮችም በሚኖሩት ሁሉ ላይ ታላቅ የእግዚአብሔር ቍጣ ይሆናል።'),
  ('29c2ea66-e1bc-5ad1-a598-6dcef3d9f592', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 6, 6, 'እግዚአብሔር በመከራው ሁሉ ያስጨንቃቸዋልና ሕዝብ ከሕዝብ ጋር፥ ከተማም ከከተማ ጋር ይዋጋል። ።'),
  ('eea8fb9b-bcb1-5464-a56a-e20770943520', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 7, 7, 'እናንተ ግን ለሥራችሁ ዋጋ ይሆንላችኋልና በርቱ፤ እጆቻችሁም አይላሉ።”'),
  ('79ae69f1-dc6a-5aef-abfe-cd820007bf9b', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 8, 8, 'አሳም ይህን ቃልና የነቢዩን የአዳድን ልጅ የአዛርያስን ትንቢት በሰማ ጊዜ ጸና፤ ከይሁዳና ከብንያምም ሀገር ሁሉ በተራራማው በኤፍሬም ሀገር ከያዛቸው ከተሞች ርኵሰትን ሁሉ አስወገደ፤ በእግዚአብሔርም ቤት ፊት የነበረውን የእግዚአብሔርን መሠዊያ አደሰ።'),
  ('98cb6157-4059-52cc-a257-71ffdbdd38dc', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 9, 9, 'አምላኩም እግዚአብሔር ከእርሱ ጋር እንደ ሆነ ባዩ ጊዜ ከእስራኤል ዘንድ ብዙ ሰዎች ወደ እርሱ ተጠግተው ነበርና እርሱ ይሁዳንና ብንያምን ሁሉ፥ ከኤፍሬምና ከምናሴም፥ ከስምዖንም ፈልሰው ከእነርሱ ጋር የተቀመጡትን ሰበሰበ።'),
  ('ebb20cd3-3286-5334-a324-9472b04f188b', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 10, 10, 'አሳም በነገሠ በዐሥራ አምስተኛው ዓመት በሦስተኛው ወር በኢየሩሳሌም ተሰበሰቡ።'),
  ('3fe9253f-5560-52ce-aaf8-cc6d55013dfb', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 11, 11, 'በዚያም ቀን ካመጡት ምርኮ ሰባት መቶ በሬዎችንና ሰባት ሺህ በጎችን ለእግዚአብሔር ሠዋ።'),
  ('55fab5ce-5ce4-554b-ac12-fb5ef916daee', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 12, 12, 'በፍጹም ልባቸውና በፍጹም ነፍሳቸው የአባቶቻቸውን አምላክ እግዚአብሔርን ይሹ ዘንድ ቃል ኪዳን አደረገ፤'),
  ('45fbff61-03da-51b6-a992-3123633f3d9d', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 13, 13, 'የእስራኤልንም አምላክ እግዚአብሔርን የማይፈልግ፥ ታናሽ ወይም ታላቅ፥ ወንድ ወይም ሴት ቢሆን፥ ይገደል ዘንድ ማሉ።'),
  ('31cf38fa-bd8c-53d8-aa4a-37e366bc94a1', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 14, 14, 'ለእግዚአብሔርም በታላቅ ድምፅና በእልልታ፥ በእንቢልታና በቀንደ መለከት ማሉ።'),
  ('04bc4209-1bb2-5575-aa22-1dae1fc50beb', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 15, 15, 'በፍጹምም ልባቸው ምለዋልና፥ በፍጹምም ሕሊናቸው ፈልገውታልና፥ እርሱም ተገኝቶላቸዋልና ይሁዳ ሁሉ በመሐላው ደስ አላቸው፤ እግዚአብሔርም በዙሪያቸው ዕረፍትን ሰጣቸው።'),
  ('6b680cfc-faf8-52e0-aae1-4bbead070104', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 16, 16, 'ንጉሡም አሳ እናቱን መዓካን ለአስጣርቴስ ስለ ሰገደች ከእቴጌነቷ አወረዳት፤ አሳም ምስሉን ቈርጦ ቀጠቀጠው፤ በቄድሮንም ወንዝ አጠገብ አቃጠለው።'),
  ('37399b8e-5dba-565a-aa33-42644316b9d6', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 17, 17, 'በኮረብታ ላይ የነበሩትን መስገጃዎች ግን ከእስራኤል አላራቀም። ገና በእስራኤል ዘንድ እስከ አሁን ነበሩ፤ ይሁን እንጂ የአሳ ልብ በዘመኑ ሁሉ ፍጹም ነበረ።'),
  ('d674fa35-dac0-59a3-ae7f-59c820d32956', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 18, 18, 'አባቱም ዳዊት የቀደሰውን፥ እርሱም የቀደሰውን ወርቁንና ብሩን፥ ልዩ ልዩውንም ዕቃ ወደ እግዚአብሔር ቤትአገባ።'),
  ('2ca6d993-77fd-57fa-a0c1-fb48b0e7efae', '32f49dad-af47-5a29-a9cb-417ea51f6f8d', '6cd9390e-679c-5c78-a2db-2655df891c5f', 19, 19, 'አሳም በነገሠበት ዘመን እስከ ሠላሳ አምስተኛው ዓመት ድረስ ጦርነት አልነበረም።'),
  ('a973b035-d2ae-50cc-a045-1d2f7b50dce6', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 1, 1, 'አሳ በነገሠ በሠላሳ ስድስተኛው ዓመት የእስራኤል ንጉሥ ባኦስ በይሁዳ ላይ ዘመተ፥ ወደ ይሁዳም ንጉሥ ወደ አሳ ማንም መውጣትና መግባት እንዳይችል ራማን ሠራት።'),
  ('95527376-9c5b-5b50-a669-ec3d2d9979ed', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 2, 2, 'አሳም ከእግዚአብሔር ቤትና ከንጉሥ ቤት መዝገብ ብርና ወርቅ ወስዶ፦ በደማስቆ ወደ ተቀመጠው ወደ ሶርያ ንጉሥ ወደ ወልደ አዴር ላከ። እንዲህም አለው፦'),
  ('af237029-55cd-54f4-af56-c8bc366db704', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 3, 3, '“በአባቴና በአባትህ መካከል እንደ ነበረው ቃል ኪዳን በእኔና በአንተ መካከል አድርግ፤ የእስራኤል ንጉሥ ባኦስ ከእኔ ዘንድ እንዲርቅ መጥተህ ትወጋው ዘንድ እነሆ፥ ወርቅና ብር ልኬልሃለሁ።”'),
  ('5c8a072b-489f-58c6-afd0-05527e1ed36b', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 4, 4, 'ወልደ አዴርም ንጉሡን አሳን ሰማው፤ የሠራዊቱንም አለቆች በእስራኤል ከተሞች ላይ ሰደደ፤ እነርሱም አእዮንንና ዳንን፥ አቤልማይምንና የንፍታሌምንም አውራጃ ከተሞች ሁሉ መቱ።'),
  ('eac78621-88f3-5284-aa78-721c59e2a2dd', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 5, 5, 'ባኦስም በሰማ ጊዜ ራማን መሥራት ተወ፤ ሥራውንም አቋረጠ።'),
  ('e2f7a002-8357-540d-a886-0b3ffa823fb9', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 6, 6, 'የይሁዳ ንጉሥ አሳም የይሁዳን ሰዎች ሁሉ ሰበሰበ፤ ባኦስ ይሠራበት የነበረውን የራማን ድንጋይና እንጨት ወሰደ፤ እርሱም ገባዖንንና መሴፋን ሠራበት።'),
  ('2d5acf11-b49f-5c48-a859-2b2088d3231d', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 7, 7, 'በዚያን ጊዜም ነቢዩ አናኒ ወደ ይሁዳ ንጉሥ ወደ አሳ መጥቶ እንዲህ አለው፥ “በሶርያ ንጉሥ ታምነሃልና፥ በአምላክህም በእግዚአብሔር አልታመንህምና ስለዚህ የሶርያ ንጉሥ ጭፍራ ከእጆችህ አምልጠዋል።'),
  ('2d29e787-0e57-50fb-a9d7-82ba7d9f8ad3', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 8, 8, 'ኢትዮጵያውያንና የልብያ ሰዎች እጅግ ብዙ ሰረገሎችና ፈረሰኞች የነበሩአቸው እጅግ ታላቅ ጭፍራ አልነበሩምን? በእግዚአብሔር ስለ ታመንህ በእጅህ አሳልፎ ሰጣቸው።'),
  ('ea942715-96ba-584e-a22f-bff78c15a7cf', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 9, 9, 'እግዚአብሔር ልቡ በእርሱ ዘንድ ፍጹም የሆነውን ያጸና ዘንድ ዐይኖቹ በምድር ሁሉ ይመለከታሉና። አሁንም ባለማወቅህ በድለሃል፤ ስለዚህም ከዛሬ ጀምሮ ጦርነት ይሆንብሃል።”'),
  ('13154118-09ca-5be3-a767-180a73ae74a5', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 10, 10, 'አሳም በነቢዩ በአናኒ ላይ ተቈጣ፤ ስለዚህም ነገር ተቈጥቶአልና በግዞት አኖረው፤ በዚያን ጊዜም አሳ ከሕዝቡ አያሌ ሰዎችን አስጨነቀ።'),
  ('3ff292b9-a0d7-5c1f-a336-6949c5d95833', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 11, 11, 'የአሳም የፊተኛውና የኋለኛው ነገር፥ እነሆ፥ በይሁዳና በእስራኤል ነገሥታት የታሪክ መጽሐፍ ተጽፎአል።'),
  ('52b9b03b-b0db-551d-a1fe-25e3aea161f6', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 12, 12, 'አሳም በነገሠ በሠላሳ ዘጠነኛው ዓመት እግሩን ታመመ፤ ደዌውም ጸናበት፤ ነገር ግን በሕማሙ ጊዜ ባለ መድኀኒቶችን እንጂ እግዚአብሔርን አልፈለገም።'),
  ('d53a1f56-07af-53d3-a391-513dee28b413', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 13, 13, 'አሳም ከአባቶቹ ጋር አንቀላፋ፤ በነገሠም በአርባ አንደኛው ዓመት ሞተ።'),
  ('c4753760-30d8-598f-a48e-e2d1098b7cf3', 'f565d76e-2f67-503b-a15d-4789cb2fa9cf', 'b17350b0-ba77-5a06-ad6a-61c1c9551687', 14, 14, 'ለእርሱም ለራሱ በሠራው መቃብር በዳዊት ከተማ ቀበሩት፤ በቀማሚ ብልሃት የተሰናዳ ልዩ ልዩ መልካም ሽቱ በተሞላ አልጋ ላይም አኖሩት፤ እጅግም ታላቅ የሆነ የቀብር ሥርዐት አደረጉለት።'),
  ('60a90242-e61b-5d24-a110-cf8e583efd61', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 1, 1, 'ከአሳም በኋላ ልጁ ኢዮሳፍጥ ነገሠ፤ ኢዮሳፍጥም በእስራኤል ላይ ጠነከረ።'),
  ('a843e2a0-c2b7-56b8-ada6-cc3c8350885b', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 2, 2, 'በተመሸጉትም በይሁዳ ከተሞች ሁሉ ሠራዊቱን አኖረ፤ በይሁዳም ሀገር፥ አባቱም አሳ በወሰዳቸው በኤፍሬም ከተሞች መሳፍንቱን አስቀመጠ።'),
  ('48b3c739-7992-5440-aac4-af07d7aedc96', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 3, 3, 'እግዚአብሔርም ከኢዮሳፍጥ ጋር ነበረ፤ በፊተኛዪቱም በአባቱ በዳዊት መንገድ ሄዶአልና፥ ጣዖትንም አልፈለገምና፤'),
  ('8e9d6fe3-0e43-54a7-aee8-f27c33eed12b', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 4, 4, 'ነገር ግን የአባቱን አምላክ ፈለገ፤ በአባቱም ትእዛዝ ሄደ፤ በእስራኤልም ሥራ አይደለም።'),
  ('70b9b500-60b1-55c2-a408-b471b8a767e9', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 5, 5, 'እግዚአብሔርም መንግሥቱን በእጁ አጸና፤ ይሁዳም ሁሉ እጅ መንሻ ለኢዮሳፍጥ አመጣ፤ እጅግም ብዙ ብልጥግናና ክብር ሆነለት።'),
  ('4f7890e0-9d76-53a8-afe4-3c7eb8ef187c', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 6, 6, 'ልቡም በእግዚአብሔር መንገድ ከፍ ከፍ አለ፤ የኮረብታውን መስገጃዎችና የማምለኪያ አፀዱንም ከይሁዳ አስወገደ።'),
  ('fdfcd2a2-4ff6-59ef-aa34-1d15b24979a5', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 7, 7, 'በነገሠም በሦስተኛው ዓመት በይሁዳ ከተሞች ያስተምሩ ዘንድ መሳፍንቱንና ኀያላኑን ሰዎች አብድያስን፥ ዘካርያስን፥ ናትናኤልን፥ ሚኪያስን ላከ።'),
  ('f6b77044-1335-5f53-a782-7743c8de7f55', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 8, 8, 'ከእነርሱም ጋር ሌዋውያንን ሸማያን፥ ነታንያን፥ ዛባድያን፥ አሣሄልን፥ ሰሚራሞትን፥ ዮናታንን፥ አዶንያስን፥ ጦብያን፥ ጦባዶንያስን ከእነርሱም ጋር ካህናቱን ኤሊሳማንና ኢዮራምን ላከ።'),
  ('780aa58d-c2a4-5c08-a3b6-61fc75b31703', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 9, 9, 'እነርሱም የእግዚአብሔርን የሕጉን መጽሐፍ ይዘው በይሁዳ ያስተምሩ ነበር፤ ወደ ይሁዳም ከተሞች ሁሉ ተመላልሰው ሕዝቡን አስተማሩ።'),
  ('b6001fef-0db0-55f8-ab3b-1a0cc2771e05', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 10, 10, 'በይሁዳም ዙሪያ በነበሩ የምድር መንግሥታት ሁሉ ላይ ከእግዚአብሔር ዘንድ ድንጋጤ ሆነ፤ ከኢዮሳፍጥም ጋር አልተዋጉም።'),
  ('8727d897-b824-5f95-afe6-050f151db1bd', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 11, 11, 'ከፍልስጥኤማውያንም ለኢዮሳፍጥ እጅ መንሻና የብር ግብር ያመጡ ነበር፤ ዐረባውያንም ደግሞ ከመንጎቻቸው ሰባት ሺህ ሰባት መቶ አውራ በጎችንና ሰባት ሺህ ሰባት መቶ አውራ ፍየሎችን ያመጡለት ነበር።'),
  ('bfd7a2b1-06c3-59f9-a176-6d4e39890a8f', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 12, 12, 'ኢዮሳፍጥም እየበረታና እጅግም እየከበረ ሄደ፤ በይሁዳም ግንቦችንና የተመሸጉ ከተሞችን ሠራ።'),
  ('a72bd28a-66c4-54a5-a193-efad871fdd4b', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 13, 13, 'በይሁዳም ከተሞች ብዙ ሥራ ሠራ፤ በኢየሩሳሌምም ጽኑዓን ኀያላን ሰልፈኞች ነበሩት።'),
  ('a0ce62dc-eacd-531b-a416-09c1349031b6', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 14, 14, 'ቍጥራቸውም እንደ አባቶቻቸው ቤት ይህ ነበረ፤ ከይሁዳ ሻለቆች አለቃው ዓድናስ፥ ከእርሱም ጋር ሦስት መቶ ሺህ ጽኑዓን ኀያላን ሰዎች ነበሩ፤'),
  ('3bb3c078-12a4-5a5b-a1a1-9432b3a4ff5e', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 15, 15, 'ከእርሱም በኋላ አለቃው ኢዮአናን፥ ከእርሱም ጋር ሁለት መቶ ሰማንያ ሺህ ሰዎች ነበሩ፤'),
  ('156249c8-d642-532f-affc-c51a5185c24c', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 16, 16, 'ከእርሱም በኋላ እግዚአብሔርን የሚያገለግል የዝክሪ ልጅ ማስያስ፥ ከእርሱም ጋር ሁለት መቶ ሺህ ጽኑዓን ኀያላን ሰዎች ነበሩ።'),
  ('487546d0-acc7-5b7a-a454-6425c145006d', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 17, 17, 'ከብንያምም ጽኑዕ ኀያል የነበረው ኤሊያዳ፥ ከእርሱም ጋር ቀስት የሚገትሩ፥ ወንጭፍ የሚወነጭፉ ሁለት መቶ ሺህ ሰዎች ነበሩ፤'),
  ('4e8d8669-2f22-5a59-ab99-2236a32e5d80', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 18, 18, 'ከእርሱም በኋላ ዮዛባድ፥ ከእርሱም ጋር ለሰልፍ የተዘጋጁ መቶ ሰማንያ ሺህ ሰዎች ነበሩ።'),
  ('ccda8d03-5237-58b0-affc-8f80b69bb3d4', '92b34cd8-1781-5eb7-a56b-0215f4c17233', '85a0ff7c-daff-58ec-aa7c-82f73d25c7f2', 19, 19, 'ንጉሡ በተመሸጉ በይሁዳ ከተሞች ሁሉ ካኖራቸውም ሌላ እነዚህ ንጉሡን ያገለግሉ ነበር።'),
  ('7b5a24e4-96ad-5cac-a8b3-41bda548b0d4', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 1, 1, 'ለኢዮሣፍጥም ብዙ ብልጥግናና ክብር ነበረው፤ ከአክዓብም ወገን ሚስት አገባ።'),
  ('a2d8323b-fc9f-535a-a52b-96b8a1431c25', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 2, 2, 'ከጥቂት ዓመታት በኋላም ወደ አክዓብ ወደ ሰማርያ ወረደ። አክዓብም ለእርሱና ከእርሱ ጋር ለነበሩት ሕዝብ ብዙ በጎችንና በሬዎችን አረደ፤ ወደደውም፤ ከእርሱም ጋር ወደ ሬማት ዘገለዓድ ይሄድ ዘንድ አባበለው።'),
  ('0bbb5744-c445-59a8-ae7c-902c8b986cde', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 3, 3, 'የእስራኤልም ንጉሥ አክዓብ የይሁዳን ንጉሥ ኢዮሣፍጥን፥ “ከእኔ ጋር ወደ ሬማት ዘገለዓድ ትሄዳለህን?” አለው። እርሱም፥ “እኔ እንደ አንተ ነኝ፤ ሕዝቤም ለሰልፍ እንደ ሕዝብህ ናቸው፤” ብሎ መለሰለት።'),
  ('053d6e24-18b0-5ef8-a1b6-7b2a302c9f0b', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 4, 4, 'ኢዮሣፍጥም የእስራኤልን ንጉሥ፥ “ዛሬ እግዚአብሔርን ጠይቅ” አለው።'),
  ('c6c51fd7-c0d6-5c08-a332-845c3de2f105', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 5, 5, 'የእስራኤልም ንጉሥ ከነቢያቱ አራት መቶ ሰዎችን ሰብስቦ፥ “ወደ ሬማት ዘገለዓድ ለሰልፍ ልሂድን? ወይስ ልቅር?” አላቸው። እነርሱም፥ “እግዚአብሔር በንጉሥ እጅ አሳልፎ ይሰጣታልና ውጣ” አሉት።'),
  ('f3bf65b0-cf3e-59c3-a43d-d90afe839238', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 6, 6, 'ኢዮሣፍጥ ግን፥ “እንጠይቀው ዘንድ የእግዚአብሔር ነቢይ የሆነ ሌላ ሰው በዚህ አይገኝምን?” አለ።'),
  ('4fa2535c-e1dd-51bf-aec7-09efdf32a041', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 7, 7, 'የእስራኤልም ንጉሥ ኢዮሣፍጥን፥ “እግዚአብሔርን የምንጠይቅበት አንድ ሰው አለ፤ ነገር ግን ሁልጊዜ ክፉ እንጂ ከቶ መልካም ትንቢት አይናገርልኝምና እጠላዋለሁ፤ እርሱም የይምላ ልጅ ሚክያስ ነው” አለው። ኢዮሣፍጥም፥ “ንጉሡ እንዲህ አይበል” አለው።'),
  ('06da795d-e745-5ad9-a369-0ccc5414a3d4', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 8, 8, 'የእስራኤልም ንጉሥ አንድ ጃንደረባ ጠርቶ፥ “የይምላን ልጅ ሚክያስን ፈጥነህ አምጣው” አለው።'),
  ('22f9ac27-816e-5ade-ae72-d326dd3aa6d5', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 9, 9, 'የእስራኤል ንጉሥና የይሁዳ ንጉሥ ኢዮሣፍጥ ልብሰ መንግሥት ለብሰው በሰማርያ በር መግቢያ አጠገብ በአደባባይ በዙፋኖቻቸው ላይ ተቀምጠው ነበር፤ ነቢያትም ሁሉ በፊታቸው ትንቢት ይናገሩ ነበር።'),
  ('e4d1129b-78d8-5ca3-a873-3aee47fa4867', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 10, 10, 'የካህናን ልጅ ሴዴቅያስም የብረት ቀንዶች ሠርቶ፦ እግዚአብሔር እንዲህ ይላል፥ “ሶርያውያንን እስክታጠፋቸው ድረስ በእነዚህ ትወጋለህ” አለ።'),
  ('318150ed-7a88-5b26-ad99-3f27618107d1', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 11, 11, 'ነቢያትም ሁሉ፥ “እግዚአብሔር በንጉሡ እጅ አሳልፎ ይሰጣታልና ወደ ሬማት ዘገለዓድ ውጣና ተከናወን” እያሉ እንዲሁ ትንቢት ይናገሩ ነበር።'),
  ('03b3deb8-7b07-5bb2-abe7-e1bfe5b6b782', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 12, 12, 'ሚክያስንም ሊጠራ የሄደ መልእክተኛ፥ “እነሆ፥ ነቢያት በአንድ አፍ ሆነው ለንጉሡ መልካም ይናገራሉ፤ ቃልህም እንደ ቃላቸው እንዲሆን መልካም እንድትናገር እለምንሃለሁ” አለው።'),
  ('bacb49e2-5fea-51dd-afc4-f5e6023f3556', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 13, 13, 'ሚክያስም፥ “ሕያው እግዚአብሔርን! አምላኬ የሚለውን እርሱን እናገራለሁ” አለ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('7e90113c-16d3-5ef5-a369-dd029a2c1622', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 14, 14, 'ወደ ንጉሡም በመጣ ጊዜ ንጉሡ፥ “ሚክያስ ሆይ፥ ወደ ሬማት ዘገለዓድ ለሰልፍ ልሂድን? ወይስ ልቅር?” አለው።'),
  ('e47043af-33a5-5959-a55d-eaad187dcb87', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 15, 15, 'ነቢዩ ሚክያስም፥ “ውጣ፤ ተከናወን፤ በእጅህም አልፈው ይሰጣሉ” አለ። ንጉሡም፥ “በእግዚአብሔር ስም ከእውነት በቀር እንዳትነግረኝ ስንት ጊዜ አምልሃለሁ?” አለው።'),
  ('d40042bf-4e70-5bd7-ad73-9b2115044c46', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 16, 16, 'እርሱም፥ “እስራኤል ሁሉ ጠባቂ እንደሌላቸው በጎች በተራሮች ላይ ተበትነው አየሁ፤ እግዚአብሔርም፦ ለእነዚህ ጌታ የላቸውም፥ እያንዳንዱም በሰላም ወደ ቤቱ ይመለስ አለ” ብሎ ተናገረ።'),
  ('a2d770e8-b6a6-5172-aec1-c0f3b4ff9bd3', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 17, 17, 'የእስራኤልም ንጉሥ ኢዮሣፍጥን፥ “ክፉ እንጂ መልካም ትንቢት አይናገርልኝም አላልሁህምን?” አለው።'),
  ('ca9d758e-2e62-5304-adec-d7159db5fb0d', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 18, 18, 'ሚክያስም አለ፥ “እንዲህ አይደለም፤ እንግዲህ የእግዚአብሔርን ቃል ስሙ፤ እግዚአብሔር በዙፋኑ ተቀምጦ፥ የሰማይ ሠራዊት ሁሉ በቀኙና በግራው፤ ቆመው አየሁ።”'),
  ('2602c3cf-c76f-5574-a416-64a69da9202c', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 19, 19, 'እግዚአብሔርም፥ “ወጥቶ በሬማት ዘገለዓድ ይወድቅ ዘንድ የእስራኤልን ንጉሥ አክዓብን የሚያታልል ማን ነው?” አለ። አንዱም እንደዚህ፥ ሌላውም እንደዚያ ያለ ነገር ተናገረ።'),
  ('ede550e0-a458-5d4a-a35b-dc06cc93bf8d', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 20, 20, 'መንፈስም መጣ፤ በእግዚአብሔርም ፊት ቆሞ፥ “እኔ አታልለዋለሁ” አለ። እግዚአብሔርም፥ “በምን ታታልለዋለህ?” አለው።'),
  ('0918a607-b386-5a5d-ac18-1214cbdc8e5c', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 21, 21, 'እርሱም፥ “ወጥቼ በነቢያት ሁሉ አፍ የሐሰት መንፈስ እሆናለሁ” አለ። እግዚአብሔርም፥ “ታታልለዋለህ፤ ይቀናሃል፥ ውጣ፤ እንዲህም አድርግ” አለው።'),
  ('3d559bdd-8e62-5d31-a1b5-20ddd76c80c4', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 22, 22, '“አሁንም እነሆ፥ እግዚአብሔር በእነዚህ በነቢያትህ አፍ የሐሰት መንፈስን አድርጎአል፤ እግዚአብሔርም በአንተ ላይ ክፉ ተናግሮብሃል።”'),
  ('91e71e29-fa9f-5db2-a72b-d79e694c3080', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 23, 23, 'የካህናንም ልጅ ሴዴቅያስ ቀረበ፤ ሚክያስንም በጥፊ መታውና፥ “የእግዚአብሔር መንፈስ ከአንተ ጋር ይናገር ዘንድ በምን መንገድ ከእኔ አለፈ?” አለው።'),
  ('884134f2-e38d-5b2c-a9e2-c8823285a708', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 24, 24, 'ሚክያስም፥ “እነሆ፥ በዚያ ቀን ልትሸሸግ ከእልፍኝ ወደ እልፍኝ ስትሄድ ታያለህ” አለ።'),
  ('fe19b9fb-4cb0-5eac-a032-c1506d8d28bb', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 25, 25, 'የእስራኤልም ንጉሥ እንዲህ አለ፥ “ሚክያስን ውሰዱ፤ ወደ ከተማዪቱም አለቃ ወደ ኤሜር፥ ወደ ንጉሡም ልጆች አለቃ ወደ ኢዮአስ መልሱት'),
  ('4f8d8597-6dfc-53f3-a302-5dfa60d9f510', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 26, 26, 'እንዲህም በሉአቸው፦ ንጉሡ እንዲህ ይላል፦ በደኅና እስክመለስ ድረስ ይህን ሰው በግዞት አኑሩት፤ የመከራም እንጀራ መግቡት፤ የመከራም ውኃ አጠጡት።”'),
  ('327d1c3e-31cf-502e-a1b2-30ce4c2a7c41', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 27, 27, 'ሚክያስም፥ “በደኅና ብትመለስ እግዚአብሔር በእኔ አልተናገረም” አለ። “ደግሞም እናንተ ሕዝቡ ሁሉ ስሙኝ” አለ።'),
  ('eb19325d-7327-5ebf-a0c7-0e3d08c2150f', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 28, 28, 'የእስራኤል ንጉሥና የይሁዳ ንጉሥ ኢዮሣፍጥ ወደ ሬማት ዘገለዓድ ወጡ።'),
  ('a6ffd5e6-8300-5b36-a52c-c4ebc9c78b58', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 29, 29, 'የእስራኤል ንጉሥም ኢዮሣፍጥን፥ “ልብሴን ለውጬ ወደ ጦርነት እገባለሁ፤ አንተ ግን የእኔን ልብስ ልበስ” አለው። የእስራኤልም ንጉሥ ልብሱን ለወጠ፤ ወደ ሰልፍም ገባ።'),
  ('cc760c88-3965-53c4-ad8c-e36c396fd3c8', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 30, 30, 'የሶርያም ንጉሥ ከእርሱ ጋር የነበሩትን የሰረገሎቹን አለቆች፦ ከእስራኤልም ንጉሥ በቀር ትንሽ ቢሆን ወይም ትልቅ ከማናቸውም ጋር አትጋጠሙ ብሎ አዝዞ ነበር።'),
  ('8b9bc0a3-cc9e-5609-a186-bb064d4ca86f', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 31, 31, 'የሰረገሎችም አለቆች ኢዮሣፍጥን ባዩ ጊዜ፥ “የእስራኤል ንጉሥ ነው” አሉ፤ ሊጋጠሙትም ከበቡት፤ ኢዮሣፍጥ ግን ጮኸ፤ እግዚአብሔርም አዳነው፤ አምላኩም ከእርሱ መለሳቸው።'),
  ('92b0bb74-b924-5197-a19a-5bf317912615', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 32, 32, 'የሰረገሎቹም አለቆች የእስራኤል ንጉሥ እንዳልሆነ ባዩ ጊዜ ከእርሱ ተመለሱ።'),
  ('15a67433-9e40-533e-a5f1-8db77ce58015', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 33, 33, 'አንድ ሰውም ቀስቱን በድንገት ገትሮ የእስራኤልን ንጉሥ በጥሩሩ መጋጠሚያ በኩል ሳንባውን ወጋው። ሰረገለኛውንም፥ “ተወግቻለሁና እጅህን ግታ፤ ከጦርነት ውስጥ አውጣኝ” አለው።'),
  ('31451b56-7e9f-5275-aefd-9e03f309ea01', 'fa51beb2-5cf3-5488-a43f-be1b165dfde8', '0d20665f-cbe7-577b-ab58-a0566a26be88', 34, 34, 'በዚያም ቀን ጦርነት በረታ፤ የእስራኤልም ንጉሥ በሶርያውያን ፊት እስከ ማታ ድረስ በሰረገላው ላይ ራሱን ይደግፍ ነበር፤ ፀሐይም በገባ ጊዜ ሞተ።'),
  ('b3a38e72-b8c5-5310-ad3e-23779298701b', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 1, 1, 'የይሁዳም ንጉሥ ኢዮሣፍጥ ወደ ቤቱ ወደ ኢየሩሳሌም በሰላም ተመለሰ።'),
  ('3079275b-0b99-56b7-a13e-2cc49ecafa43', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 2, 2, 'ነቢዩ የአናኒ ልጅ ኢዩ ሊገናኘው ወጣ፤ ንጉሡንም ኢዮሣፍጥን፥ “ኀጢአተኛውን ታግዛለህን? ወይስ እግዚአብሔር የሚጠላውን ትወድዳለህን? ስለዚህም ነገር ከእግዚአብሔር ዘንድ ቍጣ መጥቶብሃል።'),
  ('96d09bcc-07ea-556e-a23f-6fbb2afb6f97', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 3, 3, 'ነገር ግን የማምለኪያ ዐፀዶችን ከምድረ ይሁዳ አስወግደሃልና፥ እግዚአብሔርንም ትፈልግ ዘንድ ልብህን አዘጋጅተሃልና መልካም ነገር ተገኝቶብሃል” አለው።'),
  ('c90cc428-3fb7-5176-a705-795390d45187', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 4, 4, 'ኢዮሣፍጥም በኢየሩሳሌም ተቀመጠ፤ ደግሞም ከቤርሳቤህ ጀምሮ እስከ ተራራማው እስከ ኤፍሬም ሀገር ድረስ ወደ ሕዝቡ ወጥቶ ወደ አባቶቻቸው አምላክ ወደ እግዚአብሔር መለሳቸው።'),
  ('dbc6ceab-e1ba-5901-a819-734f12dd19de', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 5, 5, 'በተመሸጉት በይሁዳ ከተሞች ሁሉ በእያንዳንዱ ከተማ ውስጥ ፈራጆችን ሾመ።'),
  ('94136d40-a8ad-57cb-a251-2152d9be956d', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 6, 6, 'ፈራጆቹንም፥ “ለእግዚአብሔር እንጂ ለሰው አትፈርዱምና፥ የፍርድም ነገር ከእናንተ ጋር ነውና የምታደርጉትን ተመልከቱ።'),
  ('5f96cb35-45e8-5b4b-a1b5-3e977139a7f4', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 7, 7, 'አሁንም እግዚአብሔርን መፍራት በእናንተ ላይ ይሁን፤ በአምላካችንም በእግዚአብሔር ዘንድ በደልና ለሰው ፊት ማድላት፥ መማለጃም መውሰድ የለምና ሁሉን ተጠንቅቃችሁ አድርጉ” አላቸው።'),
  ('04e07d35-4a7f-5abc-afa3-1ab06cb6541a', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 8, 8, 'ኢዮሣፍጥም ከሌዋውያንና ከካህናት፥ ከእስራኤልም የአባቶች ቤቶች አለቆች በእግዚአብሔር ፍርድ በኢየሩሳሌም በሚኖሩ ላይ ፍርድን እንዲፈርዱ በኢየሩሳሌም ሾመ።'),
  ('2c7a7b87-2189-58c7-a956-8c347391b85c', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 9, 9, 'እንዲህም ብሎ አዘዛቸው፥ “እንዲሁ እግዚአብሔርን በመፍራት፥ በቅንነትም፥ በፍጹምም ልብ አድርጉ።”'),
  ('6edc1714-eb8a-55e9-a912-0d78f55826ef', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 10, 10, 'በከተሞቻቸውም ከተቀመጡት ከወንድሞቻችሁ በደምና በደም መካከል፥ በሕግና በትእዛዝ፥ በሥርዐትና በፍርድም መካከል ያለ ማናቸውም ሰው ለፍርድ ወደ እናንተ ቢመጣ እግዚአብሔርን እንዳይበድሉ፥ ቍጣም በእናንተና በወንድሞቻችሁ ላይ እንዳይመጣ አስጠንቅቁአቸው፤ እንዲህም ብታደርጉ በደለኞች አትሆኑም።'),
  ('1b036b7f-7e20-5824-a7e1-68e2f896d361', '0619e1aa-9531-511e-abb1-cb3d2c6a0062', '2326b719-4a1a-59cd-aae0-1763bc71cd3d', 11, 11, 'እነሆም፥ ለእግዚአብሔር በሚሆነው ነገር ሁሉ የካህናቱ አለቃ አማርያ፥ በንጉሡም ነገር ሁሉ የይሁዳ ቤት አለቃ የይስማኤል ልጅ ዝባድያስ በላያችሁ ተሾመዋል፤ ጸሐፍቱና ሌዋውያኑ ደግሞ በፊታችሁ አሉ፤ በርትታችሁም አድርጉ፤ እግዚአብሔር መልካም ከሚያደርግ ጋር ይሁን።'),
  ('b63b3728-5180-548b-a3b7-632de0378f53', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 1, 1, 'እንዲህም ሆነ፤ ከዚህ በኋላ የሞዓብና የአሞን ልጆች ከእነርሱም ጋር ምዑናውያን ኢዮሣፍጥን ሊወጉ መጡ።'),
  ('953fd6b1-7c03-58f9-ac59-fc3ffda60575', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 2, 2, 'ሰዎችም መጥተው፥ “ከባሕሩ ማዶ ከሶርያ ታላቅ ሠራዊት መጥቶብሃል፤ እነሆም፥ ዓይንጋዲ በተባለች በሐሴሶን ታማር ናቸው” ብለው ለኢዮሣፍጥ ነገሩት።'),
  ('767f5386-e032-5497-a430-e11321c92488', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 3, 3, 'ኢዮሣፍጥም ፈራ፤ እግዚአብሔርንም ሊፈልግ ፊቱን አቀና፤ በይሁዳም ሁሉ ጾም አወጀ።'),
  ('7d9ca905-6270-55e0-adf3-6d7de5d6ddf4', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 4, 4, 'ይሁዳም እግዚአብሔርን ይፈልግ ዘንድ ተሰበሰበ፤ ከይሁዳ ከተሞችም ሁሉ እግዚአብሔርን ይፈልጉ ዘንድ መጡ።'),
  ('02ab04f8-d7e1-5b09-ae7a-ec03c8183e5b', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 5, 5, 'ኢዮሣፍጥም በይሁዳና በኢየሩሳሌም ጉባኤ መካከል በእግዚአብሔር ቤት ውስጥ በአዲሱ አደባባይ ፊት ቆመ፤'),
  ('94b32b10-094d-57bb-a0a9-5b45b501856c', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 6, 6, 'እንዲህም አለ፥ “አቤቱ፥ የአባቶቻችን አምላክ ሆይ፥ በሰማይ ያለህ አምላክ አንተ አይደለህምን? የአሕዛብንስ መንግሥታት ሁሉ የምትገዛ አንተ አይደለህምን? ኀይልና ችሎታ በእጅህ ነው፤ ሊቋቋምህም የሚችል የለም።'),
  ('1c281de4-ac58-5774-a07b-0d2c4b5b9ea9', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 7, 7, 'አምላካችን ሆይ፥ በዚህ ምድር የነበሩትን አሕዛብ ከሕዝብህ ከእስራኤል ፊት ያሳደድህ፥ ለወዳጅህም ለአብርሃም ዘር ለዘለዓለም የሰጠሃት አንተ አይደለህምን?'),
  ('eab16854-2f0d-5df5-ae7d-2cf9792a1f38', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 8, 8, 'እነርሱ ተቀመጡባት፤ ለስምህም መቅደስን ሠሩባት።'),
  ('f94f8908-1795-5db8-a94c-be690de518e5', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 9, 9, 'እንዲህም አሉ፦ ክፉ ነገር፥ የፍርድ ሰይፍ ወይም ቸነፈር ወይም ራብ፥ ቢመጣብን በዚህ ቤት ፊትና በፊትህ እንቆማለን፤ ስምህ በዚህ ቤት ላይ ነውና፤ በመከራችንም ወደ አንተ እንጮኻለን፥ አንተም ሰምተህ ታድነናለህ።'),
  ('65f5f2b5-3966-5ad6-a0d8-b512831e80f4', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 10, 10, 'አሁንም እነሆ፥ እስራኤል ከግብዕ ምድር በወጡ ጊዜ ያልፉባቸው ዘንድ ያልፈቀድህላቸው የአሞንና የሞዓብ ልጆች፥ የሴይርም ተራራ ሰዎች እንዳያጠፉአቸው ከእነርሱ ፈቀቅ ብለው ነበር።'),
  ('1db7cc0b-a40a-52f9-aac9-97a2ca3b8ef4', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 11, 11, 'እነሆ፥ አሁን ለወሮታችን ክፋት ይመልሱልናል፤ ከሰጠኸንም ርስት ያወጡን ዘንድ መጥተዋል።'),
  ('5f560ad5-a910-52a8-a1b4-0fbe8b4cd559', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 12, 12, 'አምላካችን ሆይ፥ አንተ አትፈርድባቸውምን? ይህን የመጣብንን ታላቅ ወገን መቃወም እንችል ዘንድ ኀይል የለንም፤ የምናደርግባቸውንም አናውቅም፤ ነገር ግን ዐይኖቻችን ወደ አንተ ናቸው።”'),
  ('4661007f-12d2-560e-a0cd-b8527511a678', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 13, 13, 'የይሁዳም ሰዎች ሁሉ ከሚስቶቻቸው፥ ከልጆቻቸውም ጋር በእግዚአብሔር ፊት ቆመው ነበር።'),
  ('cf2d80e4-ec7f-5ceb-aba6-e394a62074eb', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 14, 14, 'የእግዚአብሔርም መንፈስ ከአሳፍ ወገን በነበረው በሌዋዊው በምታንያስ ልጅ በኢያሔል ልጅ በብልአንያ ልጅ በዘካርያስ ልጅ በኡዝሔል ላይ በጉባኤው መካከል መጣ፤'),
  ('48ef313a-7ab2-59e9-ae4b-0fca859b5ecd', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 15, 15, 'እንዲህም አለ፥ “ይሁዳ ሁሉ፥ በኢየሩሳሌምም የምትኖሩ፥ አንተም ንጉሡ ኢዮሣፍጥ! ስሙ፤ እግዚአብሔር እንዲህ ይላችኋል፦ ሰልፉ የእግዚአብሔር ነው እንጂ የእናንተ አይደለምና ከዚህ ታላቅ ወገን የተነሣ አትፍሩ፤ አትደንግጡም።'),
  ('96149f40-f892-5b95-a15d-711b287b4509', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 16, 16, 'ነገ በእነርሱ ላይ ውረዱ፤ እነሆ፥ በአሲስ ዐቀበት ይወጣሉ፤ በሸለቆውም መጨረሻ በኢያርሔል ምድረ በዳ ፊት ለፊት ታገኙአቸዋላችሁ።'),
  ('a2eff907-11b5-5a37-a43f-ef644020d7a8', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 17, 17, 'እናንተ የምቷጉ አይደላችሁም፤ ይሁዳና ኢየሩሳሌም ሆይ፥ ተሰለፉ፤ ዝም ብላችሁ ቁሙ፤ የሚሆነውንም የእግዚአብሔርን ማዳን እዩ፤ እግዚአብሔርም ከእናንተ ጋር ነውና አትፍሩ፤ አትደንግጡም፤ ነገም ውጡባቸው።”'),
  ('c8a39731-af5c-53bf-a318-8c53efc5c1bb', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 18, 18, 'ኢዮሣፍጥም በምድር ላይ ሰገደ፤ ይሁዳም ሁሉ፥ በኢየሩሳሌምም የሚኖሩ በእግዚአብሔር ፊት ወደቁ፤ ለእግዚአብሔርም ሰገዱ።'),
  ('96a24b79-15e9-54b0-a8b5-49ae3a25f5fe', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 19, 19, 'ሌዋውያንም፥ ከቀዓት ልጆችና ከቆሬ ልጆች የእስራኤልን አምላክ እግዚአብሔርን ከፍ ባለ ታላቅ ድምፅ ያመሰግኑ ዘንድ ቆሙ።'),
  ('3ce88919-6608-512c-a969-7351fcf0d1a5', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 20, 20, 'ማልደውም ተነሡ፤ ወደ ቴቁሔም ምድረ በዳ ወጡ፤ ሲወጡም ኢዮሣፍጥ ቆመና፥ “ይሁዳና በኢየሩሳሌም የምትኖሩ ሆይ፥ ስሙኝ፤ በአምላካችሁ በእግዚአብሔር እመኑ፥ ትጸኑማላችሁ፤ በነቢዩም እመኑ፤ ነገሩም ይቀናላችኋል” አለ።'),
  ('f255b467-bdd3-56ad-a2b4-569a9d30e5a5', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 21, 21, 'ከሕዝቡም ጋር ተማክሮ በሠራዊቱ ፊት የሚሄዱትን፥ “ምሕረቱ ለዘለዓለም ነውና እግዚአብሔርን አመስግኑ” የሚሉትንም፥ በቅድስና የሚያመሰግኑትን፥ ለእግዚአብሔርም የሚዘምሩትን መዘምራን አቆመ።'),
  ('8eee8096-e084-5787-a079-ab795a47e191', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 22, 22, 'ዝማሬውንና ምስጋናውንም በጀመሩ ጊዜ ይሁዳን ሊወጉ በመጡት በአሞንና በሞዓብ ልጆች በሴይርም ተራራ ሰዎች ላይ እግዚአብሔር ኀይልን ሰጣቸው፤ እነርሱም ተመቱ።'),
  ('0a204d7a-5111-5fda-a333-891fdc4d84a7', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 23, 23, 'የአሞንና የሞዓብ ልጆችም በሴይር ተራራ በሚኖሩት ላይ ፈጽመው ይገድሉአቸው ዘንድ፥ ያጠፉአቸውም ዘንድ ተነሥተውባቸው ነበር፤ በሴይርም የሚኖሩትን ካጠፉ በኋላ እርስ በርሳቸው ሊጠፋፉ ተነሡ።'),
  ('3529661a-bba3-5ce1-a156-c87f3d981263', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 24, 24, 'የይሁዳም ሰዎች ወደ ምድረ በዳው መጠበቂያ ግንብ በመጡ ጊዜ ሕዝቡን አዩ፤ እነሆም፥ በምድሩ ሁሉ ሬሳ ሞልቶ ነበር፤ ያመለጠም ሰው አልነበረም።'),
  ('7297a2eb-6d0a-5a48-aefe-5088e94f3cca', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 25, 25, 'ኢዮሳፍጥና ሕዝቡም ምርኮ ይወስዱ ዘንድ መጡ፤ ብዙ ከብትና ልዩ ልዩ ዕቃም፥ ልብስም፥ እጅግም ያማረ ዕቃ አገኙ፤ ማረኩትም፤ ምርኮውም ብዙ ነበርና ምርኮውን እየሰበሰቡ እስከ ሦስት ቀን ድረስ ቈዩ።'),
  ('6296b885-deed-5114-ab21-d1c1cfb1a5f4', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 26, 26, 'በአራተኛውም ቀን በበረከት ሸለቆ ውስጥ ተሰበሰቡ፤ በዚያም እግዚአብሔርን አመሰገኑ፤ ስለዚህም ያ ስፍራ እስከ ዛሬ ድረስ የበረከት ሸለቆ ተባለ።'),
  ('8f52ac46-0d14-52b5-ab2f-7b344d4a3582', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 27, 27, 'የይሁዳ ሰዎች ሁሉ፥ ንጉሣቸውም ኢዮሣፍጥ፥ እግዚአብሔር በጠላቶቻቸው ላይ ደስ አሰኝቶአቸዋልና በደስታ ወደ ኢየሩሳሌም ተመለሱ።'),
  ('45753c33-8136-5cf7-a2db-1a59caa60055', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 28, 28, 'በበገናና በመሰንቆ፥ በመለከትም ወደ ኢየሩሳሌም ወደ እግዚአብሔር ቤት ገቡ።'),
  ('b350e770-ab18-5d49-a2d4-958905652d9d', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 29, 29, 'እግዚአብሔር የእስራኤልን ጠላቶች እንደ ወጋ በሰሙ ጊዜ በምድር ነገሥታት ሁሉ ላይ የእግዚአብሔር ፍርሀት ሆነ።'),
  ('3018b642-e084-5bb7-a3c6-293f0cd748ef', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 30, 30, 'የኢዮሣፍጥም መንግሥት ሰላም ሆነች፤ አምላኩም እግዚአብሔር በዙሪያው ካሉ አሳረፈው።'),
  ('4ba86f9d-39d0-5c8f-affd-7f2617506a71', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 31, 31, 'ኢዮሣፍጥም በይሁዳ ላይ ነገሠ፤ መንገሥ በጀመረ ጊዜም የሠላሳ አምስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ሃያ አምስት ዓመት ነገሠ፤ እናቱም የሳሊ ልጅ አዙባ ነበረች።'),
  ('296cb2ca-8d4c-531d-a171-7fdd70ba5cdb', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 32, 32, 'በአባቱም በአሳ መንገድ ሄደ፤ በእግዚአብሔርም ፊት ቅን የሆነውን ነገር ከማድረግ ፈቀቅ አላለም።'),
  ('dea2a04a-c4c6-5391-a40a-3435eb389128', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 33, 33, 'ነገር ግን ኮረብታዎች ገና በዚያ ነበሩ፤ ሕዝቡም ገና ልባቸውን ወደ አባቶቻቸው አምላክ ወደ እግዚአብሔር አላቀኑም ነበር።'),
  ('19073e2e-294e-54cb-a6bb-5c3e73bf44e3', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 34, 34, 'የቀረውም የፊተኞቹና የኋለኞቹ የኢዮሣፍጥ ነገሮች፥ እነሆ የእስራኤልን ነገሥታት ታሪክ በጻፈው በአናኒ ልጅ በነቢዩ በኢዩ ታሪክ ተጽፈዋል።'),
  ('d34b4a92-51c5-5b8c-a84e-ab1c4b5d691b', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 35, 35, 'ከዚህም በኋላ የይሁዳ ንጉሥ ኢዮሣፍጥ ከእስራኤል ንጉሥ ከአካዝያስ ጋር ተባበረ፤ ይህም በደልን የሠራ ነበር፦'),
  ('ee04dc4b-a396-5e63-a6c6-92c848f51532', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 36, 36, 'ወደ ተርሴስም የሚሄዱትን መርከቦች ያሠራ ዘንድ ከእርሱ ጋር አንድ ሆነ፤ መርከቦቹንም በጋሲዮንጋብር አሠሩ።'),
  ('50382643-a79a-5c0c-a263-94b85d4cda85', 'cd2dc998-5dfa-53dc-ae52-272edd7b3dbd', '78c73a10-b1f5-523a-a6cb-0d1ee7530eed', 37, 37, 'የማርሶስ ሰው የኢያድያ ልጅ አልዓዛር፥ “ከአካዝያስ ጋር ተባብረሃልና እግዚአብሔር ሥራህን አፍርሶታል” ብሎ በኢዮሣፍጥ ላይ ትንቢት ተናገረ። መርከቦቹም ተሰበሩ፤ ወደ ተርሴስም ይሄዱ ዘንድ አልቻሉም።'),
  ('c34aca71-aa10-553f-ac9d-b062ff7e066e', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 1, 1, 'ኢዮሣፍጥም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ተቀበረ፤ ልጁም ኢዮራም በእርሱ ፋንታ ነገሠ።'),
  ('fde3154b-ac70-5591-a9c3-cdce141d8e96', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 2, 2, 'ለእርሱም የኢዮሣፍጥ ልጆች አዛርያስ፥ ኢይሔል፥ ዘካርያስ፥ ዔዛርያስ፥ ሚካኤል፥ ሰፋጥያስ የሚባሉ ስድስት ወንድሞች ነበሩት፤ እነዚህ ሁሉ የይሁዳ ንጉሥ የኢዮሣፍጥ ልጆች ነበሩ።'),
  ('8cf69a60-7ebe-5a3c-a93d-79f0d2bc052e', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 3, 3, 'አባታቸውም ብዙ ስጦታ፥ ብርና ወርቅ፥ የከበረም ዕቃ፥ በይሁዳም የተመሸጉትን ከተሞች ሰጣቸው፤ መንግሥቱን ግን የበኵር ልጁ ስለሆነ ለኢዮራም ሰጠው።'),
  ('9108d4a8-70f5-5d3c-a063-7e5b77b0b27f', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 4, 4, 'ኢዮራምም በአባቱ መንግሥት ላይ ተነሥቶ በጸና ጊዜ ወንድሞቹን ሁሉ፥ ሌሎችንም የእስራኤልን መሳፍንት በሰይፍ ገደለ።'),
  ('e82fead5-45ef-50f7-af02-1d7cfda04bf3', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 5, 5, 'ኢዮራምም መንገሥ በጀመረ ጊዜ የሠላሳ ሁለት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ስምንት ዓመት ነገሠ።'),
  ('0974b095-f601-5530-a251-3f172d09000d', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 6, 6, 'የአክዓብንም ልጅ አግብቶ ነበርና የአክዓብ ቤት እንዳደረገ በእስራኤል ነገሥታት መንገድ ሄደ፤ በእግዚአብሔርም ፊት ክፉ አደረገ።'),
  ('35f9d69b-1748-5921-adbb-773d37ebe976', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 7, 7, 'ነገር ግን ከዳዊት ጋር ስላደረገው ቃል ኪዳን፥ ለእርሱና ለልጆቹም በዘመናት ሁሉ መብራትን ይሰጠው ዘንድ ስለ ሰጠው ተስፋ እግዚአብሔር የዳዊትን ቤት ያጠፋ ዘንድ አልወደደም።'),
  ('3b4fe019-4489-5916-a7b1-9a80633eb406', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 8, 8, 'በእነዚያም ዘመናት የኤዶምያስ ሰዎች በይሁዳ ላይ ዐመፁ፤ ለራሳቸውም ንጉሥ አነገሡ።'),
  ('35ee2cd2-5adb-595c-a0a6-70826216b648', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 9, 9, 'ኢዮራምም ከአለቆቹና ከሰረገሎቹ ሁሉ ጋር ተሻገረ፤ በሌሊትም ተነሥቶ እርሱንና የሰረገሎቹን አለቆች ከብበው የነበሩትን የኤዶምያስ ሰዎችን መታ፤ ሕዝቡም ወደ ድንኳናቸው ሸሹ።'),
  ('663dbea4-86b8-5392-ae39-f2c08ee2c7e2', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 10, 10, 'ኤዶምያስ ግን በይሁዳ ላይ እስከ ዛሬ ድረስ ዐመፀ፤ በዚያም ዘመን ልብና ደግሞ በእርሱ ላይ ዐመፀ፤ የአባቶቹን አምላክ እግዚአብሔርን ትቶ ነበርና።'),
  ('9bf5b6b5-fa3b-527f-a330-061fab728f9a', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 11, 11, 'ደግሞም በይሁዳ ተራሮች ላይ መስገጃዎችን ሠራ፤ በኢየሩሳሌምም የተቀመጡትን እንዲያመነዝሩ አደረጋቸው፤ የይሁዳንም ሰዎች አሳታቸው።'),
  ('0b878305-ec8d-5ddc-ae61-2580f0f3accf', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 12, 12, 'ከነቢዩም ከኤልያስ እንዲህ የሚል ጽሕፈት መጣበት፥ “የአባትህ የዳዊት አምላክ እግዚአብሔር እንዲህ ይላል፦ በአባትህ በኢዮሣፍጥ መንገድ፥ በይሁዳም ንጉሥ በአሳ መንገድ አልሄድህምና፥'),
  ('3a3782c4-653b-5f2b-a6a8-c57dfc96ea08', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 13, 13, 'በእስራኤል ነገሥታት መንገድ ግን ሄደሃልና፥ የአክዓብም ቤት እንዳደረገ ይሁዳንና በኢየሩሳሌም የሚኖሩትን እንዲያመነዝሩ አድርገሃልና፥ ከአንተም የሚሻሉትን የአባትህን ቤት ወንድሞችህን ገድለሃልና፥'),
  ('81d8c653-b910-561c-af85-22735b22dfdc', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 14, 14, 'እነሆ፥ እግዚአብሔር ሕዝብህንና ልጆችህን፥ ሚስቶችህንም፥ ያለህንም ንብረት ሁሉ በታላቅ መቅሠፍት ይቀሥፋል።'),
  ('159d5b58-26fb-50ad-ab37-94b71f3894cf', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 15, 15, 'አንተም ከደዌው ጽናት የተነሣ አንጀትህ በየዕለቱ እስኪወጣ ድረስ በክፉ የአንጀት ደዌ ትታመማለህ።”'),
  ('ae2c5ab2-6ae6-5926-a299-437390f8dfbd', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 16, 16, 'እግዚአብሔርም ፍልስጥኤማውያንንና በኢትዮጵያውያን አጠገብ የሚኖሩትን የዓረብያን ሰዎች በኢዮራም ላይ አስነሣ።'),
  ('3c067d07-01e6-5746-ac6a-8d6b37b1a6e9', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 17, 17, 'ወደ ይሁዳም ወጡ፤ በረቱባቸውም፤ የንጉሡንም ቤት ዕቃ ሁሉ፥ ወንዶች ልጆቹንም፥ ሴቶች ልጆቹንም ወሰዱ፤ ከታናሹም ልጅ ከአካዝያስ በቀር ልጅ አልቀረለትም።'),
  ('41cac552-3a9a-5e80-a146-5161af2ec580', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 18, 18, 'ከዚህም ሁሉ በኋላ እግዚአብሔር መድኀኒት በማይገኝለት ደዌ አንጀቱን ቀሠፈው።'),
  ('6a09eed4-5620-5dcc-a6cb-8a730e14d999', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 19, 19, 'ከቀንም ወደ ቀን እንዲህ ሆነ፤ ከሁለት ዓመት በኋላ ከደዌው ጽናት የተነሣ አንጀቱ ወጣ፤ በክፉም ደዌ ሞተ። ሕዝቡም ለአባቶቹ ያደርገው እንደ ነበረ ለእርሱ የመቃብር ወግ አላደረገም።'),
  ('9d1c9860-63df-57a3-a56f-e852d1ac0da7', 'd4cd65e4-a4a2-5cd2-a341-9ad9a3d27412', '89e11555-dd53-53bb-aec3-0e62eb4225ab', 20, 20, 'መንገሥም በጀመረ ጊዜ የሠላሳ ሁለት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ስምንት ዓመት ነገሠ፤ ማንም ሳያዝንለት ሄደ፤ በዳዊትም ከተማ እንጂ በነገሥታት መቃብር አልቀበሩትም።'),
  ('c40e178d-bd33-5511-ae83-d4bfe86a17c8', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 1, 1, 'በኢየሩሳሌምም የነበሩት ታናሹን ልጁን አካዝያስን በእርሱ ፋንታ አነገሡት። የመጣባቸው የዓረብና የአሊማዞን የሽፍቶች ጭፍራ የእርሱን ታላቆች ወንድሞች ገድለዋቸው ነበርና የይሁዳ ንጉሥ የኢዮራም ልጅ አካዝያስ ነገሠ።'),
  ('c953a29b-2b83-5a5a-abaa-bab43bae2e8f', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 2, 2, 'አካዝያስም መንገሥ በጀመረ ጊዜ ዕድሜው ሃያ ሁለት ዓመት ነበረ፥ በኢየሩሳሌምም አንድ ዓመት ነገሠ፤ እናቱም ጎቶልያ የተባለች የዘንበሪ ልጅ ነበረች።'),
  ('82646f9e-3c8a-5f69-a779-6ab25558967e', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 3, 3, 'እናቱም ክፉ እንዲያደርግ ትመክረው ነበርና እርሱ ደግሞ በአክዓብ ቤት መንገድ ሄደ።'),
  ('431764af-1a2f-561f-a6a8-818722ef5e18', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 4, 4, 'ከአባቱም ሞት በኋላ የአክዓብ ቤት እንዳደረገ በእግዚአብሔር ፊት ክፉ አደረገ፤ ያጠፉት ዘንድ መካሪዎች ነበሩትና።'),
  ('7c26d179-fd75-5939-a2eb-c47ba02bf81b', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 5, 5, 'በምክራቸውም ሄደ፤ ከእስራኤልም ንጉሥ ከአክዓብ ልጅ ከኢዮራም ጋር የሶርያን ንጉሥ አዛሄልን በሬማት ዘገለዓድ ሊዋጋ ሄደ፤ ሶርያውያንም ኢዮራምን አቈሰሉት።'),
  ('b69060aa-882e-57a3-aad9-fb82fa2def17', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 6, 6, 'ከሶርያም ንጉሥ ከአዛሄል ጋር በተዋጋ ጊዜ ሶርያውያን በሬማት ያቈሰሉትን ቍስል ይታከም ዘንድ ወደ ኢይዝራኤል ተመለሰ፤ ታምሞም ነበርና የይሁዳ ንጉሥ የኢዮራም ልጅ አካዝያስ የአክዓብን ልጅ ኢዮራምን ያይ ዘንድ ወደ ኢይዝራኤል ወረደ።'),
  ('edc9282a-accc-5eef-a1fa-6197bdbe424b', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 7, 7, 'ወደ ኢዮራም በመምጣቱም የአካዝያስ ጥፋት ከእግዚአብሔር ሆነ፤ በመጣም ጊዜ ከኢዮራም ጋር እግዚአብሔር የአክዓብን ቤት ያጠፋ ዘንድ ወደ ቀባው ወደ ናሚሲ ልጅ ወደ ኢዩ ወጣ።'),
  ('c73c9322-bac4-534f-a174-5b0c72d31150', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 8, 8, 'ኢዩም የአክዓብን ቤት ይበቀል ዘንድ የይሁዳን መሳፍንትና አካዝያስን ያገለግሉ የነበሩትን የአካዝያስን ወንድሞች አግኝቶ ገደላቸው።'),
  ('ed7789a4-6773-5a0d-a9b6-b932f4e0cc95', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'ce93d565-ab7d-5fb7-ac0c-629b954d4447', 9, 9, 'አካዝያስንም ፈለገው፤ በሰማርያም እየታከመ ሳለ አገኙት፤ ወደ ኢዩም አመጡት፤ እርሱም ገደለው፦ እነርሱም፥ “በፍጹም ልብ እግዚአብሔርን የፈለገው የኢዮሣፍጥ ልጅ ነው” ብለው ቀበሩት። ከአካዝያስም ቤት ማንም መንግሥትን ይይዝ ዘንድ የሚችል አልነበረም።'),
  ('d76a9ed8-f563-5d96-aa7e-422f93b459d6', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'e449a9d3-e740-530d-a0aa-316764d69c9a', 1, 10, 'የአካዝያስም እናት ጎቶልያ ልጅዋ እንደ ሞተ ባየች ጊዜ ተነሥታ የይሁዳን ቤተ መንግሥት ዘር ሁሉ አጠፋች።'),
  ('6068bfff-2e2f-5e22-a041-347e2b6b297c', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'e449a9d3-e740-530d-a0aa-316764d69c9a', 2, 11, 'የንጉሡ ልጅ ዮሳቤት ግን ከተገደሉት ከንጉሡ ልጆች መካከል የአካዝያስን ልጅ ኢዮአስን ሰርቃ ወሰደች፤ እርሱንና ሞግዚቱን በእልፍኝ ውስጥ አኖረቻቸው፤ የንጉሡ የኢዮራም ልጅ የአካዝያስ እኅት የካህኑ የዮዳሄ ሚስት ዮሳቤት ከጎቶልያ ፊት ሸሸገችው፤ እርስዋም አልገደለችውም።'),
  ('ecd7a35c-dba1-5b27-a342-c39546509d7d', '4282104a-1ab5-5a57-abd8-488f204bcb8f', 'e449a9d3-e740-530d-a0aa-316764d69c9a', 3, 12, 'ከእርስዋም ጋር በእግዚአብሔር ቤት ተሸሽጎ ስድስት ዓመት ያህል ተቀመጠ፤ ጎቶልያም በምድር ላይ ነገሠች።'),
  ('cc72a34e-a2e0-543e-ac1d-0335474fbe53', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 1, 1, 'በሰባተኛውም ዓመት ኢዮአዳ በረታ፤ የመቶ አለቆቹንም፥ የኢዮራምን ልጅ አዛርያስን፥ የኢዮአናንም ልጅ እስማኤልን፥ የዖቤድንም ልጅ አዛርያን፥ የኢዳኢንም ልጅ መዓስያን፥ የዘካርያስንም ልጅ ኤሊሳፋጥን ወደ እግዚአብሔር ቤት ከእርሱ ጋር ወሰደ።'),
  ('91642b1e-ab33-5e4d-a26d-64472bd8fe1b', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 2, 2, 'ይሁዳንም ዞሩ፤ በይሁዳም ከተሞች ሁሉ ሌዋውያንንና የእስራኤልን አባቶች ቤቶች አለቆች ሰብስበው ወደ ኢየሩሳሌም መጡ።'),
  ('7590df8e-b90a-507b-ad46-64758fc9ade1', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 3, 3, 'የይሁዳም ጉባኤ ሁሉ በእግዚአብሔር ቤት ውስጥ ከንጉሥ ጋር ቃል ኪዳን አደረገ። የንጉሥንም ልጅ አሳያቸው፤ አላቸውም፥ “እነሆ፥ እግዚአብሔር ስለ ዳዊት ቤት እንደ ተናገረ የንጉሡ ልጅ ይነግሣል።'),
  ('51d8bc41-dd1d-5ba0-a888-f21da902675b', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 4, 4, 'እነሆ፥ የምታደርጉት ይህ ነው፤ በሰንበት ቀን ከምትገቡት ከእናንተ ከካህናትና ከሌዋውያን ከሦስት አንድ እጅ በመግቢያ በሮች በረኞች ሁኑ፤'),
  ('1089ee2d-07c3-5196-a393-7fdaf0f469d4', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 5, 5, 'ከሦስት አንድ እጅም በንጉሡ ቤት ሁኑ፤ ሌላውም ከሦስት አንድ እጅ በመካከለኛው በር ሁኑ፤ ሕዝቡም ሁሉ በእግዚአብሔር ቤት አደባባይ ይሁኑ።'),
  ('770a0332-8c15-53c2-add3-e4c51119841e', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 6, 6, 'ወደ እግዚአብሔር ቤት ግን ከካህናትና ከሌዋውያን ከሌዋውያኑም አገልጋዮች በቀር ማንም አይግባ፤ እነርሱ ቅዱሳን ናቸውና ይግቡ፤ ሕዝቡም ሁሉ የእግዚአብሔርን ትእዛዝ ይጠብቅ።'),
  ('08e3099a-937d-58dd-aa3e-0c21a4aa3648', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 7, 7, 'ሌዋውያንም የጦር መሣሪያቸውን በእጃቸው ይዘው ንጉሡን በዙሪያው ይክበቡት፤ ወደ ቤቱም የሚገባ ይገደል፤ ንጉሡም ሲገባና ሲወጣ ከእርሱ ጋር ሁኑ።”'),
  ('1dbca6e1-dbb2-5b38-ae60-b8b867555540', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 8, 8, 'ሌዋውያንና ይሁዳም ሁሉ ካህኑ ኢዮአዳ ያዘዘውን ሁሉ አደረጉ፤ ካህኑም ኢዮአዳ ሰሞነኞቹን አላሰናበተም ነበርና እያንዳንዱ ከሰንበት መጀመሪያ እስከ ሰንበት መጨረሻ ሰዎችን ወሰደ።'),
  ('a75642c4-df66-5159-a30e-1ae893ffe873', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 9, 9, 'ካህኑም ኢዮአዳ በእግዚአብሔር ቤት የነበረውን የንጉሡን የዳዊትን ሰይፍና ጦር፥ አላባሽ አግሬውንም ጋሻ ለመቶ አለቆች ሰጣቸው።'),
  ('e6a14daa-2e2c-5dbe-a783-360a0237cec4', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 10, 10, 'ሕዝቡም ሁሉ እያንዳንዱ የጦር መሣሪያውን በእጁ እየያዘ በንጉሡ ዙሪያ ከቤተ መቅደሱ ቀኝ እስከ ቤተ መቅደሱ ግራ ድረስ በመሠዊያውና በመቅደሱ አጠገብ እንዲቆም አደረገ።'),
  ('5cf6846f-55f6-59fa-a2fb-5f9250af36af', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 11, 11, 'የንጉሡንም ልጅ አውጥቶ ዘውዱን ጫነበት፤ ምስክሩንም ሰጠው፤ አነገሡትም፤ ኢዮአዳና ልጆቹም አነገሡት፥ “ንጉሡ በሕይወት ይኑር” እያሉም ቀቡት።'),
  ('4db1e27f-c7f4-533d-af40-11c932010b31', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 12, 12, 'ጎቶልያም የሚሮጡትንና ንጉሡን የሚያመሰግኑትን የሕዝቡን ድምፅ በሰማች ጊዜ ወደ ሕዝቡ ወደ እግዚአብሔር ቤት መጣች።'),
  ('dee95ebf-e385-533f-aa8d-f1b264db58b9', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 13, 13, 'እነሆም፥ ንጉሡ በመግቢያው በዓምዱ አጠገብ ሆኖ በንጉሡም ዙሪያ አለቆችና መለከተኞች፥ መኳንንትም ቆመው አየች። ሕዝቡም ሁሉ ደስ ብሎአቸው መለከቱን ይነፉ ነበር፤ መዘምራንም በዜማ ዕቃ እያዜሙ የምስጋና መዝሙር ይዘምሩ ነበር። ጎቶልያም ልብስዋን ቀድዳ፥ “ዐመፅ ነው! ዐመፅ ነው!” ብላ ጮኸች።'),
  ('29d58db2-0337-5b95-a113-9df0b9a194e4', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 14, 14, 'ካህኑም ኢዮአዳ ወጥቶ በጭፍራው ላይ የተሾሙትን አለቆችና የመቶ አለቆች፥ “ከቤተ እግዚአብሔር ወደ ውጭ አውጡአት፤ የሚከተላትም በሰይፍ ይገደል” ብሎ አዘዛቸው። ካህኑ፥ “በእግዚአብሔር ቤት ውስጥ አትገደል” ብሎአልና።'),
  ('94f99e8b-628f-5d4a-ad10-aacca5578cf1', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 15, 15, 'ገለልም ብለው አሳለፉአት፤ እርስዋም ወደ ፈረሱ በር መግቢያ ወደ ንጉሡ ቤት ሄደች፤ በዚያም ገደሉአት።'),
  ('6ee134ff-aef9-5043-ae49-82beb31c3a36', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 16, 16, 'ካህኑ ኢዮአዳም በእርሱና በሕዝቡ ሁሉ፥ በንጉሡም መካከል የእግዚአብሔር ሕዝብ ይሆኑ ዘንድ ቃል ኪዳን አደረገ።'),
  ('351503de-7a76-553a-a2fe-57894227fef5', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 17, 17, 'የሀገሩም ሕዝብ ሁሉ ወደ በዓል ቤት ሄደው አፈረሱት፤ መሠዊያዎቹንና ምስሎቹንም አደቀቁ፤ የበዓልንም ካህን ማታንን በመሠዊያው ፊት ገደሉት።'),
  ('5b389fde-fa0d-5421-ac9f-846d347ea480', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 18, 18, 'ካህኑ ኢዮአዳም በሙሴ ሕግ እንደ ተጻፈው እንደ ዳዊት ትእዛዝ በደስታና በመዝሙር ለእግዚአብሔር የሚቃጠለውን መሥዋዕት ያቀርቡ ዘንድ ዳዊት በእግዚአብሔር ቤት የከፈላቸውን ካህናትና ሌዋውያን በእግዚአብሔር ቤት አገልግሎት ላይ ሾመ።'),
  ('8e484b51-b783-5db2-a0b1-22be0caa8e93', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 19, 19, 'በማናቸውም ነገር ሁሉ ርኩስ የሆነ ሰው እንዳይገባ በእግዚአብሔር ቤት በር በረኞችን አኖረ።'),
  ('26c28102-5d52-5f41-a194-912d8baeaf1b', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 20, 20, 'የመቶ አለቆችንም፥ ከበርቴዎችንም፥ የሕዝቡንም አለቆች፥ የሀገሩንም ሕዝብ ሁሉ ወሰደ፤ ንጉሡንም ከእግዚአብሔር ቤት አወረዱት፤ በእግዚአብሔርም ቤት በውስጠኛው በር በኩል ወደ ንጉሡ ቤት አመጡት፤ ንጉሡንም በመንግሥቱ ዙፋን ላይ አስቀመጡት።'),
  ('626d8f29-155e-5d50-a0a5-8f1753ed24a4', '95ffa885-0381-5cb6-acee-30cc209b9d15', '3e12cc80-7f81-58a3-a1aa-6de101096b44', 21, 21, 'የሀገሩም ሕዝብ ሁሉ ደስ አላቸው፤ ከተማዪቱም ጸጥ አለች፤ ጎቶልያንም በሰይፍ ገደሉአት።'),
  ('d33161ae-bc75-57fc-ad51-d11ec6517876', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 1, 1, 'ኢዮአስም መንገሥ በጀመረ ጊዜ የሰባት ዓመት ልጅ ነበረ፤ በኢየሩሳሌምም አርባ ዓመት ነገሠ፤ እናቱ ሳብያ የተባለች የቤርሳቤህ ሴት ነበረች።'),
  ('0759606e-53e9-5870-a454-1d6118fe28e9', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 2, 2, 'ኢዮአስም በካህኑ በኢዮአዳ ዘመን ሁሉ በእግዚአብሔር ፊት ቅን ነገርን አደረገ።'),
  ('18d50f8e-bd50-5c92-afe5-9c12957c69e0', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 3, 3, 'ኢዮአዳም ሁለት ሚስቶችን አጋባው፤ ወንዶችና ሴቶች ልጆችንም ወለደ።'),
  ('4fc134c6-f5e0-56d9-a766-73402a6e438e', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 4, 4, 'ከዚህም በኋላ ኢዮአስ የእግዚአብሔርን ቤት ይጠግን ዘንድ አሰበ።'),
  ('ab6fe486-96f7-5482-a9a8-ce99989b5eac', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 5, 5, 'ካህናትንና ሌዋውያንንም ሰብስቦ፥ “ወደ ይሁዳ ከተሞች ውጡ፤ የአምላካችሁንም ቤት በየዓመቱ ለማደስ የሚበቃ ከእስራኤል ሁሉ ገንዘብን ሰብስቡ፤ ነገሩንም ፈጥናችሁ አድርጉ” አላቸው። ሌዋውያን ግን አላፋጠኑም።'),
  ('771644dc-b53f-5858-abe9-8a07652d0bbf', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 6, 6, 'ንጉሡ ኢዮአስም አለቃውን ኢዮአዳን ጠርቶ፥ “የእግዚአብሔር ባሪያ ሙሴ እስራኤልን በምስክሩ ድንኳን በሰበሰበ ጊዜ እንዲያዋጣ ያዘዘውን ግብር ከይሁዳና ከኢየሩሳሌም ያመጡ ዘንድ ስለ ምን ሌዋውያንን አልተከታተልህም?” አለው።'),
  ('1b4d76bc-ac93-52d4-a098-d6d737317cb1', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 7, 7, 'ጎቶልያ ከሐዲት ነበረችና ልጆችዋም የእግዚአብሔርን ቤት አፍርሰዋልና፤ በእግዚአብሔርም ቤት ተቀድሶ የነበረውን ሁሉ ለበኣሊም ሰጥተዋልና።'),
  ('e1c713ef-8230-57c1-a0cd-87953cbff46d', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 8, 8, 'ንጉሡም ሣጥን ሠርተው በእግዚአብሔር ቤት በር አጠገብ በስተውጭ ያኖሩት ዘንድ አዘዘ።'),
  ('8055b94a-9bad-5cb0-ac1e-4bd5f5b962ce', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 9, 9, 'የእግዚአብሔርም ባሪያ ሙሴ በምድረ በዳ በእስራኤል ላይ ያዘዘውን ግብር ለእግዚአብሔር ያመጡ ዘንድ፥ በይሁዳና በኢየሩሳሌም ያስተምሩ ዘንድ አዘዘ።'),
  ('0b84c019-7531-5673-af14-a7695f642287', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 10, 10, 'አለቆቹና ሕዝቡም ሁሉ ሰጡ፤ እስኪሞላም ድረስ በሣጥኑ ውስጥ አስገቡት።'),
  ('0ff3c460-4036-5412-a5b5-e6f0b9dc81f7', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 11, 11, 'ሣጥኑም በሌዋውያን እጅ ወደ ንጉሡ ሹሞች በደረሰ ጊዜ፥ ብዙ ገንዘብም እንዳለበት ባዩ ጊዜ፥ የንጉሡ ጸሓፊና የሊቀ ካህናቱ ሹም እየመጡ ብሩን ከሣጥን ያወጡ ነበር፤ ሣጥኑንም ደግሞ ወደ ስፍራው ይመልሱት ነበር። እንዲሁም በየቀኑ ያደርጉ ነበር፤ ብዙም ገንዘብ ሰበሰቡ።'),
  ('683b9676-9c86-57a5-ac8e-c374f00d4a51', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 12, 12, 'ንጉሡና ኢዮአዳም በእግዚአብሔር ቤት ሥራ ላይ ለተሾሙት ሰጡአቸው፤ እነርሱም የእግዚአብሔርን ቤት የሚጠግኑትን ጠራቢዎችንና አናጢዎችን፥ የእግዚአብሔርንም ቤት የሚያድሱትን የብረትና የናስ ሠራተኞችን ይቀጥሩበት ነበር።'),
  ('8d327458-4677-56e3-ad32-6bec47d2cf7a', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 13, 13, 'ሠራተኞችም ሠሩ፤ ሥራውም ሁሉ በእጃቸው ተፈጸመ፤ የእግዚአብሔርንም ቤት እንደ ቀድሞው ሥራ መለሱ፤ አጽንተውም አቆሙት።'),
  ('94c22b10-3b32-5f8a-a3bc-499fdb8c02eb', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 14, 14, 'በጨረሱም ጊዜ የተረፈውን ገንዘብ ወደ ንጉሡና ወደ ካህኑ ኢዮአዳ ፊት አመጡ፤ እነርሱም ለእግዚአብሔር ቤት ዕቃ፥ ለአገልግሎትና ለቍርባን ዕቃ፥ ለጭልፋዎችም፥ ለወርቅና ለብርም ዕቃ አደረጉት። በኢዮአዳም ዘመን ሁሉ ለእግዚአብሔር ቤት የሚቃጠል መሥዋዕት ሁልጊዜ ያቀርቡ ነበር።'),
  ('785b1b24-a6ee-5b52-a5aa-03b8def9a110', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 15, 15, 'ኢዮአዳም ሸመገለ፤ ዕድሜም ጠግቦ ሞተ፤ በሞተም ጊዜ ዕድሜው መቶ ሠላሳ ዓመት ነበረ።'),
  ('c4aa4deb-50c7-54fb-a9c3-7f1e100a8ecf', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 16, 16, 'ከእስራኤልም ጋር፥ ከእግዚአብሔርና ከቤቱም ጋር መልካም ሠርቶአልና በዳዊት ከተማ ከነገሥታቱ ጋር ቀበሩት።'),
  ('57fa658d-d4b8-5d63-a0c4-f6f2cdcdd0ce', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 17, 17, 'ካህኑ ኢዮአዳም ከሞተ በኋላ የይሁዳ አለቆች ገብተው ለንጉሡ ሰገዱ፤ ንጉሡም ሰማቸው።'),
  ('1059955f-1574-5f5f-aa8e-2e1f4af7def8', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 18, 18, 'የአባቶቻቸውንም አምላክ የእግዚአብሔርን ቤት ትተው ባዕድ አምላክንና ጣዖታትን አመለኩ፤ በዚያም ወራት በይሁዳና በኢየሩሳሌም ላይ ቍጣ ወረደ።'),
  ('3332b071-5b74-5465-aea1-d99676590aa3', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 19, 19, 'ወደ እግዚአብሔርም ይመልሱአቸው ዘንድ ነቢያትን ይሰድድላቸው ነበር፤ መሰከሩባቸውም፤ እነርሱ ግን አላደመጡም።'),
  ('662c75b3-528b-5ce4-a35c-37d6b2fe9e84', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 20, 20, 'የእግዚአብሔርም መንፈስ በካህኑ በኢዮአዳ ልጅ በአዛርያስ ላይ መጣ፤ እርሱም በሕዝቡ ፊት ቆመና፥ “እግዚአብሔር እንዲህ ይላል፦ የእግዚአብሔርን ትእዛዝ ለምን ትተላለፋላችሁ? መልካምም አይሆንላችሁም፤ እግዚአብሔርን ስለ ተዋችሁ እርሱ ትቶአችኋል” አላቸው።'),
  ('6dea7f4d-4d48-5809-a449-1e681abf3134', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 21, 21, 'ወደ እርሱም ሮጡ በንጉሡም ትእዛዝ በእግዚአብሔር ቤት አደባባይ ውስጥ በድንጋይ ደበደቡት።'),
  ('256d67f7-5c34-56eb-a1eb-7d027f934740', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 22, 22, 'እንዲሁም ንጉሡ ኢዮአስ አባቱ ኢዮአዳ ያደረገለትን ቸርነት አላሰበም፤ ልጁንም አዛርያስን አስገደለው፤ እርሱም ሲሞት፥ “እግዚአብሔር ይየው፤ ይፍረደውም” አለ።'),
  ('6fd7a5c4-7363-5bf4-ab23-3ec7b4cae58c', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 23, 23, 'ዓመቱም ካለፈ በኋላ የሶርያውያን ሠራዊት መጡበት፤ ወደ ይሁዳና ወደ ኢየሩሳሌምም መጥተው ከሕዝቡ መካከል የሕዝቡን አለቆች ሁሉ አጠፉ፤ ምርኮአቸውንም ሁሉ ለደማስቆ ንጉሥ ላኩ።'),
  ('fd5cd5d4-dc71-5e67-a12a-6565a3b7782c', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 24, 24, 'የሶርያውያንም ሠራዊት ቍጥር ጥቂት ነበር፤ እግዚአብሔር ግን ብዙውንና ጠንካራውን ሠራዊት አሳልፎ በእጃቸው ሰጣቸው፤ የአባቶቻቸውን አምላክ እግዚአብሔርን ዘንግተዋልና። በኢዮአስም ላይ ፈረደበት።'),
  ('743e63fa-8760-5d9b-a3a9-709c8726b4c3', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 25, 25, 'ከእርሱም ዘንድ አልፈው ከሄዱ በኋላ እጅግ ታሞ ሳለ ተዉት፤ የገዛ ባሪያዎቹም ስለ ካህኑ ስለ ኢዮአዳ ልጅ ደም ተበቅለው በአልጋው ላይ ገደሉት፤ ሞተም፤ በዳዊትም ከተማ ቀበሩት፤ ነገር ግን በነገሥታት መቃብር አልቀበሩትም።'),
  ('574995c0-2681-5b00-ae9d-94d1b083bb1c', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 26, 26, 'የገደሉትም የአሞናዊቱ የሰማት ልጅ ዘቡድ፥ የሞዓባዊቱም የሰማሪት ልጅ ኢዮዛብድ ነበሩ።'),
  ('c3c17aed-1932-5b76-a2f5-2aff0aa5a2be', '4cb218d1-e067-51fd-ab96-fa7e1ba3b7cf', '78aae39c-484d-5d20-ae43-cdd9778c6fb1', 27, 27, 'የልጆቹና በእርሱ ላይ የተደረገው ነገር፥ የእግዚአብሔርንም ቤት ማደሱ፥ እነሆ በነገሥታቱ የታሪክ መጽሐፍ ተጽፎአል። ልጁም አሜስያስ በእርሱ ፋንታ ነገሠ።'),
  ('f8317060-d892-57ec-a9f6-ebbc7b2ec199', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ff405513-08d6-5212-ad98-85856cc3b2f5', 1, 1, 'አሜስያስም መንገሥ በጀመረ ጊዜ የሃያ አምስት ዓመት ጐልማሳ ነበረ፥ በኢየሩሳሌምም ሃያ ዘጠኝ ዓመት ነገሠ፤ እናቱ ኢዮዓዲን የተባለች የኢየሩሳሌም ሴት ነበረች።'),
  ('8e41ac29-d603-5d53-ab61-af455a094fc9', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ff405513-08d6-5212-ad98-85856cc3b2f5', 2, 2, 'በእግዚአብሔርም ፊት ቅን ነገርን አደረገ፤ ነገር ግን በፍጹም ልብ አይደለም።'),
  ('ccd0b1a1-a948-5574-a47f-df591ceb9dbf', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ff405513-08d6-5212-ad98-85856cc3b2f5', 3, 3, 'መንግሥትም በእጁ በጸናለት ጊዜ ንጉሡን አባቱን የገደሉትን ባሪያዎች ገደለ።'),
  ('db5c9fbf-8052-5df1-a02c-7c8cf61f1beb', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ff405513-08d6-5212-ad98-85856cc3b2f5', 4, 4, 'እንደ እግዚአብሔር ሕግ ቃል ኪዳን እንደ ተጻፈ፥ እግዚአብሔርም፥ “ሰው ሁሉ በገዛ ኀጢአቱ ይሙት እንጂ አባቶች በልጆቻቸው፥ ልጆችም በአባቶቻቸው ፋንታ አይሙቱ” ብሎ እንዳዘዘ ልጆቻቸውን ግን አልገደለም።'),
  ('41fcc254-8998-5fcf-ad4f-f4c7d3ae5505', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 1, 5, 'ንጉሡ አሜስያስም የይሁዳን ሕዝብ ሰበሰበ፤ እንደ እየአባቶቻቸውም ቤቶች አቆማቸው፤ በይሁዳና በኢየሩሳሌም ሁሉ የሽህ አለቆችንና የመቶ አለቆችን አደረገ፤ ከሃያ ዓመት ጀምሮ ከዚያም በላይ ያሉትን ሁሉ ቈጠረ፤ ለሰልፍም የሚወጡ፥ ጋሻና ጦርም የሚይዙ ሦስት መቶ ሺህ የተመረጡ ሰዎችን አገኘ።'),
  ('9a031597-f6f8-55f5-af9d-93f0abfff6cf', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 2, 6, 'ደግሞም ከእስራኤል ዘንድ መቶ ሺህ ጽኑዓን ኀያላን ሰዎችን በመቶ መክሊት ብር ቀጠረ።'),
  ('e61d25a8-2203-5e19-af58-5365e86664d5', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 3, 7, 'አንድ የእግዚአብሔር ሰው ግን ወደ እርሱ መጥቶ፥ “ንጉሥ ሆይ፥ እግዚአብሔር ከእስራኤልና ከኤፍሬም ልጆች ሁሉ ጋር አይደለምና የእስራኤል ጭፍራ ከአንተ ጋር አይውጣ።'),
  ('c9d08513-1178-5ae4-a603-8d296ee8fc65', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 4, 8, 'ብትሄድ ግን፥ በእነርሱም ማሸነፍን ብታስብ፥ የማጽናትና የመጣል ኀይል ከእግዚአብሔር ዘንድ ነውና እግዚአብሔር በጠላቶችህ ፊት ይጥልሃል” አለው።'),
  ('1e83f48a-c567-5076-a1a9-4eb22ab30a34', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 5, 9, 'አሜስያስም የእግዚአብሔርን ሰው፥ “ለእስራኤል ጭፍራ የሰጠሁት መቶ መክሊት ምን ይሁን?” አለው። የእግዚአብሔርም ሰው፥ “ከዚህ አብልጦ ይሰጥህ ዘንድ ለእግዚአብሔር አይሳነውም” ብሎ መለሰለት።'),
  ('7fb52d76-0ad5-5f32-a14a-9c5b920f0f8b', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 6, 10, 'ንጉሡ አሜስያስም ከኤፍሬም ከተሞች የመጡ ጭፍሮች ወደ ስፍራቸው ይመለሱ ዘንድ ለይቶ አሰናበታቸው፤ ስለዚህም ቍጣቸው በይሁዳ ላይ ጸና፤ ወደ ስፍራቸውም በጽኑ ቍጣ ተመለሱ።'),
  ('ebdf0ddc-61f6-58a5-a602-b7c408a28867', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 7, 11, 'አሜስያስም በረታ፤ ሕዝቡንም ሰብስቦ ወደ ጨው ሸለቆ ሄደ፤ ከሴይርም ልጆች ዐሥር ሺህ ገደለ።'),
  ('8a958a89-0666-5ef5-a7bf-eaaa32b89d9f', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 8, 12, 'የይሁዳም ልጆች ደግሞ ዐሥር ሺህ ሰዎችን ማረኩ። ወደ ዐለቱም ራስ ላይ አመጡአቸው፤ ከዐለቱም ራስ ላይ ጣሉአቸው፤ ሁሉም ተፈጠፈጡ።'),
  ('ab6ef1b8-d46c-5f13-ade3-f51c260b338a', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 9, 13, 'አሜስያስ ግን ከእርሱ ጋር ወደ ሰልፍ እንዳይሄዱ ያሰናበታቸው ጭፍሮችም ከሰማርያ ጀምረው እስከ ቤትሮን ድረስ በይሁዳ ከተሞች ላይ አደጋ ጣሉ፤ ከእነርሱም ሦስት ሺህ ገደሉ፤ ብዙም ምርኮ ማረኩ።'),
  ('f63b6fcc-6e7a-5211-a5d6-5fc073e9fbf8', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 10, 14, 'አሜስያስም የኤዶምያስን ሰዎች ከገደለ በኋላ የሴይርን ልጆች አማልክት አመጣ፤ የእርሱም አማልክት ይሆኑ ዘንድ አቆማቸው፤ በፊታቸውም ይሰግድላቸውና ይሠዋላቸው ነበር።'),
  ('416f8015-300d-551b-a1b3-9d933358aea1', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 11, 15, 'ስለዚህም የእግዚአብሔር ቍጣ በንጉሡ በአሜስያስ ላይ መጣ፤ እንዲህም ሲል ነቢይን ላከበት፥ “ሕዝባቸውን ከአንተ እጅ ያላዳኑትን የአሕዛብን አማልክት ስለምን ፈለግሃቸው?”'),
  ('bb216d5e-9156-583e-ab57-4dbbaf0a4c2d', 'b168be31-a696-59c9-a0d0-c82357c1775c', 'ba07cbaa-b0bb-5f02-af3d-6cc2762bd2ca', 12, 16, 'እርሱም ይህን ሲናገር ንጉሡ አሜስያስ፥ “በውኑ የንጉሡ አማካሪ ልትሆን ሹሜሃለሁን? ቅጣት እንዳያገኝህ ተጠንቀቅ” አለው። ነቢዩም፥ “ይህን አድርገሃልና፥ ምክሬንም አልሰማህምና እግዚአብሔር ሊያጠፋህ እንዳሰበ አወቅሁ” ብሎ ዝም አለ።'),
  ('d74d0a51-cc57-573e-aae5-904c218f7539', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 1, 17, 'የይሁዳም ንጉሥ አሜስያስ ምክር አደረገና፥ “ና፥ እርስ በርሳችን ፊት ለፊት እንተያይ” ብሎ ወደ እስራኤል ንጉሥ ወደ ኢዩ ልጅ ወደ ኢዮአካዝ ልጅ ወደ ኢዮአስ ላከ።'),
  ('3194af2c-5eb6-5d61-ab61-806f60104fc2', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 2, 18, 'የእስራኤልም ንጉሥ ኢዮአስ፦ ወደ ይሁዳ ንጉሥ ወደ አሜስያስ እንዲህ ሲል ላከ፥ “የሊባኖስ ኵርንችት ልጅህን ለልጄ ሚስት አድርገህ ስጠው” ብሎ ወደ ሊባኖስ ዝግባ ላከ፤ የሊባኖስም ዱር አውሬዎች መጥተው ኵርንችቱን ረገጡት።'),
  ('25a43edf-702e-51d5-af4b-ecb4a9e7bb19', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 3, 19, 'አንተም፦ እነሆ፥ ኤዶምያስን መትቻለሁ ብለህ በልብህ ኰርተሃል፤ በቤትህ ተቀመጥ፤ አንተ ከይሁዳ ጋር ትወድቅ ዘንድ ስለምን መከራን በራስህ ትሻለህ?”'),
  ('7d1e55c0-d0a5-5858-a9b7-33a586d0c7c6', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 4, 20, 'የኤዶምያስንም አማልክት ስለ ፈለጉ በጠላቶቻቸው እጅ አሳልፎ ይሰጣቸው ዘንድ ይህ ከእግዚአብሔር ዘንድ ነበረና አሜስያስ አልሰማም።'),
  ('a8364780-cebc-5acc-aa5f-d3d547cba68e', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 5, 21, 'የእስራኤልም ንጉሥ ኢዮአስ ወጣ፤ እርሱና የይሁዳ ንጉሥ አሜስያስም በይሁዳ ባለች በቤትሳሚስ ላይ እርስ በርሳቸው ተያዩ።'),
  ('666e8e8c-6f87-5a56-abb8-71805b95a2b6', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 6, 22, 'ይሁዳም በእስራኤል ፊት ድል ሆኑ፥ እያንዳንዳቸውም ወደ ድንኳናቸው ሸሹ።'),
  ('f0012d6d-12ae-5722-aa94-70a403cc876b', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 7, 23, 'የእስራኤልም ንጉሥ ኢዮአስ የይሁዳን ንጉሥ የአካዝያስን ልጅ የኢዮአስን ልጅ አሜስያስን በቤትሳሚስ ይዞ ወደ ኢየሩሳሌም አመጣው፤ የኢየሩሳሌምንም ቅጥር ከኤፍሬም በር ጀምሮ እስከ ማዕዘኑ በር ድረስ አራት መቶ ክንድ አፈረሰ።'),
  ('4f858df9-748b-5d25-ae89-bf7489403705', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 8, 24, 'ወርቁንና ብሩን ሁሉ፥ በእግዚአብሔርም ቤት በአብዲዶም እጅ የነበሩትን ዕቃዎች ሁሉ፥ በንጉሡም ቤተ መዛግብት የተገኘውን፥ በመያዣ የተያዙትንም ልጆች ወስዶ ወደ ሰማርያ ተመለሰ።'),
  ('26e1862d-6bb5-5360-ab9e-4f1d664dae6e', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 9, 25, 'የይሁዳ ንጉሥ የኢዮአስ ልጅ አሜስያስ ከእስራኤል ንጉሥ ከኢዮአካዝ ልጅ ከኢዮአስ ሞት በኋላ ዐሥራ አምስት ዓመት ኖረ።'),
  ('10143621-689f-50fb-af4c-02a03c7f3526', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 10, 26, 'የቀሩትም የፊተኞቹና የኋለኞቹ የአሜስያስ ነገሮች፥ እነሆ፥ በይሁዳና በእስራኤል ነገሥታት መጽሐፍ የተጻፈ አይደለምን?'),
  ('1c27ec5d-17ff-54c7-a861-2c8da2347ad2', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 11, 27, 'አሜስያስም እግዚአብሔርን ከመከተል በራቀ ጊዜ በኢየሩሳሌም የዐመፅ መሐላ አደረጉበት፤ ወደ ለኪሶም ኮበለለ፤ በስተኋላውም ወደ ለኪሶ ላኩ፤ በዚያም ገደሉት።'),
  ('36348eaf-50d3-50c7-a45a-15171e039599', 'b168be31-a696-59c9-a0d0-c82357c1775c', '571e8926-e9bd-5635-ae86-a6899bdb6913', 12, 28, 'በፈረስም ጭነው አመጡት፤ በዳዊትም ከተማ ከአባቶቹ ጋር ቀበሩት።'),
  ('f652d141-78aa-57cd-aca0-bc9a327e5aff', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 1, 1, 'የይሁዳም ሕዝብ ሁሉ የዐሥራ ስድስት ዓመት ጐልማሳ የነበረውን ዖዝያንን ወስደው በአባቱ በአሜስያስ ፋንታ አነገሡት።'),
  ('1fd1404c-3bfb-50ec-abed-a257b2065ad9', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 2, 2, 'ንጉሥ አባቱም ከአባቶቹ ጋር ከአንቀላፋ በኋላ ዖዝያን ኤላትን ሠራ፤ ወደ ይሁዳም መለሳት።'),
  ('633f1164-ce37-5acc-a538-d4ca444035a0', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 3, 3, 'ዖዝያንም መንገሥ በጀመረ ጊዜ የዐሥራ ስድስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም አምሳ ሁለት ዓመት ነገሠ፤ እናቱም ኢዮኮልያስ የተባለች የኢየሩሳሌም ሴት ነበረች።'),
  ('8124b137-e5dd-5b6f-a698-9b055ee7d68e', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 4, 4, 'አባቱም አሜስያስ እንዳደረገው ሁሉ በእግዚአብሔር ፊት ቅን ነገርን አደረገ።'),
  ('2b704fa8-7f1b-5887-a9b9-b757c1ce7959', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 5, 5, 'እግዚአብሔርንም መፍራት ባስተማረ በዘካርያስ ዘመን እግዚአብሔርን ይፈልግ ዘንድ ልብ አደረገ፤ በዘመኑም እግዚአብሔርን ፈለገ፤ እግዚአብሔርም ነገሩን አከናወነለት።'),
  ('720d3b31-3d70-5cdb-a177-c013e7fd6f1d', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 6, 6, 'ወጥቶም ከፍልስጥኤማውያን ጋር ተዋጋ፤ የጌትን ቅጥር፥ የኢያቢስንም ቅጥር፥ የአዛጦንንም ቅጥር አፈረሰ፤ በአዛጦንና በፍልስጥኤማውያንም ሀገር ከተሞችን ሠራ።'),
  ('3879b779-c248-53b1-af06-bdd876ae02a9', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 7, 7, 'እግዚአብሔርም በፍልስጥኤማውያንና በዓለት ላይ በሚኖሩ ዓረባውያን፥ በምዕዑናውያንም ላይ አጸናው።'),
  ('d41cb573-bd50-575b-a405-3c6a105a38e1', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 8, 8, 'አሞናውያንም ለዖዝያን ገበሩ፤ እጅግም በርትቶ ነበርና ዝናው እስከ ግብፅ መግቢያ ድረስ ተሰማ።'),
  ('35cdd957-9338-5965-a0a5-2e6c65fead12', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 9, 9, 'ዖዝያንም በኢየሩሳሌም በማዕዘኑ በርና በሸለቆው በር፥ ቅጥሩም በዞረበት ማዕዘን አጠገብ ግንቦችን ሠርቶ መሸጋቸው።'),
  ('9941029b-c540-52f9-a88b-537f3e2b4457', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 10, 10, 'በምድረ በዳውም ግንቦችን ሠራ፤ ብዙ ጕድጓድም ማሰ፤ በቆላውና በደጋው ብዙ እንስሶች ነበሩትና፤ ደግሞም እርሻ ይወድድ ነበርና በተራራማውና በፍሬያማው ስፍራ አራሾችና የወይን አትክልተኞች ነበሩት።'),
  ('5be05c45-db72-5024-a1d5-4ec3c7742e4f', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 11, 11, 'ደግሞም ለዖዝያን የሰልፍ ሠራዊት ነበሩት፤ በንጉሡ አለቃ በሐናንያ ትእዛዝ፥ በአለቃው በመዕሤያና በጸሓፊው በኢዮሔል እጅ እንደ ተቈጠሩ ወደ ሰልፍ በየቍጥራቸው ይወጡ ነበር።'),
  ('78b3f814-c603-5cb7-a415-ed82d918a180', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 12, 12, 'የአባቶቻቸውም ቤቶች አለቆች በሰልፍ ጽኑዓንና ኀያላን የሆኑ ሁሉ ቍጥራቸው ሁለት ሺህ ስድስት መቶ ነበረ።'),
  ('737d888d-5ef7-54b2-a399-4e98a2fbc591', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 13, 13, 'ከእነርሱም ጋር ወደ ሰልፍ የሚወጡ ሦስት መቶ ሰባት ሺህ አምስት መቶ ሠራዊት ነበሩ፤ እነዚህም ንጉሡን በጠላቱ ላይ የሚያግዙ፥ በታላቅ ኀይል ወደ ሰልፍ የሚወጡ ጽኑዓን ነበሩ።'),
  ('51fa2a0c-e337-5136-a101-830e3f3c0fd8', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 14, 14, 'ዖዝያንም ለጭፍራው ሁሉ ጋሻና ጦር፥ ራስ ቍርና ጥሩር፥ ቀስትና የሚወነጭፉትን ድንጋይ አዘጋጀላቸው።'),
  ('cb575db5-3a88-5fb2-acdf-4f985a099d4a', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 15, 15, 'በኢየሩሳሌምም በብልሃተኞች እጅ የተሠሩትን ፥ በግንብና በቅጥር ላይ የሚኖሩትን፥ ፍላጻና መርግ የሚወረወርባቸውን መሣሪያዎች አደረገ፤ እስኪበረታም ድረስ እግዚአብሔር በድንቅ ረድቶታልና የመሣሪያዎቹ ዝና እስከ ሩቅ ድረስ ተሰማ።'),
  ('f2b51a2c-2b40-54fb-a143-f0b13b226ff9', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 16, 16, 'ነገር ግን በበረታ ጊዜ ለጥፋት ልቡ ታበየ፤ አምላኩንም እግዚአብሔርን በደለ፤ በዕጣን መሠዊያውም ላይ ያጥን ዘንድ ወደ መቅደስ ገባ።'),
  ('d6589c7e-9d6b-5675-a7d2-63f965bfb531', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 17, 17, 'ካህኑም ዓዛርያስ፥ ከእርሱም ጋር ጽኑዓን የነበሩ ሰማንያ የእግዚአብሔር ካህናት ተከትለው ገቡ።'),
  ('4f7985c3-4cbc-5f2f-a1a2-4c89ef129f42', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 18, 18, 'ንጉሡንም ዖዝያንን እየተቃወሙ፥ “ዖዝያን ሆይ፥ ዕጣን ማጠን ለተቀደሱት ለአሮን ልጆች ለካህናቱ ነው እንጂ ለእግዚአብሔር ታጥን ዘንድ ለአንተ አይገባህም፤ ከእግዚአብሔር ርቀሃልና ከመቅደሱ ውጣ፤ ይህም በአምላክ በእግዚአብሔርም ዘንድ ለአንተ ክብር አይሆንህም” አሉት።'),
  ('54d19f7c-b750-5085-a43e-c634c5cc7760', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 19, 19, 'ዖዝያንም ተቈጣ፤ በመቅደስም የሚያጥንበት ጥና በእጁ ነበረ፤ ካህናቱንም በተቈጣ ጊዜ በካህናቱ ፊት በእግዚአብሔር ቤት ውስጥ በዕጣኑ መሠዊያ አጠገብ ሳለ በግንባሩ ላይ ለምጽ ታየ።'),
  ('9eb017f8-77a7-5aa0-a522-b8ce220bb581', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 20, 20, 'ታላቁ ካህን ዓዛርያስ፥ ካህናቱም ሁሉ ተመለከቱት፤ እነሆም፥ በግንባሩ ላይ ለምጽ ነበረ፤ ፈጥነውም አባረሩት፤ እርሱም ደግሞ እግዝአብሔር ቀሥፎት ነበርና ይወጣ ዘንድ ቸኰለ።'),
  ('ac73058e-635a-5892-a053-9e86a0445e83', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 21, 21, 'ንጉሡም ዖዝያን እስኪሞት ድረስ ለምጻም ነበረ፤ ለምጻምም ሆኖ ከእግዚአብሔር ቤት ርቆአልና በተለየ ቤት ይቀመጥ ነበር፤ ልጁም ኢዮአታም በቤተ መንግሥቱ ሆኖ በምድሩ ሕዝብ ላይ ይፈርድ ነበር።'),
  ('6eb3e366-4df2-57c9-a554-2740052cd508', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 22, 22, 'የቀሩትም የፊተኞቹና የኋለኞቹ የዖዝያን ነገሮች በነቢዩ በኢሳይያስ መጽሐፍ ተጽፈዋል።'),
  ('aedd2799-c088-5a60-a40e-2b8cd210d763', 'd8d3f5ef-e3a9-5357-acfe-3aea5dfa7125', 'f1ef1dd3-2926-5405-ab29-c03911ef9c40', 23, 23, 'ዖዝያንም ከአባቶቹ ጋር አንቀላፋ፤ ለምጻም ነው ብለዋልና የነገሥታቱ መቃብር ባልሆነ እርሻ ውስጥ ቀበሩት፤ ልጁም ኢዮአታም በእርሱ ፋንታ ነገሠ።'),
  ('a4cec89d-a620-52f5-af69-2b89800cb2aa', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 1, 1, 'ኢዮአታምም መንገሥ በጀመረ ጊዜ የሃያ አምስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ ስድስት ዓመት ነገሠ፤ እናቱም የሳዶቅ ልጅ ኢየሩሳ ትባል ነበር።'),
  ('eed2f4b8-4185-5a40-a5c4-85286b5353da', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 2, 2, 'አባቱም ዖዝያን እንዳደረገ ሁሉ በእግዚአብሔር ፊት ቅን ነገር አደረገ፤ ነገር ግን ወደ እግዚአብሔር መቅደስ አልገባም፤ ሕዝቡም ገና ይበድል ነበር።'),
  ('cc778b0f-309c-50af-aba7-c25f8ba4954e', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 3, 3, 'የእግዚአብሔርን ቤት የላይኛውን በር ሠራ፤ በዖፌልም ቅጥር ላይ ብዙ ሠራ።'),
  ('8b1c9f26-5021-5af0-a1f5-d72708fff6b5', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 4, 4, 'በተራራማውም በይሁዳ ሀገር ላይ ከተሞችን ሠራ፤ በዱር ስፍራዎችም አምባዎችንና ግንቦችን ሠራ።'),
  ('09d032b1-b2d1-59f9-acb8-d1a16ba1ead9', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 5, 5, 'ከአሞንም ልጆች ንጉሥ ጋር ተዋጋ፤ አሸነፋቸውም። በዚያም ዓመት የአሞን ልጆች መቶ መክሊት ብር፥ ዐሥር ሺህም የቆሮስ መስፈሪያ ስንዴ፥ ዐሥር ሺህም የቆሮስ መስፈሪያ ገብስ ግብር ሰጡት። እንዲሁም ደግሞ የአሞን ልጆችና ንጉሣቸው በመጀመሪያው፥ በሁለተኛውና በሦስተኛው ዓመት ሰጡት።'),
  ('b9a53e50-3997-5e9d-aaf7-3b3507751f61', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 6, 6, 'ኢዮአታምም በአምላኩ በእግዚአብሔር ፊት መንገዱን አቅንቶአልና በረታ።'),
  ('a5311c31-37eb-52e3-a59d-8ad34c79ad57', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 7, 7, 'የቀሩትም የኢዮአታም ነገሮች፥ ሰልፉም ሁሉ፥ ሥራውም፥ እነሆ፥ በእስራኤልና በይሁዳ ነገሥታት መጽሐፍ ተጽፎአል።'),
  ('dd6ca53b-6175-563f-a051-7a3bb60f62d5', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 8, 8, 'መንገሥም በጀመረ ጊዜ የሃያ አምስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ ስድስት ዓመት ነገሠ።'),
  ('b97a6ee1-0ee7-50a2-a29c-a0983dc06895', '6265abe5-827b-5055-a29d-3e53d1688646', 'a41a6796-eda6-50ce-ab77-0e025f9945ab', 9, 9, 'ኢዮአታምም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ቀበሩት፤ ልጁም አካዝ በእርሱ ፋንታ ነገሠ።'),
  ('d5a6495a-f18c-567d-a019-474ec70ff954', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 1, 1, 'አካዝም መንገሥ በጀመረ ጊዜ የሃያ ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ ስድስት ዓመት ነገሠ፤ እንደ አባቱም እንደ ዳዊት በእግዚአብሔር ፊት ቅን ነገር አላደረገም።'),
  ('7b16b03b-b1d8-5d6b-a312-6a4b0310fdc6', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 2, 2, 'ነገር ግን በእስራኤል ነገሥታት መንገድ ሄደ፤ ደግሞም ቀልጠው የተሠሩትን ምስሎች ሠራ።'),
  ('beb2acda-c17a-5197-af22-24e7624059ed', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 3, 3, 'ደግሞም በሄኖም ልጅ ሸለቆ ውስጥ ለምስሉ ሠዋ፤ እግዚአብሔር ከእስራኤል ልጆች ፊት እንዳሳደዳቸው እንደ አሕዛብም ክፉ ልማድ ልጆቹን በእሳት አቃጠለ።'),
  ('dc0f9853-274a-5c63-a2b8-b903344f9900', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 4, 4, 'በኮረብታው መስገጃዎችና በተራሮች ላይ በለመለመውም ዛፍ ሁሉ በታች ያጥን ነበር።'),
  ('f548eb3f-6a12-5804-a072-6689d4ae9e42', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 5, 5, 'ስለዚህ አምላኩ እግዚአብሔር በሶርያ ንጉሥ እጅ አሳልፎ ሰጠው፤ እርሱም መታው፤ ከእርሱም ብዙ ምርኮኞችን ወሰደ፤ ወደ ደማስቆም አመጣው። ደግሞም በእስራኤል ንጉሥ እጅ አሳልፎ ሰጠው፤ እርሱም በታላቅ አመታት መታው።'),
  ('3cbc0c83-aa10-5025-a9c9-32dce15b3978', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 6, 6, 'የአባቶቻቸውንም አምላክ እግዚአብሔርን ትተው ነበርና የእስራኤል ንጉሥ የሮሜልዩ ልጅ ፋቁሔ በአንድ ቀን ከይሁዳ ጽኑዓን የነበሩ መቶ ሃያ ሺህ ሰልፈኞችን ገደለ፤'),
  ('619f7a87-b1d9-54bf-ae70-139ea5769124', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 7, 7, 'ከኤፍሬም ወገን የነበረው ኀያል ሰው ዝክሪም የንጉሡን ልጅ ማዓሥያንና የቤቱን አዛዥ ዓዝሪቃምን፥ ለንጉሡም በማዕርግ ሁለተኛ የሆነውን ሕልቃናን ገደለ።'),
  ('444177cf-b627-5da5-a7ed-f4ab8c0e4f11', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 8, 8, 'የእስራኤል ልጆች ከወንድሞቻቸው ሦስት መቶ ሺህ ሴቶችን፥ ወንዶችና ሴቶች ልጆችንም ማረኩ፤ እጅግም ምርኮ ከእነርሱ ወስደው ወደ ሰማርያ አገቡ።'),
  ('e4c34d3f-5cf9-58be-a91e-3818da99494c', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 9, 9, 'በዚያም ዖዴድ የተባለ የእግዚአብሔር ነቢይ ነበረ፤ ወደ ሰማርያም የሚመጣውን ጭፍራ ሊገናኘው ወጣ፤ እንዲህም አላቸው፤ “እነሆ፥ የአባቶቻችሁ አምላክ እግዚአብሔር ይሁዳን ስለ ተቈጣ በእጃችሁ አሳልፎ ሰጣቸው፤ እናንተም ወደ ሰማይ በሚደርስ ቍጣ ገደላችኋቸው።'),
  ('9cd65de0-8673-567e-a0af-60f4ace3bbff', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 10, 10, 'አሁንም የይሁዳንና የኢየሩሳሌምን ልጆች ባሪያዎች አድርገን እንግዛ ትላላችሁ፤ የፈጣሪያችሁ የእግዚአብሔር ምስክር የምሆን እኔም ከእናንተ ጋር ያለሁ አይደለምን?'),
  ('569e50b2-808c-5bf9-a580-b1d9280d348d', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 11, 11, 'አሁንም ስሙ፤ የእግዚአብሔር ቍጣ በላያችሁ ነድዶአልና ከወንድሞቻችሁ የወሰዳችኋቸውን ምርኮኞች መልሱ።”'),
  ('ddd3e9e4-6d5b-5d08-a83e-eb9861211869', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 12, 12, 'ደግሞም ከኤፍሬም ልጆች አለቆች የአናን ልጅ ዓዛርያስ፥ የመስለሞት ልጅ በራክያ፥ የሳሎም ልጅ ሕዝቅያስ፥ የአዳሊ ልጅ አማስያ ከሰልፍ የተመለሱትን ተቃወሙአቸው።'),
  ('f64d8c82-205e-590b-ab0d-3c0d9a1cad17', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 13, 13, '“ደግሞም በእግዚአብሔር ፊት በእኛ ላይ በደል ታመጡብናላችሁና፥ ኀጢአታችንንና በደላችንን ታበዙብናላችሁና የተማረኩትን ወደዚህ አታግቡ፤ በደላችን ታላቅ ነውና፥ የእግዚአብሔርም የመቅሠፍቱ ቍጣ በእስራኤል ላይ ነውና” አሉአቸው።'),
  ('bc344d28-fc0e-5940-ad25-f528902628c5', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 14, 14, 'ሰልፈኞቹም ምርኮኞቹንና ምርኮውን በአለቆችና በጉባኤ ሁሉ ፊት ተዉ።'),
  ('7ec27d5a-2708-5641-aef7-db10558e8c79', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', 'a437ad22-42e5-50ae-abfb-d438e4613830', 15, 15, 'በስማቸውም የተጻፉ ሰዎች ተነሥተው ምርኮኞቹን ወሰዱ፤ በመካከላቸውም ራቁታቸውን ለነበሩት ሁሉ ከምርኮው አለበሱአቸው፤ አጐናጸፉአቸውም፤ ጫማም በእግራቸው አደረጉላቸው፤ መገቡአቸውም፤ አጠጡአቸውም፤ ቀቡአቸውም፤ ደካሞቹንም ሁሉ በአህዮች ላይ አስቀመጡአቸው፤ ዘንባባም ወዳለበት ከተማ ወደ ኢያሪኮ ወደ ወንድሞቻቸው አመጡአቸው፤ ወደ ሰማርያም ተመለሱ።'),
  ('dfeadd77-8f60-561c-ade5-51bab3954911', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 1, 16, 'በዚያም ጊዜ ንጉሡ አካዝ ርዳታ ፈልጎ ወደ አሦር ንጉሥ ላከ፤'),
  ('d60eb354-5ae9-5894-ade6-2f06e0779c65', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 2, 17, 'የኤዶምያስ ሰዎች ዳግመኛ መጥተው፥ ይሁዳንም መትተው ብዙ ምርኮኛ ወስደው ነበርና።'),
  ('b97c2da0-c3df-5b1f-a0dd-6dce5c79bdc3', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 3, 18, 'ደግሞም ፍልስጥኤማውያን በቆላውና በደቡብ በኩል ባሉት በይሁዳ ከተሞች አደጋ ጥለው ነበር፤ ቤትሳሚስንና ኤሎንን፥ ጋቤሮትንም፥ ሠካዕንና መንደሮችዋን፥ ቴምናንና መንደሮችዋንም፥ ጋማዚእንና መንደሮችዋን ወስደው በዚያ ተቀምጠው ነበር።'),
  ('42db0d66-5ff6-5221-a069-e475e22e86e7', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 4, 19, 'በይሁዳም ንጉሥ በአካዝ ምክንያት እግዚአብሔር ይሁዳን አዋረደው፤ እርሱ ከእግዚአብሔር እጅግ ርቆአልና።'),
  ('9b1a916a-274a-59be-ac25-45b2b431a882', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 5, 20, 'የአሦርም ንጉሥ ቴልጌልቴልፌልሶር መጥቶ አስጨነቀው።'),
  ('6ed7148c-97f0-5bf6-a6f0-30f2b955a025', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 6, 21, 'አካዝም ከእግዚአብሔር ቤት ከንጉሡና ከአለቆቹም ቤት የነበረውን ሁሉ ወሰደ፤ ለአሦርም ንጉሥ ሰጠ፥ ነገር ግን አስጨነቀው እንጂ አልረዳውም።'),
  ('8ecd93fc-df1f-5a92-af66-24ca2ce3bb9a', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 7, 22, 'ዳግመኛም ንጉሡ አካዝ ፈጽሞ ከእግዚአብሔር ራቀ።'),
  ('79b5b2a6-607a-5f10-a27b-ce13ae30a306', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 8, 23, 'ንጉሡም፥ “የመቱኝን የደማስቆን አማልክት እፈልጋቸዋለሁ፤ የሶርያን ንጉሥ እርሱን ረድተውታልና እኔንም ይረዱኝ ዘንድ እሠዋላቸዋለሁ” አለ። ነገር ግን ለእርሱና ለእስራኤል ሁሉ ዕንቅፋት ሆኑ።'),
  ('233078a1-0c29-5777-aab5-4203dedbb5ac', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 9, 24, 'አካዝም የእግዚአብሔርን ቤት ዕቃዎች ሁሉ ወስዶ ሰባበራቸው፤ የእግዚአብሔርንም ቤት ደጆች ዘጋ፤ በኢየሩሳሌምም ማዕዘን ሁሉ ለራሱ መሠዊያ ሠራ።'),
  ('2d7d1147-d986-5e19-af5c-ce8cbc4a320a', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 10, 25, 'በይሁዳም ከተሞች ሁሉ ለሌሎች አማልክት ያጥን ዘንድ የኮረብታ መስገጃዎችን አሠራ፤ የአባቶቻቸውንም አምላክ እግዚአብሔርን አስቈጣ።'),
  ('a6c6c79b-b614-5377-abae-acf83f481bcf', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 11, 26, 'የቀሩትም ነገሮቹና ሥራው ሁሉ፥ የፊተኞቹና የኋለኞቹ እነሆ፥ በይሁዳና በእስራኤል ነገሥታት መጽሐፍ ተጽፈዋል።'),
  ('bf7becb7-16c7-5a76-a1ef-3283603ffb72', '722f49e5-b9d0-5a4e-ae02-87d16a961cf0', '40682240-a8d8-5dca-a5c4-0989133fe861', 12, 27, 'አካዝም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ቀበሩት፤ ነገር ግን ወደ እስራኤል ነገሥታት መቃብር አላገቡትም፤ ልጁም ሕዝቅያስ በእርሱ ፋንታ ነገሠ።'),
  ('eb84cf5b-2d9c-58ef-a1c2-f0a252e2d818', '36320144-c18a-529f-a816-cc971ef7ad67', '93200853-e0b1-52c9-a89d-7907f096a7b3', 1, 1, 'ሕዝቅያስም የሃያ አምስት ዓመት ጐልማሳ በነበረ ጊዜ መንገሥ ጀመረ፤ በኢየሩሳሌምም ሃያ ዘጠኝ ዓመት ነገሠ፤ እናቱም የዘካርያስ ልጅ አብያ ትባል ነበር።'),
  ('01773977-b8db-5a74-a1dd-abaf7b9b66f4', '36320144-c18a-529f-a816-cc971ef7ad67', '93200853-e0b1-52c9-a89d-7907f096a7b3', 2, 2, 'አባቱም ዳዊት እንዳደረገ ሁሉ በእግዚአብሔር ፊት ቅን ነገርን አደረገ።'),
  ('3685ffd6-5140-576a-aefb-7bea6ce5490e', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 1, 3, 'በመንግሥቱም በጸና ጊዜ በመጀመሪያው ወር የእግዚአብሔርን ቤት ደጆች ከፈተ፤ አደሳቸውም።'),
  ('e42573b8-ac63-510c-aee0-d438820b4f3e', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 2, 4, 'ካህናቱንና ሌዋውያኑንም አስመጣ፤ በምሥራቅ በኩል ባለው አደባባይም ሰበሰባቸው፤'),
  ('eeb864ae-2af0-5be6-a802-3395468b305c', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 3, 5, 'እንዲህም አላቸው፥ “ሌዋውያን ሆይ፥ ስሙኝ፤ ራሳችሁን አንጹ፤ የአባቶቻችሁንም አምላክ የእግዚአብሔርን ቤት ቀድሱ፤ ርኩስን ነገር ሁሉ ከመቅደሱ አስወግዱ።'),
  ('9a0359df-726a-56d5-a880-aefd5c759ec8', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 4, 6, 'አባቶቻችን ከእግዚአብሔር ርቀዋል፤ በአምላካችንም በእግዚአብሔር ፊት ክፉ አድርገዋል፤ እርሱንም ረስተዋል፤ ፊታቸውንም ከእግዚአብሔር ቤት መልሰዋል፤ ጀርባቸውንም አዙረዋል፤'),
  ('a7603953-7ddc-575e-ae91-1dd744ce7bd3', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 5, 7, 'ደግሞም የእግዚአብሔርን ቤት ደጆች ዘግተዋል፤ መብራቶቹንም አጥፍተዋል፤ በመቅደሱም ውስጥ ለእስራኤል አምላክ አላጠኑም፤ የሚቃጠለውንም መሥዋዕት አላቀረቡም።'),
  ('cb9afa99-7c06-537f-a167-94b96474832c', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 6, 8, '“ስለዚህም የእግዚአብሔር ቍጣ በይሁዳና በኢየሩሳሌም ላይ ሆነ፤ በዐይናችሁም እንደምታዩ ለድንጋጤና ለመደነቂያ፥ ለመዘበቻም አሳልፎ ሰጣቸው።'),
  ('d08b00f2-a616-5513-a3f6-853cb3fd6549', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 7, 9, 'እነሆም፥ ስለዚህ አባቶቻችሁ በሰይፍ ወደቁ፤ ወንዶችና ሴቶች ልጆቻችሁም፥ ሚስቶቻችሁም የእነርሱ ሀገር ወዳልሆነ ተማረኩ፤ እስከ ዛሬም በዚያ ይኖራሉ።'),
  ('42c583e6-bd29-5785-ac47-90aeae07aa8d', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 8, 10, 'አሁንም የቍጣውን መቅሠፍት ከእኛ እንዲመልስ ከእስራኤል አምላክ ከእግዚአብሔር ጋር ቃል ኪዳን አደርግ ዘንድ በልቤ አስቤአለሁ።'),
  ('1d4262ee-40db-50c8-a5e5-f01649f90f1e', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 9, 11, 'አሁንም በፊቱ ትቆሙና ታገለግሉት ዘንድ፥ አገልጋዮቹም ትሆኑ ዘንድ፥ ታጥኑለትም ዘንድ እግዚአብሔር መርጦአችኋልና ቸል አትበሉ።”'),
  ('fdd884a8-04b5-5b4f-a4ff-c142fcc8fda0', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 10, 12, 'ሌዋውያኑም፥ ከቀዓት ልጆች የአሜሳእ ልጅ መኤትና የዓዛርያስ ልጅ ኢዮሔል፥ ከሜራሪም ልጆች የአብዲ ልጅ ቂስና የያሃሌልኤል ልጅ ዓዛርያስ፥ ከጌድሶንም ልጆች የዛማት ልጅ ዮአክና የዮአክ ልጅ ኢዮአድ፤'),
  ('a1f20f17-0243-582e-a9da-7ec1054390b4', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 11, 13, 'ከኤልሳፋንም ልጆች ሳምሪና ኢዮሔል፥ ከአሳፍም ልጆች ዘካርያስና ማታንያስ፤'),
  ('9393829c-2c41-566e-ae67-27f951e37c23', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 12, 14, 'ከኤማንም ልጆች ኢዮሔልና ሰሜኢ፥ ከኢዱቱንም ልጆች ሰማዕያና ኡዝሔል ተነሡ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d29f18a5-1a47-5ca6-a735-2effb82eb872', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 13, 15, 'ወንድሞቻቸውንም ሰብስበው በእግዚአብሔር ቃል እንደ ንጉሡ ትእዛዝ የእግዚአብሔርን ቤት ያነጹ ዘንድ ራሳቸውን አነጹ።'),
  ('2a7b69a5-17ed-5d6c-ab62-773cfb40f552', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 14, 16, 'ካህናቱም ያነጹት ዘንድ ወደ እግዚአብሔር ቤት ወደ ውስጥ ገቡ፤ በእግዚአብሔርም መቅደስ ያገኙትን ርኩስ ነገር ሁሉ ወደ እግዚአብሔር ቤት አደባባይ አወጡት። ሌዋውያንም ወስደው ወደ ሜዳ ወደ ቄድሮን ወንዝ ጣሉት።'),
  ('4f0fa5df-6578-5596-ad84-ea7a1873caae', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 15, 17, 'በመጀመሪያውም ወር በመጀመሪያው ቀን ያነጹ ጀመር፤ በዚያውም ወር በስምንተኛው ቀን ወደ እግዚአብሔር ቤት ወለል ደረሱ፤ የእግዚአብሔርንም ቤት በስምንት ቀን አነጹ፤ በመጀመሪያውም ወር በዐሥራ ስድስተኛው ቀን ፈጸሙ።'),
  ('3a9cfef5-f7e1-556e-ad60-d08a96a574ab', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 16, 18, 'ወደ ውስጡም ወደ ንጉሡ ወደ ሕዝቅያስ ገብተው፥ “የእግዚአብሔርን ቤት ሁሉ፥ ለሚቃጠል መሥዋዕት የሚሆነውን መሠዊያና ዕቃውንም ሁሉ፥ የኅብስተ ገጹንም ገበታና ዕቃውን ሁሉ አንጽተናል፤'),
  ('f15fceb7-a897-5e46-af51-e8cf7788f9b5', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 17, 19, 'ንጉሡም አካዝ ነግሦ ሳለ በመተላለፉ ያረከሰውን ዕቃ ሁሉ አዘጋጅተናል፤ ቀድሰናልም፤ እነሆም፥ በእግዚአብሔር መሠዊያ ፊት ሆነዋል” አሉት።'),
  ('41f71852-0741-5871-a1d0-c2777e9deb3e', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 18, 20, 'ንጉሡም ሕዝቅያስ ማልዶ ተነሣ፤ የእስራኤልንም ቤት አለቆች ሰበሰበ፤ ወደ እግዚአብሔርም ቤት ወጣ።'),
  ('571964c2-526c-54d6-aefd-565c0bc5f128', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 19, 21, 'ስለ መንግሥቱና ስለ መቅደሱም፥ ስለ ሕዝቡም ስለ እስራኤል ለኀጢአት መሥዋዕት ሰባት ወይፈኖች፥ ሰባትም አውራ በጎች፥ ሰባትም የበግ ጠቦቶች፥ ሰባትም አውራ ፍየሎች አመጡ። የአሮንንም ልጆች ካህናቱን፥ “ወደ እግዚአብሔር መሠዊያ ውጡ” አላቸው።'),
  ('e8f9d37f-1bc6-5155-a7f8-b659de5b1ea6', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 20, 22, 'ወይፈኖቹንም አረዱ፤ ካህናቱም ደሙን ተቀብለው በመሠዊያው ላይ ረጩት፤ አውራ በጎቹንም አረዱ፤ ደሙንም በመሠዊያው ላይ ረጩት፤ ጠቦቶቹንም አረዱ፤ ደሙንም በመሠዊያው ላይ ረጩት።'),
  ('88bd0c2a-c0ec-5a5b-a3ef-00f3137c0545', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 21, 23, 'የኀጢአት መሥዋዕት የሚሆኑትንም አውራ ፍየሎች በንጉሡና በጉባኤው ፊት አቀረቡ፤ እጃቸውንም ጫኑባቸው፤'),
  ('fd56312b-7030-5e04-aa4b-16a8b0177e3b', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 22, 24, 'ካህናቱም አረዱአቸው፤ ንጉሡም የሚቃጠል መሥዋዕትና የኀጢአት መሥዋዕት ለእስራኤል ሁሉ እንዲደረግ አዝዞ ነበርና ለእስራኤል ሁሉ ማስተስረያ ያደርጉ ዘንድ ደማቸውን በመሠዊያው ላይ አቀረቡ።'),
  ('9ac18753-5156-5948-a068-23595cb767b1', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 23, 25, 'ይህንም ትእዛዝ እግዚአብሔር በነቢያቱ እጅ አዝዞአልና እንደ ዳዊትና እንደ ንጉሡ ባለ ራእይ እንደ ጋድ፥ እንደ ነቢዩም እንደ ናታን ትእዛዝ፥ ጸናጽልና በገና፥ መሰንቆም አስይዞ ሌዋውያንን በእግዚአብሔር ፊት አቆመ።'),
  ('2aca16d4-0b30-579c-ae0d-c20946020fc2', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 24, 26, 'ሌዋውያንም የዳዊትን የዜማ ዕቃ ይዘው፥ ካህናቱም መለከቱን ይዘው ቆመው ነበር።'),
  ('98af187f-58c4-5eab-a252-149fd56d9929', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 25, 27, 'ሕዝቅያስም፥ “የሚቃጠለውን መሥዋዕት በመሠዊያው ላይ አሳርጉ” አለ፤ የሚቃጠለውንም መሥዋዕት ማሳረግ በተጀመረ ጊዜ የእግዚአብሔር መዝሙር ደግሞ ተጀመረ፤ መለከቱም ተነፋ፤ የእስራኤልም ንጉሥ የዳዊት ዜማ ዕቃ ተመታ።'),
  ('8f09d1d2-b2b0-5981-a00a-262b33063086', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 26, 28, 'የሚቃጠለውም መሥዋዕት እስኪፈጸም ድረስ ጉባኤው ሁሉ ይሰግዱ ነበር፤ መዘምራኑም ይዘምሩ ነበር፤ መለከተኞችም ይነፉ ነበር።'),
  ('37d4be24-2149-5fc6-ac7d-1718eae97de9', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 27, 29, 'ማቅረቡንም በፈጸሙ ጊዜ ንጉሡ፥ ከእርሱም ጋር የነበሩ ሁሉ አጐነበሱ፤ ሰገዱም።'),
  ('4f33726e-0129-526a-a0cb-f3aa3c582906', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 28, 30, 'ንጉሡ ሕዝቅያስና አለቆቹም በዳዊትና በነቢዩ በአሳፍ ቃል እግዚአብሔርን ያመሰግኑ ዘንድ ሌዋውያንን አዘዙ። በደስታም አመሰገኑ፤ አጐነበሱም፤ ሰገዱም።'),
  ('8cbbad54-2431-5d39-abf8-8795c6650e2d', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 29, 31, 'ሕዝቅያስም፥ “አሁን እጃችሁን ለእግዚአብሔር አንጽታችሁ ቅረቡ፤ መሥዋዕቱንና የምስጋናውን መሥዋዕት ወደ እግዚአብሔር ቤት አምጡ” ብሎ ተናገረ። ጉባኤውም መሥዋዕቱንና የምስጋናውን መሥዋዕት ወደ እግዚአብሔር ቤት አመጡ፤ ልባቸውም የፈቀደ ሁሉ የሚቃጠለውን መሥዋዕት አመጡ።'),
  ('9a2f8dfb-fb3f-545f-af14-7245d12a5849', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 30, 32, 'ጉባኤውም ያመጡት የሚቃጠል መሥዋዕት ቍጥር ሰባ ወይፈን፥ መቶም አውራ በጎች፥ ሁለት መቶም የበግ ጠቦቶች ነበረ፤ ይህ ሁሉ ለእግዚአብሔር የሚቃጠል መሥዋዕት ነበረ።'),
  ('1409e198-4f5d-57d7-a896-cee920bf8457', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 31, 33, 'የተቀደሱትም ቍጥር ስድስት መቶ በሬዎች፥ ሦስት ሺህም በጎች ነበረ።'),
  ('7c24b5c8-748d-5ae1-adc8-b120e0935f51', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 32, 34, 'ነገር ግን ካህናቱ ጥቂቶች ነበሩና የሚቃጠለውን መሥዋዕት ለመግፈፍ አይችሉም ነበር፤ ስለዚህም ሌዋውያን በቅን ልብ ከካህናት ይልቅ ይቀደሱ ነበርና ሥራው እስኪፈጸም ድረስ፥ ካህናቱም እስኪቀደሱ ድረስ ወንድሞቻቸው ሌዋውያን ያግዙአቸው ነበር።'),
  ('06abdbb7-e6eb-5eec-a54b-4067638422f4', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 33, 35, 'የሚቃጠለውም መሥዋዕት ከደኅንነቱ መሥዋዕት ስብና ለሚቃጠለውም መሥዋዕት ከሚቀርበው የመጠጥ ቍርባን ጋር ብዙ ነበረ። እንዲሁም የእግዚአብሔር ቤት አገልግሎት ተዘጋጀ።'),
  ('a8bc25e2-80d4-5b4d-a0ac-61bbb56996b1', '36320144-c18a-529f-a816-cc971ef7ad67', 'e061e8a7-9bcb-58cf-af33-75d1bd185110', 34, 36, 'ሕዝቅያስና ሕዝቡም ሁሉ እግዚአብሔር ለሕዝቡ ስላዘጋጀው ነገር ደስ አላቸው። ይህ ነገር በድንገት ተደርጎአልና።'),
  ('be468d4f-6bd9-56c4-a838-ba4c278e8355', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 1, 1, 'ለእስራኤልም አምላክ ለእግዚአብሔር ፋሲካ ያደርጉ ዘንድ ወደ እግዚአብሔር ቤት ወደ ኢየሩሳሌም እንዲመጡ ሕዝቅያስ ወደ እስራኤልና ወደ ይሁዳ ሁሉ ላከ፤ ደግሞም ወደ ኤፍሬምና ወደ ምናሴ ደብዳቤዎችን ጻፈ።'),
  ('f48ed717-0b63-5ba1-a132-b6f74936504c', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 2, 2, 'ንጉሡና አለቆቹ በኢየሩሳሌምም ያለ የእስራኤል ጉባኤ ሁሉ በሁለተኛው ወር ፋሲካውን ያደርጉ ዘንድ ተማከሩ።'),
  ('36948cb0-2dc8-5077-a905-49504b9a2c6e', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 3, 3, 'ካህናቱ በሚበቃ ቍጥር ስላልተቀደሱ፥ ሕዝቡም ገና በኢየሩሳሌም ስላልተሰበሰቡ በጊዜው ያደርጉት ዘንድ አልቻሉም ነበርና።'),
  ('0d2e1777-e42d-5619-a1a7-8d4a29adc143', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 4, 4, 'ነገሩም ንጉሡንና ጉባኤውን ሁሉ ደስ የሚያሰኝ ሆነ።'),
  ('ed8f47bf-fc34-52c1-a355-edce5f2798ea', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 5, 5, 'እንደ ተጻፈም ብዙዎቹ አላደረጉትም ነበርና የእስራኤልን አምላክ የእግዚአብሔርን ፋሲካ በኢየሩሳሌም ያደርጉ ዘንድ እንዲመጡ ከቤርሳቤህ ጀምሮ እስከ ዳን ድረስ ለእስራኤል ሁሉ አዋጅ እንዲነገር ወሰኑ።'),
  ('889e2c35-6b55-5fa8-a706-8425d9c24ee2', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 6, 6, 'እንደ ንጉሡም ትእዛዝ መልእክተኞቹ እንዲህ የሚለውን የንጉሡንና የአለቆቹን ደብዳቤ ይዘው ወደ እስራኤልና ወደ ይሁዳ ሁሉ ፈጥነው ሄዱ፥ “የእስራኤል ልጆች ሆይ፥ እግዚአብሔር ከአሦር ንጉሥ እጅ ወዳመለጠ ቅሬታችሁ እንዲመለስ ወደ አብርሃምና ወደ ይስሐቅ ወደ ያዕቆብም አምላክ ወደ እግዚአብሔር ተመለሱ።'),
  ('c3c23762-6848-5cf3-a90a-09a3a68ff166', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 7, 7, 'እናንተም እንደምታዩ የአባቶቻቸውን አምላክ እግዚአብሔርን እንደ በደሉ፥ ለጥፋትም እንደ ሰጣቸው እንደ አባቶቻችሁና እንደ ወንድሞቻችሁ አትሁኑ።'),
  ('f20ba969-e2c5-53d8-a2a4-660e0fd5915e', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 8, 8, 'አሁንም እንደ አባቶቻችሁ አንገታችሁን አታደንድኑ፤ ለአምላካችሁ ለእግዚአብሔር ምስጋና ስጡ፤ ለዘለዓለምም ወደ ተቀደሰው ወደ መቅደሱ ግቡ፤ ጽኑ ቍጣውንም ከእናንተ እንዲመልስ ለአምላካችሁ ለእግዚአብሔር ተገዙ።'),
  ('2efe9586-b0b1-59ae-a084-1c6a89c65687', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 9, 9, 'አምላካችሁ እግዚአብሔር ቸርና መሓሪ ነውና፥ ወደ እርሱም ብንመለስ ፊቱን ከእኛ አያዞርምና ወደ እግዚአብሔር ብትመለሱ ወንድሞቻችሁና ልጆቻችሁ በማረኩአቸው ፊት ምሕረትን ያገኛሉ፤ ደግሞም ወደዚህች ምድር ይመልሳቸዋል።”'),
  ('d3a4d09a-f663-5d65-acb4-9d7256d7f143', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 10, 10, 'መልእክተኞቹም ከከተማ ወደ ከተማ በኤፍሬምና በምናሴ ሀገር እስከ ዛብሎን ሄዱ፤ እነዚያ ግን በንቀት ሳቁባቸው፤ አፌዙባቸውም።'),
  ('994a6105-31f3-5551-aeda-f6f5f9de7fc8', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 11, 11, 'ነገር ግን ከአሴርና ከምናሴ፥ ከዛብሎንም አያሌ ሰዎች ሰውነታቸውን አዋረዱ፤ ወደ ኢየሩሳሌምም መጡ።'),
  ('ddc9a035-3e10-5fba-a7dd-18e924053f67', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 12, 12, 'ደግሞም አንድ ልብ ይሰጣቸው ዘንድ፥ በእግዚአብሔርም ቃል የሆነውን የንጉሡንና የአለቆቹን ትእዛዝ ያደርጉ ዘንድ የእግዚአብሔር እጅ በእነርሱ ላይ ሆነ።'),
  ('465c9f7e-0adc-5075-a442-3cdbf5e9ca50', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 13, 13, 'በሁለተኛውም ወር የቂጣውን በዓል ያደርጉ ዘንድ በኢየሩሳሌም ብዙ ሕዝብ ተሰበሰቡ፤ እጅግም ታላቅ ጉባኤ ነበረ።'),
  ('34152c80-596a-589d-ab0a-ff97256c0c50', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 14, 14, 'ተነሥተውም በኢየሩሳሌም የነበሩትን መሠዊያዎችና ለጣዖታት የሚያጥኑበትን ዕቃ ሁሉ አስወገዱ፤ በቄድሮንም ወንዝ ጣሉት።'),
  ('28383116-d753-5d95-a07e-95b9448777ec', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 15, 15, 'በሁለተኛውም ወር በዐሥራ አራተኛው ቀን የፋሲካውን በግ አረዱ፤ ካህናቱና ሌዋውያኑም ተዘጋጁ ነጹም። ወደ እግዚአብሔርም ቤት የሚቃጠል መሥዋዕት አመጡ።'),
  ('18a848bb-71f8-5149-a2ab-cd936732ff7c', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 16, 16, 'እንደ እግዚአብሔርም ሰው እንደ ሙሴ ሕግ በቦታቸውና በሥርዐታቸው ቆሙ፤ ካህናቱም ከሌዋውያን እጅ የተቀበሉትን ደም ይረጩ ነበር።'),
  ('06fd1b95-58eb-5842-a3e8-7b98e516da29', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 17, 17, 'በጉባኤውም ያልነጹ ብዙ ሰዎች ነበሩ፤ ስለዚህም ሌዋውያን ለእግዚአብሔር ራሳቸውን ላላነጹት ሁሉ የፋሲካውን በግ ያርዱላቸው ነበር።'),
  ('0bcda006-3bf0-5eaa-abdb-648791c15e71', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 18, 18, 'እንደ ትእዛዙም ሳይሆን ከኤፍሬምና ከምናሴ፥ ከይሳኮርና ከዛብሎንም ወገን እጅግ ሰዎች ሳይነጹ ፋሲካውን በሉ።'),
  ('44e90853-f36f-52d5-a4bb-ef79d311eeed', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 19, 19, 'ሕዝቅያስም ስለ እነርሱ እንዲህ ሲል ጸለየ፥ “ምንም እንደ መቅደሱ ማንጻት ባይነጻ የአባቶቻቸውን አምላክ እግዚአብሔርን ለመፈለግ ልቡን የሚያቀናውን ሁሉ ቸሩ እግዚአብሔር ይቅር ይበለው።”'),
  ('89ae452c-0e71-506c-a358-f8f6b340008e', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 20, 20, 'እግዚአብሔርም ሕዝቅያስን ሰማው፤ ሕዝቡንም አዳናቸው።'),
  ('5471e5c7-1fec-5b53-aa21-7b780731da61', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 21, 21, 'በኢየሩሳሌምም ተገኝተው የነበሩ የእስራኤል ልጆች በየቀኑ እግዚአብሔርን እያመሰገኑ የቂጣውን በዓል በታላቅ ደስታ ሰባት ቀን አደረጉ፤ ሌዋውያኑና ካህናቱም በዜማ ዕቃ እግዚአብሔርን ያመሰግኑ ነበር።'),
  ('0d2fb9b8-3021-5f29-af69-f540aca1b9c6', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 22, 22, 'ሕዝቅያስም በእግዚአብሔር አገልግሎት አስተዋዮች የነበሩትን ሌዋውያንን ሁሉ ያጽናና ነበር። የደኅንነትም መሥዋዕት እያቀረቡ፥ የአባቶቻቸውንም አምላክ እያመሰገኑ ሰባት ቀን በዓል አደረጉ።'),
  ('03bb12d5-ab30-52d7-a0f6-5c4b10f8d92a', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 23, 23, 'ጉባኤው ሁሉ እንደ ገና ሰባት ቀን በዓል ያደርጉ ዘንድ ተማከሩ፤ በደስታም እንደ ገና ሰባት ቀን በዓል አደረጉ።'),
  ('db747878-f32d-5eb9-ae01-c90d71a5d2a6', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 24, 24, 'ንጉሡ ሕዝቅያስም ስለ ቍርባን ሺህ ወይፈኖችንና ሰባት ሺህ በጎችን ለይሁዳና ለጉባኤው ሰጥቶ ነበር፤ አለቆቹም ሺህ ወይፈኖችንና ዐሥር ሺህ በጎችን ለጉባኤው ሰጥተው ነበር፤ ከካህናቱ እጅግ ብዙ ተቀድሰው ነበርና።'),
  ('4ac97383-4134-59fc-a17c-15b096f3c88f', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 25, 25, 'የይሁዳም ጉባኤ ሁሉ ፥ ካህናቱና ሌዋውያኑ፥ ከእስራኤልም የመጡ ጉባኤ ሁሉ፥ ከእስራኤልም ሀገር የመጡትና በይሁዳ የኖሩት እንግዶች ደስ አላቸው።'),
  ('7a5f4711-6e6c-5c9f-af7a-ce8be38a225c', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 26, 26, 'በኢየሩሳሌምም ታላቅ ደስታ ሆነ፤ ከእስራኤል ንጉሥ ከዳዊት ልጅ ከንጉሥ ሰሎሞን ዘመን ጀምሮ እንደዚህ ያለ በዓል በኢየሩሳሌም አልተደረገም ነበር።'),
  ('a5c03421-2ed6-5e7e-a0a7-2199c8a5e8d4', 'ca3dd8a1-b61c-5e6b-a57d-d7577d058216', '1d5c2490-ea38-5dec-ac1b-824580d9754f', 27, 27, 'ካህናቱና ሌዋውያኑም ተነሥተው ሕዝቡን ባረኩ፤ ድምፃቸውም ተሰማ፥ ጸሎታቸውም ወደ ቅዱስ ማደሪያው ወደ ሰማይ ዐረገ።'),
  ('1a394559-894f-59a6-a052-d96a1de04e23', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 1, 1, 'ይህም ሁሉ በተፈጸመ ጊዜ በይሁዳ ከተሞች የተገኙ እስራኤል ሁሉ ወጥተው ዐምዶቹን ሰበሩ፤ ዐፀዶችንም ኮረብታዎችንም አፈረሱ፤ መሠዊያውንም አጠፉ። በይሁዳና በብንያምም ሁሉ ደግሞም በኤፍሬምና በምናሴ የነበሩትን ፈጽመው እስከ ዘለዓለሙ አጠፉአቸው። የእስራኤልም ልጆች ሁሉ ወደ ርስታቸውና ወደ ከተሞቻቸው ተመለሱ።'),
  ('30644c1c-4af1-515a-a320-1d147af2f453', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 2, 2, 'ሕዝቅያስም የካህናትንና የሌዋውያንን ሰሞን በየክፍላቸውና በየአገልግሎታቸው፥ በእግዚአብሔር ቤት አደባባይ በሮች የሚቃጠለውን መሥዋዕትና የደኅንነቱን መሥዋዕት ያቀርቡና ያገለግሉ ዘንድ፥ ያመሰግኑም፥ ያከብሩም ዘንድ ካህናቱንና ሌዋውያኑን መደበ።'),
  ('fc023582-a6d9-537a-ae6d-f5d002f8321e', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 3, 3, 'በእግዚአብሔርም ሕግ እንደ ተጻፈ በጥዋትና በማታ በሰንበታቱም፥ በመባቻዎቹም፥ በበዓላትም ለሚቀርበው ለሚቃጠለው መሥዋዕት ንጉሡ ከገንዘቡ የሚከፍለውን ወሰነ።'),
  ('4cdd9e52-3ac7-5470-a477-844bd24c90e0', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 4, 4, 'በእግዚአብሔርም ቤት ለአገልግሎት እንዲጸኑ ለካህናቱና ለሌዋውያን ድርሻቸውን ይሰጡ ዘንድ በኢየሩሳሌም የሚኖሩትን ሕዝብ አዘዘ።'),
  ('0c1c85da-07a4-5146-a366-1b31ec5a31e1', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 5, 5, 'ይህንም ነገር እንዳዘዘ የእስራኤል ልጆች የእህሉንና የወይኑን፥ የዘይቱንና የማሩንም፥ የእርሻውንም ፍሬ መጀመሪያ ሁሉ ሰጡ፤ የሁሉንም ዐሥራት አብዝተው አቀረቡ።'),
  ('e5d74f5a-d675-5253-a44e-a11518904980', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 6, 6, 'በይሁዳም ከተሞች የሚኖሩ የእስራኤልና የይሁዳ ልጆች የበሬዉንና የበጉን፥ የፍየሉንም ዐሥራት አመጡ፤ ለአምላካቸው ለእግዚአብሔርም ቀደሱት፤ ከምረውም አኖሩት።'),
  ('c104fed3-0c9e-50c5-a7ec-dad9011295a6', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 7, 7, 'በሦስተኛውም ወር መከመር ጀመሩ፤ በሰባተኛውም ወር ጨረሱ።'),
  ('c9982051-fc49-5891-a842-e7081178f7c1', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 8, 8, 'ሕዝቅያስና አለቆቹም መጥተው ክምሩን ባዩ ጊዜ እግዚአብሔርን አመሰገኑ። ሕዝቡን እስራኤልንም ባረኩ።'),
  ('29d48552-4e69-5cbd-a170-b36c5d2dd3f8', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 9, 9, 'ሕዝቅያስም ካህናቱንና ሌዋውያኑን ስለ ክምሩ ጠየቀ።'),
  ('65572166-27af-5464-a0f6-a51d75c9232d', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 10, 10, 'ከሳዶቅም ወገን የሆነ ታላቁ ካህን ዓዛርያስ፥ “ሕዝቡ መባውን ወደ እግዚአብሔር ፊት ማቅረብ ከጀመረ ወዲህ በልተናል፤ ጠጥተናልም፤ ጠግበናልም፤ እግዚአብሔርም ሕዝቡን ባርኮአልና ብዙ ተርፎአል፤ ከዚህም ገና ብዙ ተረፈ” ብሎ ተናገረ።'),
  ('c4f53a8d-5225-5f48-abba-b6885a675cf9', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 11, 11, 'ሕዝቅያስም ለእግዚአብሔር ቤት ጎተራ ያዘጋጁ ዘንድ አዘዘ፤ እነርሱም አዘጋጁ።'),
  ('634d5e15-adb1-57e9-ab3f-5a370e464c3c', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 12, 12, 'መባኡንና ዐሥራቱን፥ የተቀደሱትንም በእምነት ወደዚያ አገቡ። ሌዋዊውም ኮክንያስ ተሾመባቸው፥ ወንድሙም ሰሜኢ በማዕርግ ሁለተኛ ነበረ፤'),
  ('dedeab2c-cf54-5069-a191-fc81de8dbd5c', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 13, 13, 'ንጉሡም ሕዝቅያስና የእግዚአብሔር ቤት አለቃ ዓዛርያስ እንደ አዘዙ ኢዮኤል፥ ዓዛዝያ፥ አናኤት፥ ኡሳሄል፥ ኢያሪሞት፥ ኢዮዛብድ፥ ኤልሄል፥ ሰማኪያ፥ መሐት፥ በናያስና ልጆቹ፥ ከኮክንያስና ከወንድሙ ከሰሜኢ እጅ በታች ተቈጣጣሪዎች ነበሩ።'),
  ('c4e689cf-d6c7-5f2e-a036-f9fce4fee6bc', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 14, 14, 'የሌዋዊውም የይምላእ ልጅ የምሥራቁ ደጅ በረኛ ቆሬ የእግዚአብሔርን መባና የተቀደሱትን ነገሮች እንዲያካፍል ሕዝቡ በፈቃዳቸው ለእግዚአብሔር በአቀረቡት ላይ ተሾመ።'),
  ('e7c8c34d-8339-57f1-acea-2b04deed70fe', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 15, 15, 'በካህናቱም ከተሞች ለታላላቆችና ለታናናሾች ወንድሞቻቸው በየሰሞናቸው ክፍላቸውን በእምነት ይሰጡ ዘንድ ኤዶም፥ ብንያስ፥ ኢያሱ፥ ሴሚ፥ አማርያ፥ ኮክንያስ ከእጁ በታች ነበሩ።'),
  ('ceedfa0e-6aab-5bd6-a026-3049f42e7504', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 16, 16, 'ከሦስትም ዓመት ወደ ላይ ላሉ በየሰሞናቸው ለሥራቸውና ለአገልግሎታቸው ዕለት ዕለት ወደ እግዚአብሔር ቤት ለሚገቡ ወንዶች ሁሉ፥'),
  ('3560fedc-f4c4-53c1-a71d-5b7bab2b62e6', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 17, 17, 'በየአባቶቻቸውም ቤት ለተቈጠሩ ካህናት፥ ከሃያ ዓመትም ወደ ላይ ላሉ በየሥርዐታቸውና በየሰሞናቸው ለተቈጠሩ ሌዋውያን፥'),
  ('c00e41ce-49ff-5493-adf0-4926ff44d969', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 18, 18, 'በማኅበራቸውም ሁሉ በየትውልዳቸው ለተቈጠሩ ለሚስቶቻቸው፥ ለወንዶችና ለሴቶች ልጆቻቸውም ይሰጡ ነበር፤ በእምነት ፈጽመው ተቀድሰዋልና።'),
  ('c27fb393-0401-5c19-a76f-36133a2ea1c7', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 19, 19, 'ክህነት ለሚገባቸው ለአሮን ልጆች ለካህናቱ፥ በከተሞቻቸውም ዙሪያ ባሉ መሰማሪያዎችና በሌሎችም ከተሞች ላሉ ለወንዶች ሁሉ፥ ከሌዋውያን ጋራ ለተቈጠሩ ሰዎችም ሁሉ ከፍለው ይሰጡ ዘንድ በስም የተጠሩ ሰዎች ነበሩ።'),
  ('b55f6c53-7831-53f9-a993-9139ff874f74', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 20, 20, 'ሕዝቅያስም በይሁዳ ሁሉ እንዲህ አደረገ፤ በአምላኩም በእግዚአብሔር ፊት መልካምንና ቅን ነገርን እውነትንም አደረገ።'),
  ('b8aa5c13-6ff8-5ebc-a4ca-5bff8f0dc466', '32496554-42ee-54a8-a117-118cfabcdec1', '10a4842a-b1cb-58e6-a390-40725f217c7c', 21, 21, 'ስለ እግዚአብሔርም ቤት አገልግሎት በጀመረው ሥራ ሁሉ፥ በሕጉና በትእዛዙም አምላኩን እግዚአብሔርን በፍጹም ልቡ ፈለገው፤ ሥራውም ሁሉ ተከናወነለት።'),
  ('77aca90c-4318-5595-abe3-3498497c7044', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 1, 1, 'ከእነዚህም ነገሮችና ከዚህ እውነት በኋላ የአሦር ንጉሥ ሰናክሬም መጥቶ ወደ ይሁዳ ገባ፤ በተመሸጉትም ከተሞች ፊት ሰፈረ፤ ሊወስዳቸውም አሰበ።'),
  ('d899b35f-81dc-54ed-a455-14391ad2fdf1', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 2, 2, 'ሕዝቅያስም ሰናክሬም እንደ መጣ፥ ኢየሩሳሌምንም ሊወጋ ፊቱን እንዳቀና አየ፤'),
  ('2741b16d-c35b-585a-a9f8-4ea8b750bf0c', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 3, 3, 'ከከተማዪቱ በስተውጭ ያለውን የውኃውን ምንጭ ይደፍኑ ዘንድ ከአለቆቹና ከኀያላኑ ጋር ተማከረ፤ እነርሱም ምክሩን ወደዱ።'),
  ('d03987ee-a338-5c01-ab3a-ee31b0a13104', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 4, 4, 'ብዙ ሰዎችንም ሰበሰበ፥ “የአሦርም ንጉሥ እንዳይመጣና ብዙ ውኃ አግኝቶ እንዳይጠነክር” ብሎ የውኃ ምንጮችንና በከተማዪቱ የሚፈስሱትን ወንዞች ደፈነ።'),
  ('20e53604-01e8-53df-ab65-1261cf3bfad9', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 5, 5, 'ሕዝቅያስም ሰውነቱን አጽናና፤ የፈረሰውንም ቅጥር ሁሉ ጠገነ፤ በላዩም ግንብ ሠራበት፤ ከእርሱም በስተውጭ ሌላ ቅጥር ሠራ፤ ወደ ዳዊትም ከተማ የሚያወጣውን በር አጠነከረ፤ ብዙም መሣሪያና ጋሻ አዘጋጀ።'),
  ('0b7be6ec-1b93-5bbb-a7b9-c912ddc48fd2', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 6, 6, 'የጦር አለቆቹንም በሕዝቡ ላይ ሾመ፤ ሁሉንም በሸለቆው በኩል ባለው በከተማዪቱ በር አደባባይ ወደ እርሱ ሰበሰበ፤ እንዲህም ብሎ ልባቸውን አጸና፦'),
  ('f1ef5316-3e88-5725-acee-1d34d5baf6f2', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 7, 7, '“ጽኑ፥ አይዞአችሁ፤ ከእኛ ጋር ያለው ከእርሱ ጋር ካለው ይበልጣልና ከአሦር ንጉሥና ከእርሱ ጋር ካለው ጭፍራ ሁሉ የተነሣ አትፍሩ፤ አትደንግጡም።'),
  ('41fad03c-8e4b-5b1a-a901-d9ba58435db2', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 8, 8, 'ከእርሱ ጋር የሥጋ ክንድ ነው፤ ከእኛ ጋር ያለው ግን የሚረዳን የሚዋጋልንም አምላካችን እግዚአብሔር ነው።” ሕዝቡም በይሁዳ ንጉሥ በሕዝቅያስ ቃል ተጽናና።'),
  ('4d7a968f-9532-59a1-ad68-275b543ceadc', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 9, 9, 'ከዚህም በኋላ የአሦር ንጉሥ ሰናክሬም ከሠራዊቱ ሁሉ ጋር በለኪሶ ፊት ሳለ ባሪያዎቹን ወደ ኢየሩሳሌም ወደ ይሁዳ ንጉሥ ወደ ሕዝቅያስና በኢየሩሳሌም ወደ ነበሩ ወደ ይሁዳ ሕዝብ ሁሉ እንዲህ ሲል ላከ፦'),
  ('53dd3b04-2706-5c60-acb1-8753556a9d34', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 10, 10, '“የአሦር ንጉሥ ሰናክሬም እንዲህ ይላል፦ እናንተ በማን ተማምናችሁ በኢየሩሳሌም ምሽግ ትቀመጣላችሁ?'),
  ('ad9e8e96-b937-5379-ac07-b2926ba27c5d', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 11, 11, 'አምላካችን እግዚአብሔር ከአሦር ንጉሥ እጅ ያድነናል እያለ ለራብ፥ ለጥምና ለሞት አሳልፎ ይሰጣችሁ ዘንድ የሚያሳስታችሁ ሕዝቅያስ አይደለምን?'),
  ('eca9fbf3-6fac-5d94-a82e-50740d60fd58', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 12, 12, 'በዚህ መሠዊያ ፊት ስገዱ፤ በእርሱም ላይ ዕጠኑ፤ እያለ የይሁዳን ሕዝብና የኢየሩሳሌምን ነዋሪዎች አዝዞ፥ የኮረብታውን መስገጃዎችና መሠዊያዎቹን ያፈረሰ ይህ ሕዝቅያስ አይደለምን?'),
  ('e4f2d17d-7636-5e17-a11b-ed6d8dd59535', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 13, 13, 'እኔና አባቶች በምድር አሕዛብ ሁሉ ያደረግነውን አላወቃችሁምን? የምድርስ ሁሉ አሕዛብ አማልክት ሀገራቸውን ከእጄ ያድኑ ዘንድ በውኑ ተቻላቸውን?'),
  ('58df5696-9bf1-5c6f-a66d-487f487dcdf9', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 14, 14, 'አምላካችሁስ ከእጄ እናንተን ለማዳን ይችል ዘንድ አባቶች ካጠፉአቸው ከአሕዛብ አማልክት ሁሉ ሕዝቡን ከእጄ ያድን ዘንድ የቻለ ማን ነው?'),
  ('4cf60c61-6b36-56b9-a3e9-5d2309e34bb7', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 15, 15, 'አሁንም ሕዝቅያስ አያስታችሁ፤ በእነዚህም ቃላት እንድትተማመኑ አያድርጋችሁ፤ አትመኑትም፤ ከአሕዛብና ከመንግሥታት አማልክት ሁሉ ሕዝቡን ከእጄና ከአባቶች እጅ ያድን ዘንድ ማንም አልቻለም፤ ስለዚህም አምላካችሁ ከእጄ ያድናችሁ ዘንድ አይችልም።”'),
  ('0975781f-94ec-5880-a099-089e602d59fb', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 16, 16, 'ባሪያዎቹም ደግሞ በአምላክ በእግዚአብሔርና በባሪያው በሕዝቅያስ ላይ ሌላ ብዙ ነገር ተናገሩ።'),
  ('912d3a4a-5df4-5977-ab23-2fb1dcf372ce', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 17, 17, 'ደግሞም የእስራኤልን አምላክ እግዚአብሔርን እየተገዳደረ በእርሱም ላይ እየተናገረ፥ “የምድር አሕዛብ አማልክት ሕዝባቸውን ከእጄ ያድኑ ዘንድ እንዳልቻሉ፥ እንዲሁ የሕዝቅያስ አምላክ ሕዝቡን ከእጄ ያድን ዘንድ አይችልም” የሚል ደብዳቤ ጻፈ።'),
  ('1d934670-2ce9-5a44-a94e-738d40edbbae', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 18, 18, 'ቅጥሩን እንዲያፈርሱ ከተማዪቱንም እንዲወስዱ፥ በቅጥር ላይ የተቀመጡትን የኢየሩሳሌምን ሕዝብ ያስፈራቸውና ያስደነግጣቸው ዘንድ በታላቅ ድምፅ በዕብራይስጥ ቋንቋ ይጮኽባቸው ነበር።'),
  ('ccb36c25-9b2e-5811-a778-f16a1660c695', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 19, 19, 'በሰውም እጅ በተሠሩ በምድር አሕዛብ አማልክት ላይ እንደሚናገር መጠን በኢየሩሳሌም አምላክ ላይ ተናገረ።'),
  ('c9907453-5305-5182-a1ad-3125a3cd01a0', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 20, 20, 'ንጉሡ ሕዝቅያስና የአሞጽ ልጅ ነቢዩ ኢሳይያስ ስለዚህ ተግዳሮት ጸለዩ፤ ወደ ሰማይም ጮኹ።'),
  ('3debc2b6-ae62-5b92-a2f9-4bc623b3d56e', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 21, 21, 'እግዚአብሔርም መልአኩን ላከ፤ እርሱም ጽኑዓን ኀያላኑንና መሳፍንቱን አለቆቹንም ከአሦር ንጉሥ ሰፈር አጠፋ። የአሦርም ንጉሥ አፍሮ ወደ ሀገሩ ተመለሰ። ወደ አምላኩም ቤት በገባ ጊዜ ከወገቡ የወጡት ልጆቹ በዚያ በሰይፍ ገደሉት።'),
  ('090e3ac8-9ec5-57bd-a1cf-d7bd36414a9d', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 22, 22, 'እግዚአብሔርም ሕዝቅያስንና በኢየሩሳሌም የሚኖሩትን ከአሦር ንጉሥ ከስናክሬም እጅና ከሁሉም እጅ አዳናቸው፤ በዙሪያቸውም ካለው ሁሉ አሳረፋቸው።'),
  ('4cb96aac-c950-572e-a6e9-f246638fac83', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 23, 23, 'ብዙዎቹም ለእግዚአብሔር መባ ይዘው ወደ ኢየሩሳሌም ይመጡ ነበር፤ ለይሁዳም ንጉሥ ለሕዝቅያስ እጅ መንሻ ይሰጡ ነበር፤ እርሱም ከዚህ ነገር በኋላ በሕዝብ ሁሉ ፊት ከፍ ከፍ አለ።'),
  ('eb463766-e5b1-5885-a021-01b315826117', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 24, 24, 'በዚያም ወራት ሕዝቅያስ እስከ ሞት ድረስ ታመመ፤ ወደ እግዚአብሔርም ጸለየ፤ እርሱም ሰማው፤ ምልክትም ሰጠው።'),
  ('a67ff8d1-1d92-550c-a164-00071f952bb5', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 25, 25, 'ሕዝቅያስ ግን እግዚአብሔር እንደ ሰጠው ቸርነት መጠን አላደረገም፤ ልቡም ኮራ፤ ስለዚህም በእርሱና በይሁዳ፥ በኢየሩሳሌምም ላይ ቍጣ ሆነ።'),
  ('27e4d2b2-9511-50d0-af80-de85dcc71d7a', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 26, 26, 'ሕዝቅያስም በኢየሩሳሌም ከሚኖሩ ሰዎች ጋር ስለ ልቡ ኵራት ሰውነቱን አዋረደ፤ እግዚአብሔርም በሕዝቅያስ ዘመን ቍጣውን አላመጣባቸውም።'),
  ('40471e23-ac4c-5b08-af0e-804cb5825474', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 27, 27, 'ለሕዝቅያስም እጅግ ብዙ ሀብትና ክብር ነበረው፤ ለብርና ለወርቅም፥ ለከበረው ዕንቍና ለሽቱው፥ ለጋሻውና ውድ ለሆነው ዕቃ ሁሉ ግምጃ ቤቶችን ሠራ።'),
  ('794ca0f9-ef4e-5e97-acaa-1ba4bcdbfe02', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 28, 28, 'ለእህልና ለወይን ጠጅም ለዘይትም ዕቃ ቤቶች፥ ለልዩ ልዩም እንስሳ ጋጥ፥ ለመንጎችም በረት ሠራ።'),
  ('2fa4f529-c0d9-5c4b-a7b3-f37723aa2e94', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 29, 29, 'እግዚአብሔርም እጅግ ብዙ ጥሪት ሰጥቶት ነበርና ከተሞችን ለራሱ ሠራ፤ ብዙም የበግና የላም መንጋ ሰበሰበ።'),
  ('1d924892-9fc8-5c53-a421-ca5e0a9187f7', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 30, 30, 'ይህም ሕዝቅያስ የላይኛውን የግዮንን ውኃ ምንጭ ደፈነ፤ በዳዊትም ከተማ በምዕራብ በኩል አቅንቶ አወረደው። ሕዝቅያስም በሥራው ሁሉ ተከናወነ።'),
  ('daa23693-ddba-5cc1-a6f1-a6bc075d71d9', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 31, 31, 'ነገር ግን የባቢሎን መሳፍንት መልእክተኞች በሀገሩ ላይ ስለ ተደረገው ተአምራት ይጠይቁት ዘንድ ወደ እርሱ በተላኩ ጊዜ እግዚአብሔር ይፈትነውና በልቡ ያለውን ሁሉ ያውቅ ዘንድ ተወው።'),
  ('6ca041a1-13ac-5d95-a49d-fc6faccc3e6a', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 32, 32, 'የሕዝቅያስም የቀሩት ነገሮች፥ ቸርነቱም፥ እነሆ፥ በአሞጽ ልጅ በነቢዩ በኢሳይያስ ራእይ በይሁዳና በእስራኤልም ነገሥታት መጽሐፍ ተጽፈዋል።'),
  ('d6e0700f-21da-58f1-a6db-3e0e0527b7b5', '0f1c82eb-cd5b-5507-ad7a-fa9ffe642640', '7cbddba0-5aab-5af4-a3ef-ac9af3c623e5', 33, 33, 'ሕዝቅያስም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ልጆች መቃብር በላይኛው ክፍል ቀበሩት፤ በይሁዳና በኢየሩሳሌም የሚኖሩትም ሁሉ በሞቱ አከበሩት። ልጁም ምናሴ በእርሱ ፋንታ ነገሠ።'),
  ('ca38ddf2-4843-5802-a168-5476b003a4c2', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 1, 1, 'ምናሴም መንገሥ በጀመረ ጊዜ የዐሥራ ሁለት ዓመት ልጅ ነበረ፤ በኢየሩሳሌምም አምሳ አምስት ዓመት ነገሠ።'),
  ('13d4888c-0b9a-551e-a19a-d6555b51eb71', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 2, 2, 'እግዚአብሔርም ከእስራኤል ልጆች ፊት እንዳወጣቸው እንደ አሕዛብ ያለ ርኵሰት በእግዚአብሔር ፊት ክፉ ነገርን አደረገ።'),
  ('6255da8c-322c-568d-a942-6b49af15074e', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 3, 3, 'አባቱም ሕዝቅያስ ያፈረሳቸውን የኮረብታ መስገጃዎች መልሶ ሠራ፤ ለበዓሊምም መሠዊያ ሠራ፤ የማምለኪያ ዐፀዶችንም ተከለ፤ ለሰማይም ሠራዊት ሁሉ ሰገደ፤ አመለካቸውም።'),
  ('016b1e42-b790-5325-aae4-4291f5ba147f', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 4, 4, 'እግዚአብሔርም፥ “ስሜ በኢየሩሳሌም ለዘለዓለም ይኖራል” ባለው በእግዚአብሔር ቤት የጣዖት መሠዊያዎችን ሠራ።'),
  ('d3f416af-8d31-5958-a2ff-fbe84e67dc8e', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 5, 5, 'በእግዚአብሔርም ቤት በሁለቱ አደባባዮች ላይ ለሰማይ ሠራዊት ሁሉ መሠዊያዎችን ሠራ።'),
  ('f1e90568-7e0b-5fd1-ae8c-46f82dec1ba9', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 6, 6, 'በሄኖምም ልጅ ሸለቆ ውስጥ ልጆቹን በእሳት አቃጠለ፤ ሞራ ገላጭም ሆነ፤ አስማትም አደረገ። መተተኛም ነበረ፤ መናፍስት ጠሪዎችንና ጠንቋዮችንም ሰበሰበ፤ ያስቈጣውም ዘንድ በእግዚአብሔር ፊት እጅግ ክፉ ነገርን አደረገ።'),
  ('d4e7e5bd-5568-57a8-a405-2a9e6167f057', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 7, 7, 'እግዚአብሔርም ለዳዊትና ለልጁ ለሰሎሞን፥ “በዚህ ቤትና ከእስራኤል ነገድ ሁሉ በመረጥኋት በኢየሩሳሌም ስሜን ለዘለዓለም አኖራለሁ፤'),
  ('aebf889b-2c4c-5241-a5c5-3212b969b974', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 8, 8, 'ያዘዝኋቸውንም ሁሉ፥ በሙሴ የተሰጠውን ሕግና ሥርዐት ፍርድንም ሁሉ ቢያደርጉ ቢጠብቁም፥ ለአባቶቻችሁ ከሰጠኋት ምድር የእስራኤልን እግር እንደ ገና አላርቅም” ባለበት በእግዚአብሔር ቤት ውስጥ የሠራውን ጣዖትና የተቀረጸውን ምስል አቆመ።'),
  ('55176a2d-630e-5bcf-a759-4b6515b99024', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 9, 9, 'ምናሴም እግዚአብሔር ከእስራኤል ልጆች ፊት ካጠፋቸው ከአሕዛብ ይልቅ ክፉ ይሠሩ ዘንድ በይሁዳና በኢየሩሳሌም የሚኖሩትን አሳተ።'),
  ('0bc64812-5039-528e-aefd-4dbad25bbbcb', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 10, 10, 'እግዚአብሔርም ምናሴንና ሕዝቡን ተናገራቸው፤ ግን አልሰሙትም።'),
  ('e278e59b-b98f-5816-a22a-04256453cc32', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 11, 11, 'ስለዚህም እግዚአብሔር የአሦርን ንጉሥ ሠራዊት አለቆች አመጣባቸው፤ ምናሴንም በዛንጅር ያዙት፤ በሰንሰለትም አስረው ወደ ባቢሎን ወሰዱት።'),
  ('e25df863-3d75-591b-a4d4-860868c6723c', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 12, 12, 'በተጨነቀም ጊዜ አምላኩን እግዚአብሔርን ፈለገ፤ በአባቶቹም አምላክ ፊት ሰውነቱን እጅግ አዋረደ።'),
  ('583c6949-5026-51e1-aefc-1974279c5a75', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'd057c5d7-6c8c-5bfe-aada-45e959d93bb1', 13, 13, 'የንጉሡ የሕዝቅያስ ልጅ ምናሴም ጸለየ እንዲህም አለ፦'),
  ('87e2ed74-edef-5fe8-aa5a-96d92fc8ad54', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 1, 14, '“ዓለምን ሁሉ የምትገዛ፥'),
  ('d8243bad-3c9f-5799-af33-ace189024325', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 2, 15, 'በቃልህ ትእዛዝ ባሕርን የገሠጽሃት፥'),
  ('b2973b0d-973f-5abb-a2bb-1e8d05e8d1b3', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 3, 16, 'ይኸውም በተመሰገነው ስምህ ነው፤'),
  ('e6380f91-42c8-5765-a9e4-0d8d42dedbfb', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 4, 17, 'ለክብርህ ከፍተኛነት ፍጻሜ የለውምና፥'),
  ('9921ec1c-e4d8-5231-a65a-d317b47d48a1', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 5, 18, 'በትእዛዝህ ለሚሆነው ይቅርታ ስፍር ቍጥር የለውም፤'),
  ('f0eda522-ef09-5878-a593-f0799b3eacb8', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 6, 19, 'አሁንም አቤቱ፥ የጻድቃን አምላካቸው አንተ ነህ።'),
  ('eaa9d4a8-8fbe-54ef-a3d2-11935b941a21', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 7, 20, 'ቍጥሩ ከባሕር አሸዋ የሚበልጥ በደልን በድያለሁና፥'),
  ('9427ba7c-cbaa-5405-ad19-ffe072bf410a', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 8, 21, 'ከንቱውን ስመለከት የማይጠቅመኝንም ነገር ሳበዛ'),
  ('61a83612-a242-56b9-adb1-28ff7b21a74f', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 9, 22, 'አሁንም ቸርነትህን እየለመንሁ በልቤ ጕልበት እሰግዳለሁ።'),
  ('99e6d9a8-6f45-54d5-aa92-a3200b536499', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 10, 23, 'አቤቱ፥ ጌታዬ፥ ፈጽሜ በደልሁ፤'),
  ('21c0286b-ed38-5d03-a8fa-c034654f6bf8', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 11, 24, 'አንተንም እማልዳለሁ፤ እለምንህማለሁ፤'),
  ('6bcddb00-4d04-5b03-a440-92814e328db8', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 12, 25, 'ለዘለዓለም ክፋቴን አትመልከትብኝ፤'),
  ('c5c0b3e4-69a1-53ec-a126-214cecd0936b', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 13, 26, 'በየጊዜውና በሕይወቴ ዘመን ሁሉ አመሰግንሃለሁ።'),
  ('608ed7bb-bc78-58b8-aece-e05a4b3ac37f', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 14, 27, 'ከዚህ በኋላ በዳዊት ከተማ በስተውጭው ከግዮን ሰሜናዊ ምዕራብ በሸለቆው ውስጥ እስከ ዓሣ በር መግቢያ ድረስ ቅጥር ሠራ። እስከ ዖፌልም አዞረበት፤ እጅግም ከፍ አደረገው፤ በተመሸጉትም በይሁዳ ከተሞች ሁሉ የጭፍራ አለቆችን አኖረ።'),
  ('879ce149-c5c8-583a-a98c-b4d3623034e8', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 15, 28, 'እንግዶችንም አማልክትና ጣዖታቱንም ከእግዚአብሔር ቤት አራቀ፤ የእግዚአብሔርም ቤት ባለበት ተራራ ላይና በኢየሩሳሌም የሠራቸውን መሠዊያዎች ሁሉ ወስዶ ከከተማዪቱ በስተውጭ ጣላቸው።'),
  ('04f5de32-ea05-552a-aa90-0d228bd59d23', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 16, 29, 'የእግዚአብሔርንም መሠዊያ ደግሞ አደሰ፤ የደኅነትንና የምስጋናንም መሥዋዕት ሠዋበት፤ የይሁዳም ሕዝብ የእስራኤልን አምላክ እግዚአብሔርን እንዲያመልኩ አዘዘ።'),
  ('4eee6e60-2ff1-54cb-ab4d-a732df4321df', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 17, 30, 'ሕዝቡ ግን ከአምላካቸው ከእግዚአብሔር ፈጽመው ርቀው ገና በኮረብታዎች ላይ ይሠዉ ነበር፥'),
  ('b59569e4-00a3-522a-a0da-a9daf9901110', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 18, 31, 'የምናሴም የቀሩት ነገሮች፥ ወደ አምላኩም የጸለየው ጸሎት፥ በእስራኤልም አምላክ በእግዚአብሔር ስም የነገሩት የነቢያት ቃል፥ እነሆ፥ በእስራኤል ነገሥታት መጽሐፍ ተጽፈዋል።'),
  ('abdbf400-9aa5-54d5-a763-93c6ca19c662', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 19, 32, 'ደግሞም ጸሎቱን፥ እግዚአብሔር እንደ ሰማው፥ ኀጢአቱና መተላለፉ ሁሉ፥ ወደ እግዚአብሔር ሳይመለስ ኮረብታውን የሠራበት ዐፀዱንና የተቀረጹትንም ምስሎች የተከለበት ስፍራ፥ እነሆ፥ በባለ ራእዩ የታሪክ መጽሐፍ ተጽፈዋል።'),
  ('c67d9a73-f0b4-5573-a5d8-90f984ceeb52', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 20, 33, 'ምናሴም ከአባቶቹ ጋር አንቀላፋ፤ በቤቱም አትክልት ቦታ ቀበሩት፤ ልጁም አሞጽ በእርሱ ፋንታ ነገሠ።'),
  ('5ffa52c7-7ac0-5bcf-aaff-61347279565c', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 21, 34, 'አሞጽ መንገሥ በጀመረ ጊዜ የሃያ ሁለት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ሁለት ዓመት ነገሠ።'),
  ('be4448e4-1d98-5a72-aa56-be193d7280de', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 22, 35, 'አባቱም ምናሴ እንዳደረገ በእግዚአብሔር ፊት ክፉ አደረገ፤ አሞጽም አባቱ ምናሴ ለሠራቸው ለተቀረጹት ምስሎች ሁሉ ሠዋ፤ አመለካቸውም።'),
  ('d187e309-c169-55d3-a140-d35337330337', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 23, 36, 'አባቱም ምናሴ ሰውነቱን እንዳዋረደ በእግዚአብሔር ፊት ሰውነቱን አላዋረደም፤ ነገር ግን አሞጽ መተላለፉን እጅግ አበዛ።'),
  ('246a53d6-b10d-5686-ab10-cb624f118668', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 24, 37, 'አገልጋዮቹም ተነሡበት፤ በቤቱም ገደሉት።'),
  ('8c1f5865-7c53-5f34-a9f3-ea305a8977a1', 'c6d79554-6160-50dd-a700-e002a09bfb77', 'ffe99909-14a8-5833-a6b2-fa375e940e1e', 25, 38, 'የሀገሩ ሕዝብ ግን በንጉሡ በአሞጽ ላይ የተነሡትን ሁሉ ገደሉ፤ የሀገሩም ሕዝብ ልጁን ኢዮስያስን በእርሱ ፋንታ አነገሡ።'),
  ('56620c89-488b-502e-a71d-62e3f7a265e4', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 1, 1, 'ኢዮስያስም መንገሥ በጀመረ ጊዜ የስምንት ዓመት ልጅ ነበረ፤ በኢየሩሳሌምም ሠላሳ አንድ ዓመት ነገሠ።'),
  ('f110e18e-b932-576b-a841-cc6237b619fe', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 2, 2, 'በእግዚአብሔርም ፊት ቅን ነገር አደረገ፤ በአባቱም በዳዊት መንገድ ሄደ፤ ወደ ቀኝም ወደ ግራም አላለም።'),
  ('7e9fdc29-449b-5e65-a169-3ba482ce8b1e', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 3, 3, 'በነገሠም በስምንተኛው ዓመት ገና ብላቴና ሳለ የአባቱን የዳዊትን አምላክ ይፈልግ ጀመረ፤ በዐሥራ ሁለተኛውም ዓመት ይሁዳንና ኢየሩሳሌምን ከኮረብታውና ከዐፀዶቹ፥ ከተቀረጹትና ቀልጠው ከተሠሩት ምስሎች ያነጻ ጀመር።'),
  ('58ac088f-1cf5-533b-a3ab-94ad77c6bca9', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 4, 4, 'የበዓሊምንም መሠዊያዎች በፊቱ አፈረሰ፤ በላዩም የነበሩትን ኮረብታዎችን ዐፀዶቹንም ቈረጠ፤ የተቀረጹትንና ቀልጠው የተሠሩትንም ምስሎች ሰባበረ፤ አደቀቃቸውም፤ ይሠዉላቸው በነበሩት ሰዎች መቃብርም ላይ በተናቸው።'),
  ('a477c568-329c-5730-a778-5e2a2dcd2fea', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 5, 5, 'የካህኖቻቸውንም አጥንት በመሠዊያቸው ላይ አቃጠለ። ይሁዳንና ኢየሩሳሌምንም አነጻ።'),
  ('f24a1039-13cf-53d0-a278-f3f7a8691b17', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 6, 6, 'የምናሴንና የኤፍሬምንም፥ የስምዖንና የንፍታሌምንም ከተሞች፥ በዙሪያቸውም ያለውን ቦታ እንዲሁ አነጻ።'),
  ('c82ae0f3-ffb3-5e9f-ae52-23a03405cb13', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 7, 7, 'መሠዊያዎቹንም አፈረሰ፤ የማምለኪያ ዐፀዶቹንና የተቀረጹትን ምስሎችም አደቀቀ፤ በእስራኤልም ሀገር ሁሉ የኮረብታዎችን መስገጃዎችአጠፋ። ወደ ኢየሩሳሌምም ተመለሰ።'),
  ('46519eff-bf78-52e8-af9a-35f02509a4ad', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 8, 8, 'በነገሠም በዐሥራ ስምንተኛው ዓመት ምድሪቱንና የእግዚአብሔርን ቤት ካነጻ በኋላ፥ የሴልያ ልጅ ሳፋን፥ የከተማዪቱም አለቃ መዕሴያ፥ ታሪክ ጸሓፊውም የኢዮአካዝ ልጅ ኢዮአክ የእግዚአብሔርን የአምላኩን ቤት ይጠግኑ ዘንድ ሰደዳቸው።'),
  ('2141d6a3-29bf-5214-a03d-f9c306fc856e', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 9, 9, 'ወደ ታላቁም ካህን ወደ ኬልቅያስ መጡ፤ ሌዋውያኑም በረኞች ከምናሴና ከኤፍሬም፥ ከአለቆችም፥ ከቀረውም ከእስራኤል ሁሉ፥ ከይሁዳና ከብንያም ሁሉ በኢየሩሳሌምም ከሚኖሩት የሰበሰቡትን፥ ወደ እግዚአብሔር ቤት የቀረበውን ገንዘብ ሰጡት።'),
  ('c636f71f-00f8-55b1-a5a0-ff238976b802', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 10, 10, 'የእግዚአብሔርንም ቤት በሚሠሩት ላይ ለተሾሙት ሰጡ፤ እነርሱም ይጠግኑና ያድሱ ዘንድ የእግዚአብሔርን ቤት ለሚሠሩ ሠራተኞች ሰጡአቸው።'),
  ('2a9a7548-c77f-5891-af71-eac5f4782837', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 11, 11, 'የይሁዳ ነገሥታት ላፈረሱት ቤት ሰረገሎች ያደርጉ ዘንድ፥ ለማጋጠሚያም እንጨት፥ የተጠረበውንም ድንጋይ ይገዙ ዘንድ ለአናጢዎችና ለጠራቢዎች ሰጡ።'),
  ('c298a1ec-f1b3-50d0-afb8-3e2b37c0e7c3', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 12, 12, 'ሰዎቹም ሥራውን በመታመን አደረጉ፤ በእነርሱም ላይ የተሾሙት፥ ሥራውንም የሚያሠሩት ሌዋውያን ከሜራሪ ልጆች ይኤትና አብድያስ፥ ከቀዓትም ልጆች ዘካርያስና ሜሱላም ነበሩ። ከሌዋውያንም ወገን በዜማ ዕቃ ዐዋቂዎች፥ የነበሩ ሁሉ፥'),
  ('a589fcea-35cc-5385-ab0d-60374428f2f0', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5aa88dba-d405-5d8e-a071-1dc0f6450c1d', 13, 13, 'በተሸካሚዎችና ልዩ ልዩ ሥራ በሚሠሩ ላይ ተሾመው ነበር፤ ጸሓፊዎቹና አለቆቹም በረኞቹም ከሌዋውያን ወገን ነበሩ።'),
  ('f6e94a1f-7d1c-5f9c-a162-2b766e55cdd8', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 1, 14, 'ወደ እግዚአብሔርም ቤት የቀረበውን ገንዘብ ባመጡ ጊዜ ካህኑ ኬልቅያስ በሙሴ እጅ የተሰጠውን የእግዚአብሔርን ሕግ መጽሐፍ አገኘ።'),
  ('bbfd5a3b-7aa5-57d5-a934-648142326058', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 2, 15, 'ኬልቅያስም ጸሓፊውን ሳፋንን፥ “የሕጉን መጽሐፍ በእግዚአብሔር ቤት አግኝቼአለሁ” ብሎ ነገረው። ኬልቅያስም መጽሐፉን ለሳፋን ሰጠው።'),
  ('0834598e-d311-58a0-a35b-14e1ef5258e7', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 3, 16, 'ሳፋንም መጽሐፉን ወደ ንጉሡ አመጣ፤ ለንጉሡም ዳግመኛ እንዲህ አለው፥ “ወርቁንና ብሩን፥ መባውንም ሁሉ የቤተ እግዚአብሔርን ሥራ ለሚሠሩ ለአገልጋዮችህ በእጃቸው ሰጧቸው።'),
  ('c3203f31-7485-5212-ad8c-d87b0e09b976', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 4, 17, 'በእግዚአብሔርም ቤት የተገኘውን ገንዘብ አፈሰሱ፤ በሥራው ላይ ለተሾሙትና ለሠራተኞቹም በእጃቸው ሰጡ።”'),
  ('5ebe063f-068f-529c-aeb2-333b1a58c19c', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 5, 18, 'ጸሓፊውም ሳፋን ለንጉሡ፥ “ካህኑ ኬልቅያስ መጽሐፍ ሰጠኝ” ብሎ ነገረው። ሳፋንም በንጉሡ ፊት አነበበው።'),
  ('35a45516-a20f-59e4-ad4f-e3c9042f0197', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 6, 19, 'ንጉሡም የሕጉን ቃል በሰማ ጊዜ ልብሱን ቀደደ።'),
  ('8925dfc9-4f32-53dc-a686-3da42072d3ff', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 7, 20, 'ንጉሡም ኬልቅያስን፥ የሳፋንንም ልጅ አኪቃምን፥ የሚክያስንም ልጅ አብዶንን፥ ጸሓፊውንም ሳፋንን፥ የንጉሡንም ብላቴና ዔሴኢያን፦'),
  ('acc4684c-e62b-589b-a32c-563397c99256', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 8, 21, '“በዚህ መጽሐፍ የተጻፈውን ሁሉ ያደርጉ ዘንድ አባቶቻችን የእግዚአብሔርን ቃል ስላልጠበቁ፥ በላያችን የነደደ የእግዚአብሔር ቍጣ እጅግ ነውና ሄዳችሁ ስለ ተገኘው የመጽሐፍ ቃል ስለእኔ፥ በእስራኤልና በይሁዳ ስለቀሩትም እግዚአብሔርን ጠይቁ” ብሎ አዘዛቸው።'),
  ('0c85e293-ffa5-5f21-a5e6-a47828375c10', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 9, 22, 'ኬልቅያስና እነዚያ ንጉሡ ያዘዛቸው ወደ ልብስ ጠባቂው ወደ ሐስራ ልጅ ወደ ቴቁዋ ልጅ ወደ ሴሌም ሚስት ወደ ነቢይቱ ወደ ሕልዳና ሄዱ፤ እርስዋም በኢየሩሳሌም በከተማዪቱ በሁለተኛው ክፍል ተቀምጣ ነበር፤ ይህንም ነገር ነገሩአት።'),
  ('06bce9ab-5d3d-53f3-a74f-7d1e4b2e1c24', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 10, 23, 'እርስዋም አለቻቸው፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ወደ እኔ ለላካችሁ ሰው እንዲህ ብላችሁ ንገሩት፦'),
  ('59864967-0a24-5f0b-a4d4-d4cf8b437a12', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 11, 24, 'እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ በዚህ ስፍራና በሚኖሩበት ላይ በይሁዳ ንጉሥ ፊት በተነበበው መጽሐፍ የተጻፉትን ቃላት ሁሉ፥ ማለት ክፉ ነገርን አመጣለሁ፥'),
  ('d15799a6-e5af-5b70-ab63-77d6a2b1993a', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 12, 25, 'በእጃቸው ሥራ ሁሉ ሊያስቈጡኝ ትተውኛልና፥ ለሌሎችም አማልክት አጥነዋልና ቍጣዬ በዚህ ስፍራ ላይ ይነድዳል፤ አይጠፋምም።'),
  ('5b6693b2-6553-597d-aae6-63da1b388220', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 13, 26, 'እግዚአብሔርን ለመጠየቅ ለላካችሁ ለይሁዳ ንጉሥ እንዲህ በሉት፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ስለ ሰማኸው ቃል ልብህ ደንግጦአልና፥'),
  ('a7ec2e62-0de2-5990-a47c-dfeced457e54', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 14, 27, 'በፊቴም ራስህን አዋርደሃልና፥ በዚህም ስፍራ በሚኖሩበት ላይ ቃሌን በሰማህ ጊዜ ራስህን አዋርደሃልና፥ ልብስህንም ቀድደህ በፊቴ አልቅሰሃልና እኔ ደግሞ ሰምቼሃለሁ፥ ይላል እግዚአብሔር።'),
  ('6076d297-cdd2-5ef4-aa8f-47c8e520fcb3', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 15, 28, 'እነሆ፥ ወደ አባቶችህ እሰበስብሃለሁ፤ በሰላምም ወደ መቃብርህ ትሰበሰባለህ፤ በዚህም ስፍራና በሚኖሩበት ላይ የማመጣውን ክፉ ነገር ሁሉ ዐይኖችህ አያዩም” ያለቻቸውንም ነገር ለንጉሡ አስረዱት።'),
  ('6fe86577-d29d-5769-a2a7-99f82311f955', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 16, 29, 'ንጉሡም ላከ፤ የይሁዳንና የኢየሩሳሌምን ሽማግሌዎች ሁሉ ሰበሰበ።'),
  ('c968d9ea-b503-542c-a050-724e980efae4', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 17, 30, 'ንጉሡም፥ የይሁዳም ሰዎች ሁሉ፥ በኢየሩሳሌምም የሚኖሩና ካህናቱ፥ ሌዋውያኑም፥ ሕዝቡም ሁሉ ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ወደ እግዚአብሔር ቤት ወጡ፤ በእግዚአብሔርም ቤት የተገኘውን የቃል ኪዳኑን መጽሐፍ ቃል ሁሉ በጆሮአቸው አነበበ።'),
  ('be147b46-658f-5d8b-a33b-a84a12920950', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 18, 31, 'ንጉሡም በዐምዱ ቆሞ እግዚአብሔርን ተከትሎ እንዲሄድ፥ ትእዛዙንና ምስክሩን፥ ሥርዐቱንም በፍጹም ልቡና በፍጹም ነፍሱ እንዲጠብቅ፥ በዚህም መጽሐፍ የተጻፈውን የቃል ኪዳን ቃል እንዲያደርግ በእግዚአብሔር ፊት ቃል ኪዳን አደረገ።'),
  ('be720535-f730-51af-a038-f34b5e4144a9', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 19, 32, 'በኢየሩሳሌምና በብንያምም ሀገር የተገኙትን ሁሉ በዚህ ነገር አማለ። በኢየሩሳሌምም የሚኖሩ እንደ አባቶቻቸው አምላክ እንደ እግዚአብሔር ቤት ቃል ኪዳን አደረጉ።'),
  ('4859669d-0a27-5474-a7cc-04663572b8a4', '8d320f20-ed00-5ac5-a392-bfdfb641935c', '5cf740e9-e265-51fe-aadb-8ecdfa1682dc', 20, 33, 'ኢዮስያስም ከእስራኤል ልጆች ምድር ሁሉ ርኩሱን ሁሉ አስወገደ፤ በእስራኤልም የተገኙትን ሁሉ አምላካቸውን እግዚአብሔርን እንዲያመልኩ አደረገ። በዘመኑ ሁሉ የአባቶቻቸውን አምላክ እግዚአብሔርን ከመከተል አልራቁም።'),
  ('77fafe9b-c05d-5107-a599-b574b6d57d2b', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 1, 1, 'ኢዮስያስም ለአምላኩ ለእግዚአብሔር በኢየሩሳሌም ፋሲካ አደረገ፤ በመጀመሪያውም ወር በዐሥራ አራተኛው ቀን የፋሲካውን በግ አረዱ።'),
  ('08044dd5-373e-555e-aee9-50d4932ca910', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 2, 2, 'ካህናቱንም በየሥርዐታቸው አቆመ፤ በእግዚአብሔርም ቤት ያገለግሉ ዘንድ አጸናቸው።'),
  ('264cd659-e17b-58bd-a9fe-d474470d1e6e', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 3, 3, 'በእስራኤልም ሁሉ መሥራት የሚችሉትን ሌዋውያን ራሳቸውን ለእግዚአብሔር እንዲያነጹና ቅድስቲቱንም ታቦት የእስራኤል ንጉሥ የዳዊት ልጅ ሰሎሞን በሠራው ቤት ውስጥ እንዲያኖሩ አዘዛቸው። ንጉሡም ኢዮስያስ አለ፥ “በትከሻችሁ የምትሸከሙት አንዳች ነገር አይኑር፤ አሁንም አምላካችሁን እግዚአብሔርንና ሕዝቡን እስራኤልን አገልግሉ፤'),
  ('308224ab-9cb4-5ae9-ad89-a71efb31f559', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 4, 4, 'የእስራኤልም ንጉሥ ዳዊት እንደ አዘዘ፥ ልጁም ሰሎሞን እንደ አዘዘ በየሰሞናችሁና በየአባቶቻችሁ ቤቶች ተዘጋጁ፤'),
  ('f2b5f72b-401a-555e-abea-a22e72c8f84e', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 5, 5, 'እንደ ሕዝቡም ልጆች እንደ ወንድሞቻችሁ በየአባቶች ቤቶች አከፋፈል በመቅደሱ ቁሙ፤ እንዲሁም ለሌዋውያን በየአባቶቻቸው ቤት አከፋፈል ይሁን፤'),
  ('6b4fb118-c656-5a62-aff8-ea571c4c651b', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 6, 6, 'የፋሲካውንም በግ እረዱ፤ እናንተም ተቀደሱ፥ እግዚአብሔርም በሙሴ እጅ የተናገረውን ቃል ታደርጉ ዘንድ ለወንድሞቻችሁ አዘጋጁ።”'),
  ('1d67c919-2e62-51d4-a3fd-bc170f1c07e2', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 7, 7, 'ኢዮስያስም ለፋሲካው መሥዋዕት እንዲሆን በዚያ ለነበሩት ለሕዝቡ ልጆች ከመንጋው ሠላሳ ሺህ የበግና የፍየል ጠቦቶች፥ ሦስት ሺህም ወይፈኖች ሰጣቸው፤ እነዚህም ከንጉሡ ሀብት ነበሩ።'),
  ('c7562c7b-cdd0-536f-ab55-f9e3c9a73f62', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 8, 8, 'አለቆቹም ለሕዝቡና ለካህናቱ፥ ለሌዋውያኑም በፈቃዳቸው ሰጡ፤ የእግዚአብሔርም ቤት አለቆች፥ ኬልቅያስ፥ ዘካርያስ፥ ኢዮሔል፥ ለፋሲካው መሥዋዕት እንዲሆን ሁለት ሺህ ስድስት መቶ በጎችንና ፍየሎችን፥ ሦስት መቶም በሬዎችን ለካህናቱ ሰጡ።'),
  ('d5cb0310-61ba-5bfe-a866-0f1bfd741791', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 9, 9, 'የሌዋውያኑም አለቆች ኮኒንያስ በንያስም፥ ወንድሞቹም ሰማዕያስና ናትናኤል፥ ሰብንያስ፥ ኢዮሄል፥ ኢዮዛብድ ለፋሲካው መሥዋዕት እንዲሆን አምስት ሺህ በጎችን፥ አምስት መቶም በሬዎችን ለሌዋውያን ሰጡ።'),
  ('7157b65b-37f0-5a78-a729-b625810e07ec', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 10, 10, 'አገልግሎቱም ተዘጋጀ፤ ካህናቱም በየስፍራቸው፥ ሌዋውያኑም በየክፍላቸው እንደ ንጉሡ ትእዛዝ ቆሙ።'),
  ('2bd17af3-c6a7-5b85-ae7a-8a57328dbc15', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 11, 11, 'የፋሲካውንም በግ አረዱ፤ ካህናቱም ከእጃቸው የተቀበሉትን ደም ረጩ፤ ሌዋውያኑም ቍርበቱን ገፈፉ።'),
  ('c4ef16dc-131e-5f80-acbe-8620b38cab09', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 12, 12, 'በሙሴም መጽሐፍ እንደ ተጻፈ ለእግዚአብሔር ያቀርቡ ዘንድ በየአባቶቻቸው ቤቶች እንደ ክፍላቸው ለሕዝቡ ልጆች እንዲሰጡ የሚቃጠለውን መሥዋዕት ለዩ። እንዲሁም በበሬዎቹ አደረጉ።'),
  ('8c09c87b-3c25-5980-af6c-3b9bc9efdf1d', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 13, 13, 'የፋሲካውንም በግ እንደ ሙሴ ሥርዐት በእሳት ጠበሱ፤ የተቀደሰውንም ቍርባን በምንቸትና በሰታቴ፥ በድስትም ቀቀሉ፤ ተከናወነላቸውም፤ ለሕዝቡም ልጆች ሁሉ በፍጥነት አደረሱ።'),
  ('e2fe16fb-85b3-5b0b-ac45-722af599f725', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 14, 14, 'ከዚያም በኋላ ለራሳቸውና ከእነርሱ ጋር ላሉ ለካህናቱ አዘጋጁ፤ የአሮንም ልጆች ካህናቱ የሚቃጠለውን መሥዋዕትና ስቡን ለማቅረብ እስከ ሌሊት ድረስ ይሠሩ ነበርና ስለዚህ ሌዋውያን ለራሳቸውና ለወንድሞቻቸው ለአሮን ልጆች ለካህናቱ አዘጋጁ።'),
  ('ed0e434b-51ea-53a2-a445-975682e64a2e', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 15, 15, 'የአሳፍም ልጆች መዘምራን እንደ ዳዊት፥ እንደ አሳፍም፥ እንደ ኤማንም የንጉሡም ባለ ራእይ እንደ ነበረው እንደ ኤዶትም ትእዛዝ በየስፍራቸው ነበሩ፤ በረኞቹም በሮቹን ሁሉ ይጠብቁ ነበር፤ ወንድሞቻቸውም ሌዋውያን ያዘጋጁላቸው ነበርና ከአገልግሎታቸው ይርቁ ዘንድ አያስፈልጋቸውም ነበር።'),
  ('bf463b83-2a09-5285-a93b-c85afff4523e', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 16, 16, 'እንደ ንጉሡም እንደ ኢዮስያስ ትእዛዝ በእግዚአብሔር መሠዊያ ላይ የሚቃጠለውን መሥዋዕት ያቀርቡ ዘንድ፥ ፋሲካውንም ያደርጉ ዘንድ፥ የእግዚአብሔር አገልግሎት ሁሉ በዚያ ቀን ተዘጋጀ።'),
  ('f6655a41-2515-5747-a947-c6d8e6611f3f', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 17, 17, 'የተገኙትም የእስራኤል ልጆች በዚያ ቀን ፋሲካውን፥ ሰባት ቀንም የቂጣውን በዓል አደረጉ።'),
  ('ee61990f-5517-5fd9-a553-a6444cdaf4c0', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 18, 18, 'ከነቢዩም ከሳሙኤል ዘመን ጀምሮ እንደዚህ ያለ ፋሲካ በእስራኤል ዘንድ ከቶ አልተደረገም፤ ከእስራኤልም ነገሥታት ሁሉ ኢዮስያስና ካህናቱ፥ ሌዋውያኑም፥ በዚያም የተገኙ የይሁዳና የእስራኤል ሰዎች ሁሉ፥ በኢየሩሳሌምም የሚኖሩት እንዳደረጉት ያለ ፋሲካ ያደረገ የለም።'),
  ('6a31cb12-283b-573a-af31-95021bc43344', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 19, 19, 'ይህም ፋሲካ ኢዮስያስ በነገሠ በዐሥራ ስምንተኛው ዓመት ተደረገ።'),
  ('e1c634c3-6e0f-5a05-a2db-a9a414cbaa8b', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 20, 20, 'ከዚህም ሁሉ በኋላ፥ ኢዮስያስም ቤተ መቅደሱን ካሰናዳ በኋላ፥ የግብጽ ንጉሥ ፈርዖን ኒካዑ በኤፍራጥስ ወንዝ አጠገብ የአሦርን ንጉሥ ይዋጋ ዘንድ ወጣ፤ ኢዮስያስም ሊጋጠመው ወጣ።'),
  ('98dc7ed7-3039-5840-a983-e97d929c280f', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 21, 21, 'እርሱም፥ “የይሁዳ ንጉሥ ሆይ፥ ከአንተ ጋር ምን አለኝ? በምዋጋበት በሌላ ቤት ላይ ነው እንጂ በአንተ ላይ ዛሬ አልመጣሁም፤ እግዚአብሔርም እንድቸኩል አዝዞኛል፤ ከእኔ ጋር ያለው እግዚአብሔር እንዳያጠፋህ ተጠንቀቅ” ብሎ መልእክተኞችን ላከበት።'),
  ('8e5e22af-466e-5e48-abd9-2113c4872d12', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 22, 22, 'ኢዮስያስ ግን ይዋጋው ዘንድ ተጽናና እንጂ ፊቱን ከእርሱ አልመለሰም፤ በእግዚአብሔርም አፍ የተነገረውን የኒካዑን ቃል አልሰማም፤ በመጊዶንም ሸለቆ ይዋጋ ዘንድ መጣ።'),
  ('1fefce7d-e248-54e4-a2c0-dbaaea491915', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 23, 23, 'ቀስተኞቹም ንጉሡን ኢዮስያስን ወጉት፤ ንጉሡም ብላቴኖቹን፥ “እጅግ ቈስያለሁና ከሰልፉ ውስጥ አውጡኝ” አላቸው።'),
  ('98e762dd-20fd-585d-aafa-bc3f6194755e', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 24, 24, 'ብላቴኖቹም ከሰረገላው አውርደው ለእርሱ በነበረው በሁለተኛው ሰረገላ ውስጥ አስቀመጡት፤ ወደ ኢየሩሳሌምም አመጡት፤ እርሱም በዚያ ሞተ፤ በአባቶቹም መቃብር ተቀበረ፤ ይሁዳና ኢየሩሳሌምም ሁሉ ለኢዮስያስ አለቀሱ።'),
  ('182d8fc3-fa1c-5f30-a8df-357c4b3401fe', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 25, 25, 'ኤርምያስም ለንጉሡ ለኢዮስያስ የልቅሶ ግጥም ገጠመለት፤ እስከ ዛሬም ድረስ ወንዶችና ሴቶች መዘምራን ሁሉ በልቅሶ ግጥማቸው ስለ ኢዮስያስ ይናገሩ ነበር፤ ይህም በእስራኤል ሁሉ ዘንድ ወግ ሆኖ በልቅሶ ግጥም ተጽፎአል።'),
  ('96358d8b-d204-5537-ace0-c3f3d6ed0136', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 26, 26, 'የቀሩትም የኢዮስያስ ነገሮች፥ በእግዚአብሔርም ሕግ እንደ ተጻፈ ያደረገው ቸርነት፥'),
  ('e85cf6ec-4915-5b78-a38d-16fb23ae8ed7', 'c39c903b-f1e1-500d-adb2-e4ca31f0884d', 'ab0beb6f-78de-5991-a4cc-65ed2ed494b3', 27, 27, 'የፊተኛውና የኋለኛውም ነገሩ፥ እነሆ፥ በእስራኤልና በይሁዳ ነገሥታት መጽሐፍ ተጽፈዋል።'),
  ('82ceda5d-c58b-5816-a5a7-4c58024c6c97', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 1, 1, 'የሀገሩም ሰዎች የኢዮስያስን ልጅ ኢዮአክስን ወስደው በአባቱ ፋንታ በኢየሩሳሌም አነገሡት።'),
  ('642870c5-1693-5191-acc5-069ff7767c5f', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 2, 2, 'ኢዮአክስም መንገሥ በጀመረ ጊዜ የሃያ ሦስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ሦስት ወር ነገሠ። 2 ‘ሀ’ የእናቱም ስም ከሎቤና የኤርምያስ ልጅ አሚጣል ነበረች። 2 ‘ለ’ አባቶቹ እንደ ሠሩት ሁሉ በእግዚአብሔር ፊት ክፉ ሥራን ሠራ። በኢየሩሳሌምም እንዳይነግሥ በኤማት ምድር በዴብላታ ፈርዖን ኒካዑ ማርኮ አሰረው።'),
  ('b6103fab-a8bb-514e-ac20-0367d02abd01', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 3, 3, 'ንጉሡም ወደ ግብፅ ወሰደው፤ በሀገሩም ላይ መቶ መክሊት ብርና አንድ መክሊት ወርቅ ግብር ጣለበት።'),
  ('03ae960f-ba27-59f7-ab7c-052384eff505', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 4, 4, 'የግብፅም ንጉሥ ፈርዖን ኒካዑ የይሁዳን ንጉሥ የኢዮስያስን ልጅ ኤልያቄምን በአባቱ ፋንታ በይሁዳና በኢየሩሳሌም ላይ አነገሠ፤ ስሙንም ኢዮአቄም ብሎ ለወጠ፤ ፈርዖን ኒካዑም ወንድሙን ኢዮአክስን ይዞ ወደ ግብፅ ወሰደው። በዚያም ሞተ። 4 ‘ሀ’ ወርቅንና ብርን ለፈርዖን ሰጠ። በዚያን ጊዜም ምድር በፈርዖን ትእዛዝ ብር መገበሯን ጀመረች። 4 ‘ለ’ እያንዳንዱም እንደሚችለው ለፈርዖን ኒካዑ እንዲገብር ከሀገሪቱ ሕዝብ ወርቅንና ብርን ጠየቀ።'),
  ('f5516903-c1b2-5dde-a658-ecd532f3f6b7', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 5, 5, 'ኢዮአቄምም መንገሥ በጀመረ ጊዜ የሃያ አምስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ አንድ ዓመት ነገሠ፤ እናቱም ዘካራ የምትባል የኔሬያሳ ልጅ የራማ ሴት ነበረች፤ አባቶቹም እንዳደረጉ በአምላኩ በእግዚአብሔር ፊት ክፉ አደረገ። 5 ‘ሀ’ በእነዚያም ወራት የባቢሎን ንጉሥ ናቡከደነፆር ወደዚያ ሀገር መጣና ሦስት ዓመት ተገዛለት። ከእርሱም ከዳ።'),
  ('3490a51c-d41e-5dac-aa48-fd1d296ed90e', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 6, 6, 'የባቢሎንም ንጉሥ ናቡከደነፆር በእርሱ ላይ ወጥቶ ወደ ባቢሎን ይወስደው ዘንድ በሰንሰለት አሰረው።'),
  ('a82a40ba-32ad-5b48-aeae-312d494d996c', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 7, 7, 'ናቡከደነፆርም ከእግዚአብሔር ቤት ዕቃ አያሌውን አውጥቶ ወደ ባቢሎን ወሰደ፤ በባቢሎንም በጣዖቱ ቤት ውስጥ አኖረው።'),
  ('1513ce8f-d5b0-5f06-a82f-5c3170d2541d', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 8, 8, 'የቀሩትም የኢዮአቄም ነገሮች፥ ያደረገውም ርኵሰት፥ በእርሱም የተገኘው ሁሉ፥ እነሆ፥ በእስራኤልና በይሁዳ ነገሥታት መጽሐፍ ተጽፈዋል፤ ኢዮአቄምም እንደ አባቶቹ አንቀላፋ፤ ከአባቶቹም ጋር በጋኖዛን ከተማ ተቀበረ። ልጁም ኢኮንያን ከእርሱ ቀጥሎ ነገሠ።'),
  ('1b6d450b-82eb-573b-a460-d5c5eb0f5ed3', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 9, 9, 'ኢኮንያንም መንገሥ በጀመረ ጊዜ የዐሥራ ስምንት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ሦስት ወር ከዐሥር ቀን ነገሠ፤ በእግዚአብሔርም ፊት ክፉ አደረገ።'),
  ('939cea90-00c2-51d4-a0c1-b35b1cd85a62', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 10, 10, 'ዓመቱም ባለፈ ጊዜ ንጉሡ ናቡከደነፆር ልኮ ወደ ባቢሎን ወሰደው፤ የከበረውንም የእግዚአብሔርን ቤት ዕቃ ከእርሱ ጋር አስወሰደ፤ የአባቱን የኢዮአቄምን ወንድም ሴዴቅያስን በይሁዳና በኢየሩሳሌም ላይ አነገሠ።'),
  ('75acc583-986e-5023-a7a7-18b4f6294cbd', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 11, 11, 'ሴዴቅያስም መንገሥ በጀመረ ጊዜ የሃያ አንድ ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ አንድ ዓመት ነገሠ።'),
  ('496ff35f-eb1c-5ad4-a8cb-24000688a906', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 12, 12, 'በአምላኩም በእግዚአብሔር ፊት ክፉ አደረገ፤ ከነቢዩ ከኤርምያስ ፊት፥ ከእግዚአብሔርም ቃል የተነሣ አላፈረም።'),
  ('223ada58-7d8a-5835-ad24-7dadc76e36af', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 13, 13, 'ደግሞም በእግዚአብሔር ስም አምሎት በነበረው በንጉሡ በናቡከደነፆር ላይ ዐመፀ፤ ወደ እስራኤልም አምላክ ወደ እግዚአብሔር እንዳይመለስ አንገቱን አደነደነ፤ ልቡንም አጠነከረ።'),
  ('1b0bdc8a-70e6-52c8-ac85-740c4afce7e5', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 14, 14, 'የይሁዳም ታላላቅ ሰዎች ካህናቱና የሀገሩም ሕዝብ በአሕዛብ ርኵሰት ሁሉ መተላለፍን አበዙ፤ በኢየሩሳሌምም ያለውን የእግዚአብሔርን ቤት አረከሱ።'),
  ('c1079d52-bd54-5803-a09f-a3052f867f64', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 15, 15, 'የአባቶቻቸውም አምላክ እግዚአብሔር ለሕዝቡና ለማደሪያው ስላዘነ ማለዳ ተነሥቶ በነቢያቱ እጅ ወደ እነርሱ ይልክ ነበር።'),
  ('434bb2a3-f71f-5a48-a4f3-c03b0513302f', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 16, 16, 'እነርሱ ግን የእግዚአብሔር ቍጣ በሕዝቡ ላይ እስኪወጣ ድረስ፥ ፈውስም እስከማይገኝላቸው ድረስ፥ በእግዚአብሔር መልእክተኞች ይሳለቁ፥ ቃሉንም ያቃልሉ፥ በነቢያቱም ላይ ያፌዙ ነበር።'),
  ('ae114253-754c-59e1-adc1-abed7a847d80', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 17, 17, 'ስለዚህም የከለዳውያንን ንጉሥ አመጣባቸው፤ እርሱም ጐልማሶቻቸውን በቤተ መቅደሱ ውስጥ በሰይፍ ገደላቸው፤ለንጉሣቸው ለሴዴቅያስም አልራራለትም፤ ደናግሉንም አልማረም፤ ሽማግሌዎቻቸውንም ወሰዳቸው፤ ሁሉንም እግዚአብሔር በእጁ አሳልፎ ሰጠው።'),
  ('da036d20-8a63-53d9-a765-508c7f88d3ea', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 18, 18, 'የእግዚአብሔርንም ቤት ዕቃ ሁሉ፥ ታላቁንና ታናሹን፥ የእግዚአብሔርንም ቤት መዝገብ፥ የንጉሡንም ቤት መዝገብ፥ የአለቆቹንም ቤት መዝገብ፥ እነዚህን ሁሉ ወደ ባቢሎን ወሰደ።'),
  ('14a6b6be-5a86-5d08-a3de-2545d3168d3a', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 19, 19, 'የእግዚአብሔርንም ቤተ መቅደስ አቃጠለ፤ የኢየሩሳሌምንም ቅጥር አፈረሰ፤ አዳራሾችዋንም በእሳት አቃጠለ፤ መልካሙንም ዕቃዋን ሁሉ አጠፋ።'),
  ('027b0143-aa4f-5439-a4e3-d8c2614ae8ad', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 20, 20, 'የተረፉትንም ወደ ባቢሎን ማረካቸው፤ የሜዶንም ንጉሥ እስኪነግሥ ድረስ ለንጉሡና ለልጆቹ ባሪያዎች ሆኑ፤'),
  ('4ba22ef3-9c50-55e7-a491-26ecd1dcde35', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 21, 21, 'በኤርምያስ አፍ የተነገረው የእግዚአብሔር ቃል እንዲፈጸም፥ ምድሪቱ ሰንበትን በማድረግዋ እስክታርፍ ድረስ፥ በተፈታችበትም ዘመን ሁሉ፥ ሰባ ዓመት እስኪፈጸም ድረስ፥ ሰንበትን አገኘች።'),
  ('9274a372-6ed2-50c8-a9d9-f4f0bd1a6eca', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 22, 22, 'በኤርምያስም አፍ የተናገረው የእግዚአብሔር ቃል ከተፈጸመ በኋላ በፋርስ ንጉሥ በቂሮስ በመጀመሪያው ዓመት እግዚአብሔር የፋርስን ንጉሥ የቂሮስን መንፈስ አስነሣ፤ በመንግሥቱም ሁሉ አዋጅ ይነገር ዘንድ በጽሕፈት እንዲህ ሲል አዘዘ፤'),
  ('883d3234-06a7-5799-adab-645fefa798e5', 'ac77930a-d600-58cd-ab37-182d44515b2a', '19a790e9-1827-5098-a7cc-49dd327fdeae', 23, 23, '“የፋርስ ንጉሥ ቂሮስ እንዲህ ይላል፦ የሰማይ አምላክ እግዚአብሔር የምድርን መንግሥታት ሁሉ ሰጥቶኛል፤ እርሱም በይሁዳ ባለችው በኢየሩሳሌም ቤትን እሠራለት ዘንድ አዝዞኛል፤ ከሕዝቡም ሁሉ በእናንተ ዘንድ ማንም ቢሆን አምላኩ እግዚአብሔር ከእርሱ ጋር ይሁን፤ እርሱም ይውጣ።”'),
  ('551f5817-a6c3-50c4-ac5e-62ed4529238b', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 1, 1, 'የእስራኤል ልጆች ከግብፅ በወጡበት በመጀመሪያው ዘመን እንዲህ ሆነ። በሦስተኛው ወር፥ ያ ወር በባተ በዐሥራ ስድስተኛው ቀን፥ እግዚአብሔር፥ “ከእኔ ዘንድ ወደዚህ ተራራ ውጣ፤ በጻፍኸውም መጠን ልብ ታስደርጋቸው ዘንድ ሕጉና ሥርዐቱ የተጻፉባቸውን ሁለቱን የዕንቍ ጽላት እሰጥሀለሁ” ብሎ ለሙሴ ተናገረ።'),
  ('31d28e80-2c1f-5240-a271-c0a648d87a1c', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 2, 2, 'ሙሴም ወደ እግዚአብሔር ተራራ ወጣ። የእግዚአብሔርም ብርሃን በደብረ ሲና ተገለጠ። ስድስት ቀንም ደመና ጋረደው።'),
  ('d1122d73-5911-5d00-a28f-00e81ad24997', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 3, 3, 'በሰባተኛዪቱም ቀን በደመና መካከል ሆኖ ሙሴን ጠራው፤ የእግዚአብሔርም ብርሃን በተራራው ራስ ላይ እንደ እሳት ሲነድድ አየ።'),
  ('88a91a4d-20a8-5a85-a2b5-311de91a52a8', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 4, 4, 'ሙሴም በተራራው ላይ አርባ ቀንና አርባ ሌሊት ተቀመጠ። እግዚአብሔርም ያለፈውንና የሚመጣውን፥ ሕጉ የሚጠበቅበትንና አምልኮቱ የሚነገርበትን፥ የዘመኑን ሁሉ አከፋፈል ነገር አመለከተው።'),
  ('2ef0e8d1-f615-52ab-a667-bdb025214baa', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 5, 5, 'እንዲህም አለው፥ “በዚህ ተራራ ላይ እኔ በምነግርህ ነገር ሁሉ ልብህን አኑር። በአንተና በእኔ መካከል በደብረ ሲና ዛሬ ለልጆቻቸው የሚደረገውን፥ እኔ የምሠራውን ሥርዐት ለማስፈረስ ስለ ሠሩት ኀጢአት ሁሉ እንደ ተለየሁአቸው ልጆቻቸው ይሰሙ ዘንድ በመጽሐፍ ጻፈው።”'),
  ('58bec477-60fe-5794-a2cb-42d4824ba9c8', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 6, 6, 'ይህ ሁሉ ነገር በእነርሱ ላይ በመጣባቸው ጊዜ እንዲህ ይናገራል። በፈረድሁባቸው ሁሉ፥ በሥራቸውም ሁሉ ከእነርሱ ይልቅ እኔ እውነተኛ እንደ ሆንሁ ያውቃሉ፤ ከእነርሱም ጋር ያለሁ እንደ ሆንሁ ያውቃሉ።'),
  ('b829db78-8bc3-52af-a507-b65a042a1587', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 7, 7, 'አንተም እኔ ዛሬ የነገርሁህን ይህን ሁሉ ነገር ጻፍ። እኔ ቍጣቸውን አውቃለሁና፥ ማርና ወተትን የምታስገኝ ሀገርን ለልጆቻችሁ እሰጣለሁ ብዬ ለአብርሃምና ለይስሐቅ ለያዕቆብም ወደማልሁላቸው ሀገር ሳላገባቸው አንገታቸው ደንዳና እንደ ሆነ አውቃለሁና፥ በልተውና ጠግበው ከመከራቸው ሁሉ ወደማያድናቸው ወደ ልዩ ጣዖት ይመለሳሉና።'),
  ('b3c86426-de07-5ecb-a1c3-c03ac784460a', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 8, 8, 'ይህች መጽሐፍ በእነርሱ ላይ ሥርዐት ትሁንባቸው። እኔ የማዝዛቸውን ትእዛዜን ሁሉ ይዘነጋሉና፥ አሕዛብንም ተከትለው ወደ ኀጢአታቸው ይሄዳሉና፥ ለጣዖቶቻቸውም ይገዛሉና፤ በእነርሱም መከራንና ጭንቅን፥ ጦርንም ለማምጣት መሰናክል ይሆንባቸዋል።'),
  ('941fdf64-121b-5e12-a295-5d3623164894', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 9, 9, '“ብዙ ሰዎች ይጠፋሉ፥ ተይዘውም በጠላቶቻቸው እጅ ይወድቃሉ። ሥርዐቴንና ትእዛዜን፥ የቃል ኪዳኔንም በዓላት፥ ሰንበታትንም፥ በመካከላቸውም የለየሁትን ቅድሳቴን፤ ስሜ በእርሱ ይጠራ ዘንድ፥ ያድርበትም ዘንድ በምድር መካከል ያከበርሁትን ድንኳኔንና መቅደሴን ትተዋልና።'),
  ('a4d94a91-cab9-5a4d-afc6-88e1c8a8b2c8', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 10, 10, 'በዓላትን፥ መስገጃ ዛፍንና ጣዖትን ሠርተው ለመሳት እየራሳቸው ይሰግዳሉ። ልጆቻቸውንም ለአጋንንት፥ በልቡናቸው ስተው ለሠሩትም ጣዖት ሁሉ ይሠዋሉ፤ አዳኝባቸውም ዘንድ ወደ እነርሱ ምስክሮችን እልካለሁ። ነገር ግን አይሰሙም፤ ምስክሮችንም ይገድላሉ።'),
  ('9d977a35-380e-50ea-a3f8-c59a8bd4ea2b', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 11, 11, 'ሕግን የሚሹ ሰዎችንም ይገድሉአቸዋል፤ ከሀገርም አስወጥተው ይሰድዱአቸዋል፤ ሁሉንም ያቦዝናሉ፤ በዐይኖችም ፊት ክፉ ሥራ መሥራትን ይጀምራሉ።'),
  ('8efe23f5-2ae0-5ccb-ad8a-1b065814250b', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 12, 12, 'ከእነርሱም ፊቴን እመልሳለሁ፤ ለመበዝበዝና ለመማረክ፥ ለመዘረፍም ይሆኑ ዘንድ በአሕዛብ እጅ አሳልፌ እሰጣቸዋለሁ፤ ከኢየሩሳሌምም መካከል አርቃቸዋለሁ፤ በአሕዛብም መካከል እበትናቸዋለሁ።'),
  ('5c49fd17-3754-5e11-a593-8104a70b2021', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 13, 13, '“ሕጌን ሁሉ፥ ትእዛዜንም ሁሉ፥ ፍርዴንም ሁሉ፥ ሥርዐቴንም ሁሉ ይዘነጋሉ። የወሩን መባቻና ሰንበትን፥ በዓሉንና ኢዮቤልዩን፥ ሥርዐቱንም፥ ይዘነጋሉ።'),
  ('ec4ad966-f969-5cd4-aa46-6f9fb3b2762d', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 14, 14, 'ከዚህም በኋላ በፍጹም ልባቸው፥ በፍጹም ነፍሳቸው፥ በፍጹም ኀይላቸውም ከአሕዛብ መካከል ወደ እኔ ይመለሳሉ። እኔም ከአሕዛብ ሁሉ መካከል እሰበስባቸዋለሁ።'),
  ('a5bb8cbd-ca33-5768-a0bd-69856ac0a5a3', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 15, 15, 'እገለጥላቸው ዘንድ ይፈልጉኛል። በፍጹም ልባቸውና በፍጹም ነፍሳቸውም በፈለጉኝ ጊዜ፥ እኔ በእውነት ብዙ ሰላምን እገልጥላቸዋለሁ፤ በፍጹም ልቤና በፍጹም ነፍሴ ወደ ቀና ሕግ እመልሳቸዋለሁ።'),
  ('e3085ea2-65ee-5238-ad88-f7b273484999', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 16, 16, 'ለበረከት ይሆናሉ፤ ለመርገምም አይደለም፤ ራስ ይሆናሉ፤ ጅራትንም አይደለም፤ በመካከላቸውም መቅደሴን እሠራለሁ፤ ከእነርሱም ጋር እኖራለሁ፤ አምላካቸውም እሆናቸዋለሁ፤ እነርሱም በሚገባ በእውነት ሕዝቤ ይሆናሉ፤ እኔም እግዚአብሔር አምላካቸው ነኝና አልተዋቸውም፤ አልለያቸውምም።”'),
  ('f6c1d68d-3133-52de-afbf-47c3eddc74bc', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 17, 17, 'ሙሴም በግንባሩ ተደፍቶ ጸለየ፤ እንዲህም አለ፥ “አቤቱ፥ አምላኬ፥ በልቡናቸው ስሕተት ይሄዱ ዘንድ ርስትህ የሆኑ ወገኖችህን አትተው። ይገዙአቸውም ዘንድ፥ አንተንም እንዲበድሉ ያደርጓቸው ዘንድ በጠላቶቻቸው በአሕዛብ እጅ አትጣላቸው።'),
  ('3d36d518-c48e-5304-a205-03d714965165', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 18, 18, 'አቤቱ፥ ይቅርታህ በወገኖችህ ላይ ከፍ ከፍ ይበል፤ የቀና ልቡናንም ፍጠርላቸው። በፊትህ ለማጣላት ፥ ከባለምዋልነትህም ይጠፉ ዘንድ ከእውነተኛ ሥራ ሁሉ ለማሰነካከል የዲያብሎስ መንፈስ አይሠልጥንባቸው።'),
  ('d1553244-59cb-5eda-aada-7ec26756b5de', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 19, 19, 'እነርሱስ በታላቅ ኀይልህ ከግብፅ ሰዎች እጅ ያዳንኻቸው ወገኖችህና ማደሪያዎችህ ናቸው። ንጹሕ ልቡናን ፍጠርላቸው። የተቀደሰ መንፈስንም አሳድርባቸው፤ ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ በኀጢአታቸው አይሰነካከሉ።”'),
  ('14fe3352-46fb-5fe7-afb7-b984b8fb1dc3', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 20, 20, 'እግዚአብሔርም ሙሴን እንዲህ አለው፥ “እኔ ክርክራቸውንና አሳባቸውን አውቃለሁ፤ አንገታቸው ደንዳና ነው። ኀጢአታቸውንና የአባቶቻቸውን ኀጢአት እስኪያውቁ ድረስ አይሰሙም።'),
  ('e5f89336-8148-5350-a391-c856bed3a595', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 21, 21, 'ከዚህም በኋላ በፍጹም ቅንነት፥ በፍጹም ልቡናና በፍጹም ሰውነት ወደ እኔ ይመለሳሉ። የልቡናቸውን ቈላፍነትና የዘራቸውን ልቡና ቈላፍነት እቈርጣለሁ። ንጹሕ ልቡናንም እፈጥርላቸዋለሁ።'),
  ('9a7e1cbd-56d1-56c5-a9b3-7093b7498943', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 22, 22, 'ከዚያች ቀን ጀምሮ እስከ ዘለዓለም ድረስ እኔን ከመከተል ወደ ኋላ እንዳይመለሱ አነጻቸዋለሁ፤ ልቡናቸውም እኔን ትከተላለች፤ ትእዛዜንም ሁሉ ይፈጽማሉ።'),
  ('4d197e61-ab64-51de-a1cc-46c043dc6157', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 23, 23, 'አባት እሆናቸዋለሁ፤ እነርሱም ልጆች ይሆኑኛል፤ ሁሉም የሕያው አምላክ ልጆች ይባላሉ። መልአክ ሁሉ፥ ሰውም ሁሉ ያውቃቸዋል። እነርሱ ልጆች እንደ ሆኑ፥ እኔም በሚገባና በእውነት አባታቸው እንደ ሆንሁ፥ እንደምወድዳቸውም ያውቋቸዋል።'),
  ('86ac5532-c3ce-5acf-a872-94fe4064aa31', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 24, 24, 'አንተም በዚህ ተራራ ላይ እኔ የምነግርህን ይህን ነገር ሁሉ፥ የፊቱንና የኋላውን፥ ይመጣ ዘንድ ያለውንም፥ ሕጉና አምልኮቱም በሚነገሩበት በዓመቱ ቍጥር እስከ ዘለዓለም ድረስ የሚሆነውን የዘመኑን አከፋፈል ሁሉ፥ እኔም ወርጄ በዘመኑ ሁሉ ከእነርሱ ጋር እስክኖር ድረስ የሚደረገውን ሁሉ ጻፍ።”'),
  ('be9b40c1-4a07-591a-ac8e-72fd2ae4c67c', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 25, 25, 'መልአከ ገጹንም እንዲህ አለው፥ “ዓለም ከተፈጠረ ጀምሮ ለዘለዓለም የምመሰገንበት ቤተ መቅደስ በመካከላቸው እስኪሠራ ድረስ እግዚአብሔርም ለሁሉ እስኪታይ ድረስ የሚሆነውን ለሙሴ ጻፍለት።'),
  ('c5c4a912-6c1b-50d5-a2c2-5ee054326df8', '338674e8-7c9f-500b-a803-e95d09f9457f', '4d7cfa62-5216-5974-a454-df374a73a674', 26, 26, 'እኔ የእስራኤል አምላክ እንደ ሆንሁ፥ ለያዕቆብ ልጆች ሁሉ አባት እንደ ሆንሁ፤ በደብረ ጽዮንም ለዘለዓለም ንጉሥ እንደ ሆንሁ ሁሉ ያውቃል፤ ጽዮን ኢየሩሳሌምም የከበረች ትሆናለች።”')
